\ =====================================================================
\  persistence-adapter.f - Library vertical slices over neutral persistence
\ =====================================================================
\  This is deliberately a Library-owned adapter.  Library records, ordered
\  meanings, history locators, membership edges, and content ownership stay
\  here; the neutral layers see only byte keys, opaque values, checked pages,
\  and immutable blobs.  The adapter does not make Library meaningful outside
\  Desk/TUI.  There is one current semantic record layout and one current
\  application-root shape, with no legacy decoder or format dispatch.
\
\  All mutable memory is caller-owned.  A LIBPA descriptor borrows one
\  PSTORE, while each LIBPA-INDEX-WORK permanently borrows the PSTORE work
\  and cold-audit map used to open, query, and mutate that authority.  The
\  fixed neutral audit work is embedded in LIBPA-INDEX-WORK; the page map is
\  externally sized so the workspace does not impose a corpus ceiling.
\  Separate descriptor/work graphs are therefore safely interleavable.
\ =====================================================================

PROVIDED akashic-tui-library-persistence-adapter

\ Preload the independently useful neutral surfaces.  None imports a Library
\ controller, service, repository, applet, or path convention.
REQUIRE ../../../persistence/store.f
REQUIRE ../../../persistence/btree.f
REQUIRE ../../../persistence/blob.f
REQUIRE ../../../persistence/reclaim.f
REQUIRE index-keys.f
REQUIRE document-values.f

PERSIST-S-OK        CONSTANT LIBPA-S-OK
PERSIST-S-ABSENT    CONSTANT LIBPA-S-ABSENT
PERSIST-S-INVALID   CONSTANT LIBPA-S-INVALID
PERSIST-S-CAPACITY  CONSTANT LIBPA-S-CAPACITY
PERSIST-S-IO        CONSTANT LIBPA-S-IO
PERSIST-S-CORRUPT   CONSTANT LIBPA-S-CORRUPT
PERSIST-S-BUSY      CONSTANT LIBPA-S-BUSY
PERSIST-S-CONFLICT  CONSTANT LIBPA-S-CONFLICT
PERSIST-S-UNCERTAIN CONSTANT LIBPA-S-UNCERTAIN
PERSIST-S-NOT-FOUND CONSTANT LIBPA-S-NOT-FOUND
PERSIST-S-FAULT     CONSTANT LIBPA-S-FAULT

0x4C49425041303131 CONSTANT _LIBPA-MAGIC       \ "LIBPA011"

\ The sole lexical byte allocation is immutable serialized format magic.
CREATE _LIBPA-ROOT-MAGIC
65 C, 75 C, 76 C, 80 C, 65 C, 48 C, 49 C, 50 C,  \ "AKLPA012"

\ The sole current application-root payload within one neutral checked page.
\ Physical PSTORE generation is deliberately separate from the logical
\ generation and mutation sequence recorded here.
 0 CONSTANT _LIBPAR-MAGIC
 8 CONSTANT _LIBPAR-FLAGS
16 CONSTANT _LIBPAR-LOGICAL-GENERATION
24 CONSTANT _LIBPAR-MUTATION-SEQUENCE
32 CONSTANT _LIBPAR-DOCUMENT-COUNT
40 CONSTANT _LIBPAR-COLLECTION-COUNT
48 CONSTANT _LIBPAR-MEMBERSHIP-COUNT
56 CONSTANT _LIBPAR-BOOTSTRAP-ID
88 CONSTANT _LIBPAR-ROOTS
1048 CONSTANT _LIBPAR-RECLAIM-STATE
1176 CONSTANT _LIBPAR-RESERVED

\ Largest current Library segment payload.  Content bytes never inhabit this
\ workspace; they stream through PBLOB.
0x4C49425041444F43 CONSTANT _LIBPA-DOCUMENT-MAGIC  \ "LIBPADOC"
  0 CONSTANT _LIBPAD-MAGIC
  8 CONSTANT _LIBPAD-PAYLOAD-U
 16 CONSTANT _LIBPAD-CONTENT-REF
 40 CONSTANT _LIBPAD-METADATA-BLOB
112 CONSTANT _LIBPAD-ENTRY
_LIBPAD-ENTRY LIB-ENTRY-SIZE + CONSTANT LIBPA-DOCUMENT-RECORD-SIZE
\ PSTORE's checked-record buffer also carries neutral PBLOB chunk records.
\ This is transport workspace, not a semantic Library content ceiling.
LIBPA-DOCUMENT-RECORD-SIZE PBLOB-CHUNK-SIZE MAX
    CONSTANT LIBPA-RECORD-MAX

\ Collection semantics live in model.f.  Adapter spellings remain thin
\ vocabulary bridges for query/repository code; there is only one layout.
LIB-COLLECTION-SIZE CONSTANT LIBPA-COLLECTION-SIZE

0x4C49425041434F4C CONSTANT _LIBPA-COLLECTION-MAGIC  \ "LIBPACOL"
  0 CONSTANT _LIBPACR-MAGIC
  8 CONSTANT _LIBPACR-PAYLOAD-U
 16 CONSTANT _LIBPACR-COLLECTION
_LIBPACR-COLLECTION LIBPA-COLLECTION-SIZE +
    CONSTANT LIBPA-COLLECTION-RECORD-SIZE

\ Descriptor: borrowed PSTORE and last adapter status only.
 0 CONSTANT _LIBPA-D-MAGIC
 8 CONSTANT _LIBPA-D-SELF
16 CONSTANT _LIBPA-D-STORE
24 CONSTANT _LIBPA-D-STATUS
32 CONSTANT LIBPA-SIZE

: _LIBPA-D.MAGIC   ( adapter -- a ) _LIBPA-D-MAGIC + ;
: _LIBPA-D.SELF    ( adapter -- a ) _LIBPA-D-SELF + ;
: _LIBPA-D.STORE   ( adapter -- a ) _LIBPA-D-STORE + ;
: _LIBPA-D.STATUS  ( adapter -- a ) _LIBPA-D-STATUS + ;

: _LIBPA-DROP3  ( x1 x2 x3 -- ) 2DROP DROP ;
: _LIBPA-DROP4  ( x1 x2 x3 x4 -- ) 2DROP 2DROP ;
: _LIBPA-DROP5  ( x1 x2 x3 x4 x5 -- ) 2DROP 2DROP DROP ;
: _LIBPA-DROP6  ( x1 x2 x3 x4 x5 x6 -- ) 2DROP 2DROP 2DROP ;
: _LIBPA-DROP7  ( x1 x2 x3 x4 x5 x6 x7 -- )
    2DROP 2DROP 2DROP DROP ;
: _LIBPA-DROP8  ( x1 x2 x3 x4 x5 x6 x7 x8 -- )
    2DROP 2DROP 2DROP 2DROP ;
: _LIBPA-DROP9  ( x1 x2 x3 x4 x5 x6 x7 x8 x9 -- )
    2DROP 2DROP 2DROP 2DROP DROP ;

: _LIBPA-BYTES=  ( a b u -- flag )
    DUP 0< IF DROP 2DROP 0 EXIT THEN
    0 ?DO
        2DUP I + C@ SWAP I + C@ <> IF
            2DROP 0 UNLOOP EXIT
        THEN
    LOOP
    2DROP -1 ;

: _LIBPA-ZERO?  ( a u -- flag )
    DUP 0< IF 2DROP 0 EXIT THEN
    0 ?DO DUP I + C@ IF DROP 0 UNLOOP EXIT THEN LOOP
    DROP -1 ;

: _LIBPA-PERSIST>STATUS  ( persist-status -- adapter-status )
    DUP PERSIST-S-OK < OVER PERSIST-S-FAULT > OR IF
        DROP LIBPA-S-FAULT
    THEN ;

: _LIBPA-LIB>STATUS  ( library-status -- adapter-status )
    CASE
        LIB-S-OK          OF LIBPA-S-OK ENDOF
        LIB-S-INVALID     OF LIBPA-S-INVALID ENDOF
        LIB-S-CAPACITY    OF LIBPA-S-CAPACITY ENDOF
        LIB-S-CHECKSUM    OF LIBPA-S-CORRUPT ENDOF
        LIB-S-UNSUPPORTED OF LIBPA-S-CORRUPT ENDOF
        LIB-S-INTEGRITY   OF LIBPA-S-CORRUPT ENDOF
        LIBPA-S-FAULT SWAP
    ENDCASE ;

\ ---------------------------------------------------------------------
\ Initialization, validation, and public status
\ ---------------------------------------------------------------------

: LIBPA-VALID?  ( adapter -- flag )
    DUP 0= IF DROP 0 EXIT THEN
    DUP LIBPA-SIZE MSPAN-NONWRAPPING? 0= IF DROP 0 EXIT THEN
    DUP _LIBPA-D.MAGIC @ _LIBPA-MAGIC <> IF DROP 0 EXIT THEN
    DUP _LIBPA-D.SELF @ OVER <> IF DROP 0 EXIT THEN
    DUP _LIBPA-D.STATUS @ DUP LIBPA-S-OK <
        SWAP LIBPA-S-FAULT > OR IF DROP 0 EXIT THEN
    DUP _LIBPA-D.STORE @ DUP PSTORE-VALID? 0= IF 2DROP 0 EXIT THEN
    PSTORE-SIZE ROT LIBPA-SIZE MSPAN-OVERLAP? 0= ;

: LIBPA-INIT  ( store adapter -- status )
    >R
    DUP PSTORE-VALID? 0= IF DROP R> DROP LIBPA-S-INVALID EXIT THEN
    R@ 0= IF DROP R> DROP LIBPA-S-INVALID EXIT THEN
    R@ LIBPA-SIZE MSPAN-NONWRAPPING? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ LIBPA-SIZE 2 PICK PSTORE-SPAN-DISJOINT? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP PSTORE-SIZE R@ LIBPA-SIZE MSPAN-OVERLAP? IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ LIBPA-SIZE 0 FILL
    _LIBPA-MAGIC R@ _LIBPA-D.MAGIC !
    R@ R@ _LIBPA-D.SELF !
    DUP R@ _LIBPA-D.STORE !
    LIBPA-S-OK R@ _LIBPA-D.STATUS !
    DROP R> DROP LIBPA-S-OK ;

: LIBPA-STATUS@  ( adapter -- status )
    DUP LIBPA-VALID? IF _LIBPA-D.STATUS @ ELSE DROP LIBPA-S-INVALID THEN ;

: LIBPA-GENERATION@  ( adapter -- generation|-1 )
    DUP LIBPA-VALID? IF _LIBPA-D.STORE @ PSTORE-GENERATION@ ELSE DROP -1 THEN ;

\ ---------------------------------------------------------------------
\ Domain agreement and alias boundary
\ ---------------------------------------------------------------------

: _LIBPA-PAIR-VALID?  ( entry content -- flag )
    DUP LIB-CONTENT-VALID? 0= IF 2DROP 0 EXIT THEN
    OVER LIB-ENTRY-VALID? 0= IF 2DROP 0 EXIT THEN
    >R
    DUP LIBE.ID R@ LIBCT.ID RID= 0= IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.DOMAIN-REVISION @ R@ LIBCT.DOMAIN-REVISION @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.KIND @ R@ LIBCT.KIND @ <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.MEDIA @ R@ LIBCT.MEDIA @ <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.CURRENT-CONTENT-REVISION @
        R@ LIBCT.CONTENT-REVISION @ <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.CONTENT-U @ R@ LIBCT.DATA-U @ <> IF DROP R> DROP 0 EXIT THEN
    LIBE.CONTENT-DIGEST R@ LIBCT.DIGEST SHA3-256-COMPARE
    R> DROP ;

\ ---------------------------------------------------------------------
\ L11 indexed-slice content locators
\ ---------------------------------------------------------------------
\ A history value names one checked locator record.  Flag zero describes a
\ currently valid LIB-CONTENT and therefore retains its model metadata.  Flag
\ one is deliberately raw immutable content: it proves content larger than the
\ current fixed 64 KiB Library view without pretending that view accepts it.

0x4C494250434E5431 CONSTANT _LIBPA-CONTENT-MAGIC  \ "LIBPCNT1"
0 CONSTANT LIBPA-CONTENT-F-LIBRARY
1 CONSTANT LIBPA-CONTENT-F-RAW

  0 CONSTANT _LIBPAC-MAGIC
  8 CONSTANT _LIBPAC-FLAGS
 16 CONSTANT _LIBPAC-RID
 48 CONSTANT _LIBPAC-DOMAIN-REVISION
 56 CONSTANT _LIBPAC-CONTENT-REVISION
 64 CONSTANT _LIBPAC-KIND
 72 CONSTANT _LIBPAC-MEDIA
 80 CONSTANT _LIBPAC-DATA-U
 88 CONSTANT _LIBPAC-DIGEST
120 CONSTANT _LIBPAC-BLOB
192 CONSTANT _LIBPAC-RESERVED
200 CONSTANT LIBPA-CONTENT-DESCRIPTOR-SIZE

: _LIBPAC.MAGIC             ( descriptor -- a ) _LIBPAC-MAGIC + ;
: _LIBPAC.FLAGS             ( descriptor -- a ) _LIBPAC-FLAGS + ;
: _LIBPAC.RID               ( descriptor -- rid ) _LIBPAC-RID + ;
: _LIBPAC.DOMAIN-REVISION   ( descriptor -- a ) _LIBPAC-DOMAIN-REVISION + ;
: _LIBPAC.CONTENT-REVISION  ( descriptor -- a ) _LIBPAC-CONTENT-REVISION + ;
: _LIBPAC.KIND              ( descriptor -- a ) _LIBPAC-KIND + ;
: _LIBPAC.MEDIA             ( descriptor -- a ) _LIBPAC-MEDIA + ;
: _LIBPAC.DATA-U            ( descriptor -- a ) _LIBPAC-DATA-U + ;
: _LIBPAC.DIGEST            ( descriptor -- digest ) _LIBPAC-DIGEST + ;
: _LIBPAC.BLOB              ( descriptor -- blob ) _LIBPAC-BLOB + ;
: _LIBPAC.RESERVED          ( descriptor -- a ) _LIBPAC-RESERVED + ;

: LIBPA-CONTENT-DESCRIPTOR-VALID?  ( descriptor -- flag )
    DUP 0= IF DROP 0 EXIT THEN
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE MSPAN-NONWRAPPING? 0= IF
        DROP 0 EXIT
    THEN
    DUP _LIBPAC.MAGIC @ _LIBPA-CONTENT-MAGIC <> IF DROP 0 EXIT THEN
    DUP _LIBPAC.RID RID-PRESENT? 0= IF DROP 0 EXIT THEN
    DUP _LIBPAC.CONTENT-REVISION @ 0> 0= IF DROP 0 EXIT THEN
    DUP _LIBPAC.DATA-U @ DUP 0< IF 2DROP 0 EXIT THEN
    OVER _LIBPAC.BLOB PBLOB-TOTAL@ <> IF DROP 0 EXIT THEN
    DUP _LIBPAC.BLOB PBLOB-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPAC.RESERVED @ IF DROP 0 EXIT THEN
    DUP _LIBPAC.FLAGS @ LIBPA-CONTENT-F-LIBRARY = IF
        DUP _LIBPAC.DOMAIN-REVISION @ DUP 0> 0= IF 2DROP 0 EXIT THEN
        OVER _LIBPAC.CONTENT-REVISION @ < IF DROP 0 EXIT THEN
        DUP _LIBPAC.KIND @ 0> 0= IF DROP 0 EXIT THEN
        DUP _LIBPAC.MEDIA @ 0> 0= IF DROP 0 EXIT THEN
        DUP _LIBPAC.DATA-U @ LIB-CONTENT-LENGTH-MAX > IF DROP 0 EXIT THEN
        _LIBPAC.DIGEST RID-PRESENT? EXIT
    THEN
    DUP _LIBPAC.FLAGS @ LIBPA-CONTENT-F-RAW <> IF DROP 0 EXIT THEN
    DUP _LIBPAC.DOMAIN-REVISION @ IF DROP 0 EXIT THEN
    DUP _LIBPAC.KIND @ IF DROP 0 EXIT THEN
    DUP _LIBPAC.MEDIA @ IF DROP 0 EXIT THEN
    DUP _LIBPAC.DIGEST RID-SIZE _LIBPA-ZERO? 0= IF DROP 0 EXIT THEN
    DROP -1 ;

: LIBPA-CONTENT-DESCRIPTOR-COPY  ( source destination -- status )
    OVER LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        2DROP LIBPA-S-INVALID EXIT
    THEN
    DUP 0= IF 2DROP LIBPA-S-INVALID EXIT THEN
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE MSPAN-NONWRAPPING? 0= IF
        2DROP LIBPA-S-INVALID EXIT
    THEN
    LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE LIBPA-S-OK ;

: LIBPA-CONTENT-RAW?  ( descriptor -- flag )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF
        _LIBPAC.FLAGS @ LIBPA-CONTENT-F-RAW =
    ELSE
        DROP 0
    THEN ;

: LIBPA-CONTENT-RID@  ( descriptor -- rid|0 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF _LIBPAC.RID ELSE DROP 0 THEN ;

: LIBPA-CONTENT-REVISION@  ( descriptor -- revision|-1 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF
        _LIBPAC.CONTENT-REVISION @
    ELSE
        DROP -1
    THEN ;

: LIBPA-CONTENT-DOMAIN-REVISION@  ( descriptor -- revision|-1 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF
        _LIBPAC.DOMAIN-REVISION @
    ELSE
        DROP -1
    THEN ;

: LIBPA-CONTENT-SIZE@  ( descriptor -- bytes|-1 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF _LIBPAC.DATA-U @ ELSE DROP -1 THEN ;

: LIBPA-CONTENT-KIND@  ( descriptor -- kind|-1 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF _LIBPAC.KIND @ ELSE DROP -1 THEN ;

: LIBPA-CONTENT-MEDIA@  ( descriptor -- media|-1 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF _LIBPAC.MEDIA @ ELSE DROP -1 THEN ;

\ The returned digest pointer is borrowed from the caller-owned descriptor.
: LIBPA-CONTENT-DIGEST@  ( descriptor -- digest|0 )
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? IF _LIBPAC.DIGEST ELSE DROP 0 THEN ;

\ Semantic equality deliberately ignores record identity, domain/content
\ revision, and physical blob references.  Sealed Library descriptors carry
\ the SHA3 digest needed to answer that question without reading content.
\ RAW evidence descriptors do not carry such a seal, so a descriptor-only
\ comparison must fail closed rather than equating same-sized opaque blobs.
: LIBPA-CONTENT-EQUAL?
  ( descriptor-a descriptor-b -- flag )
    >R
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    R@ LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBPA-CONTENT-RAW? R@ LIBPA-CONTENT-RAW? OR IF
        DROP R> DROP 0 EXIT
    THEN
    DUP _LIBPAC.DATA-U @ R@ _LIBPAC.DATA-U @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP _LIBPAC.KIND @ R@ _LIBPAC.KIND @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP _LIBPAC.MEDIA @ R@ _LIBPAC.MEDIA @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    _LIBPAC.DIGEST R> _LIBPAC.DIGEST SHA3-256-COMPARE ;

: _LIBPA-DESCRIPTOR>RETAINED-FACTS
  ( descriptor retained-facts -- status )
    >R
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DUP LIBPA-CONTENT-RAW? IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ LIBRARY-RETAINED-CONTENT-FACTS-INIT
    DUP _LIBPAC.RID R@ LIBRCF.ID RID-COPY
    DUP _LIBPAC.DOMAIN-REVISION @ R@ LIBRCF.DOMAIN-REVISION !
    DUP _LIBPAC.CONTENT-REVISION @ R@ LIBRCF.CONTENT-REVISION !
    DUP _LIBPAC.KIND @ R@ LIBRCF.KIND !
    DUP _LIBPAC.MEDIA @ R@ LIBRCF.MEDIA !
    DUP _LIBPAC.DATA-U @ R@ LIBRCF.DATA-U !
    _LIBPAC.DIGEST R@ LIBRCF.DIGEST RID-COPY
    R@ LIBRARY-RETAINED-CONTENT-FACTS-VALID? 0= IF
        R@ LIBRARY-RETAINED-CONTENT-FACTS-INIT
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

\ ---------------------------------------------------------------------
\ One current semantic document record
\ ---------------------------------------------------------------------
\ The neutral segment already supplies the checked envelope.  The Library
\ payload therefore stores only its semantic entry and the immutable content
\ descriptor reference needed to resolve the current bytes.  It has no
\ intermediate codec shim, legacy decoder, or format branch.

: _LIBPAD.MAGIC       ( record -- a ) _LIBPAD-MAGIC + ;
: _LIBPAD.PAYLOAD-U   ( record -- a ) _LIBPAD-PAYLOAD-U + ;
: _LIBPAD.CONTENT-REF ( record -- ref ) _LIBPAD-CONTENT-REF + ;
: _LIBPAD.METADATA-BLOB ( record -- blob ) _LIBPAD-METADATA-BLOB + ;
: _LIBPAD.ENTRY       ( record -- entry ) _LIBPAD-ENTRY + ;

: _LIBPAD-REF-AGREES?  ( entry content-ref-or-zero -- flag )
    OVER LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED = IF
        DUP 0= IF 2DROP -1 EXIT THEN
        PERSIST-REF-SIZE _LIBPA-ZERO? NIP EXIT
    THEN
    DUP 0= IF 2DROP 0 EXIT THEN
    PERSIST-REF-VALID? NIP ;

: _LIBPAD-METADATA-AGREES?  ( entry metadata-blob-or-zero -- flag )
    OVER LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED = IF
        DUP 0= IF 2DROP -1 EXIT THEN
        PBLOB-SIZE _LIBPA-ZERO? NIP EXIT
    THEN
    DUP 0= IF 2DROP 0 EXIT THEN
    DUP PBLOB-VALID? 0= IF 2DROP 0 EXIT THEN
    PBLOB-TOTAL@ SWAP LIBE.METADATA-U @ = ;

: LIBPA-DOCUMENT-RECORD-VALID?  ( record-a record-u -- flag )
    DUP LIBPA-DOCUMENT-RECORD-SIZE <> IF 2DROP 0 EXIT THEN
    OVER 0= IF 2DROP 0 EXIT THEN
    2DUP MSPAN-NONWRAPPING? 0= IF 2DROP 0 EXIT THEN
    DROP
    DUP _LIBPAD.MAGIC @ _LIBPA-DOCUMENT-MAGIC <> IF DROP 0 EXIT THEN
    DUP _LIBPAD.PAYLOAD-U @ LIBPA-DOCUMENT-RECORD-SIZE <> IF
        DROP 0 EXIT
    THEN
    DUP _LIBPAD.ENTRY LIB-ENTRY-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPAD.ENTRY OVER _LIBPAD.CONTENT-REF
        _LIBPAD-REF-AGREES? 0= IF DROP 0 EXIT THEN
    DUP _LIBPAD.ENTRY SWAP _LIBPAD.METADATA-BLOB
        _LIBPAD-METADATA-AGREES? ;

: LIBPA-DOCUMENT-RECORD-ENCODE
    ( entry content-ref-or-zero metadata-blob-or-zero destination -- status )
    >R
    2 PICK LIB-ENTRY-VALID? 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK 2 PICK _LIBPAD-REF-AGREES? 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK OVER _LIBPAD-METADATA-AGREES? 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ LIBPA-DOCUMENT-RECORD-SIZE MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK LIB-ENTRY-SIZE R@ LIBPA-DOCUMENT-RECORD-SIZE
        MSPAN-OVERLAP? IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    1 PICK IF
        1 PICK PERSIST-REF-SIZE R@ LIBPA-DOCUMENT-RECORD-SIZE
            MSPAN-OVERLAP? IF
            _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
        THEN
    THEN
    DUP IF
        DUP PBLOB-SIZE R@ LIBPA-DOCUMENT-RECORD-SIZE
            MSPAN-OVERLAP? IF
            _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
        THEN
    THEN
    R@ LIBPA-DOCUMENT-RECORD-SIZE 0 FILL
    _LIBPA-DOCUMENT-MAGIC R@ _LIBPAD.MAGIC !
    LIBPA-DOCUMENT-RECORD-SIZE R@ _LIBPAD.PAYLOAD-U !
    1 PICK IF 1 PICK R@ _LIBPAD.CONTENT-REF PERSIST-REF-COPY THEN
    DUP IF DUP R@ _LIBPAD.METADATA-BLOB PBLOB-COPY DROP THEN
    2 PICK R@ _LIBPAD.ENTRY LIB-ENTRY-SIZE MOVE
    _LIBPA-DROP3
    R@ LIBPA-DOCUMENT-RECORD-SIZE LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: LIBPA-DOCUMENT-RECORD-DECODE
    ( record-a record-u entry-destination -- status )
    >R
    2DUP LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ LIB-ENTRY-SIZE MSPAN-NONWRAPPING? 0= IF
        2DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    2DUP R@ LIB-ENTRY-SIZE MSPAN-OVERLAP? IF
        2DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    DROP _LIBPAD.ENTRY R@ LIB-ENTRY-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-DOCUMENT-RECORD-CONTENT-REF  ( record-a record-u -- ref|0 )
    2DUP LIBPA-DOCUMENT-RECORD-VALID? IF
        DROP _LIBPAD.CONTENT-REF
    ELSE
        2DROP 0
    THEN ;

: LIBPA-DOCUMENT-RECORD-METADATA-BLOB  ( record-a record-u -- blob|0 )
    2DUP LIBPA-DOCUMENT-RECORD-VALID? IF
        DROP _LIBPAD.METADATA-BLOB
    ELSE
        2DROP 0
    THEN ;

\ ---------------------------------------------------------------------
\ One current semantic collection record
\ ---------------------------------------------------------------------

: LIBPAC.ID                ( collection -- rid ) LIBC.ID ;
: LIBPAC.OPERATION-KEY     ( collection -- key ) LIBC.OPERATION-KEY ;
: LIBPAC.REVISION          ( collection -- a ) LIBC.REVISION ;
: LIBPAC.MUTATION-SEQUENCE ( collection -- a )
    LIBC.MUTATION-SEQUENCE ;
: LIBPAC.CREATED-SEQUENCE  ( collection -- a )
    LIBC.CREATED-SEQUENCE ;
: LIBPAC.MEMBER-N          ( collection -- a ) LIBC.MEMBER-N ;
: LIBPAC.TITLE-U           ( collection -- a ) LIBC.TITLE-U ;
: LIBPAC.FLAGS             ( collection -- a ) LIBC.FLAGS ;
: LIBPAC.TITLE             ( collection -- a ) LIBC.TITLE ;
: LIBPAC.REQUEST-SEAL      ( collection -- digest )
    LIBC.REQUEST-SEAL ;
: LIBPAC.RESERVED          ( collection -- a ) LIBC.RESERVED ;
: LIBPAC-TITLE$            ( collection -- a u )
    LIBC-TITLE$ ;

: LIBPA-COLLECTION-INIT  ( collection -- )
    LIB-COLLECTION-INIT ;

: LIBPA-COLLECTION-VALID?  ( collection -- flag )
    LIB-COLLECTION-VALID? ;

: _LIBPA-CANONICAL-RIDS?  ( member-rids member-n -- flag )
    DUP 0< IF 2DROP 0 EXIT THEN
    DUP PERSIST-MAX-SIGNED RID-SIZE / > IF 2DROP 0 EXIT THEN
    DUP 0= IF 2DROP -1 EXIT THEN
    OVER 0= IF 2DROP 0 EXIT THEN
    2DUP RID-SIZE * MSPAN-NONWRAPPING? 0= IF 2DROP 0 EXIT THEN
    DUP 0 ?DO
        OVER I RID-SIZE * + RID-PRESENT? 0= IF
            2DROP 0 UNLOOP EXIT
        THEN
        I IF
            OVER I 1- RID-SIZE * + RID-SIZE
            3 PICK I RID-SIZE * + RID-SIZE
            COMPARE 0< 0= IF
                2DROP 0 UNLOOP EXIT
            THEN
        THEN
    LOOP
    2DROP -1 ;

: _LIBPA-COLLECTION-REQUEST-HASH-FEED
  ( collection member-rids member-n -- )
    SHA3-256-BEGIN
    S" akashic.library.collection-create-request.v2" SHA3-256-ADD
    2 PICK LIBC.TITLE-U 8 SHA3-256-ADD
    2 PICK LIBC.TITLE LIB-COLLECTION-TITLE-MAX SHA3-256-ADD
    2 PICK LIBC.MEMBER-N 8 SHA3-256-ADD
    OVER OVER RID-SIZE * SHA3-256-ADD
    _LIBPA-DROP3 ;

: _LIBPA-COLLECTION-REQUEST-HASH
  ( collection member-rids member-n destination -- )
    >R _LIBPA-COLLECTION-REQUEST-HASH-FEED R> SHA3-256-END ;

: _LIBPA-COLLECTION-REQUEST-MATCHES?
  ( collection member-rids member-n -- flag )
    2 PICK LIBC.REQUEST-SEAL >R
    _LIBPA-COLLECTION-REQUEST-HASH-FEED
    R> SHA3-256-END-COMPARE ;

: LIBPA-COLLECTION-REQUEST-SEAL!
  ( initial-collection canonical-member-rids member-n -- status )
    2DUP _LIBPA-CANONICAL-RIDS? 0= IF
        _LIBPA-DROP3 LIBPA-S-INVALID EXIT
    THEN
    2 PICK 0= IF _LIBPA-DROP3 LIBPA-S-INVALID EXIT THEN
    2 PICK LIBPA-COLLECTION-SIZE MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP3 LIBPA-S-INVALID EXIT
    THEN
    2 PICK LIBC.REVISION @ 1 <> IF
        _LIBPA-DROP3 LIBPA-S-INVALID EXIT
    THEN
    2 PICK LIBC.MEMBER-N @ OVER <> IF
        _LIBPA-DROP3 LIBPA-S-INVALID EXIT
    THEN
    2 PICK 2 PICK 2 PICK
    5 PICK LIBC.REQUEST-SEAL _LIBPA-COLLECTION-REQUEST-HASH
    2 PICK LIBPA-COLLECTION-VALID? 0= IF
        2 PICK LIBC.REQUEST-SEAL LIB-DIGEST-SIZE 0 FILL
        _LIBPA-DROP3 LIBPA-S-INVALID EXIT
    THEN
    _LIBPA-DROP3 LIBPA-S-OK ;

: LIBPA-COLLECTION-COPY  ( source destination -- status )
    OVER LIBPA-COLLECTION-VALID? 0= IF
        2DROP LIBPA-S-INVALID EXIT
    THEN
    DUP 0= IF 2DROP LIBPA-S-INVALID EXIT THEN
    DUP LIBPA-COLLECTION-SIZE MSPAN-NONWRAPPING? 0= IF
        2DROP LIBPA-S-INVALID EXIT
    THEN
    2DUP LIBPA-COLLECTION-SIZE MSPAN-OVERLAP? IF
        2DROP LIBPA-S-INVALID EXIT
    THEN
    LIBPA-COLLECTION-SIZE MOVE LIBPA-S-OK ;

: _LIBPACR.MAGIC      ( record -- a ) _LIBPACR-MAGIC + ;
: _LIBPACR.PAYLOAD-U  ( record -- a ) _LIBPACR-PAYLOAD-U + ;
: _LIBPACR.COLLECTION ( record -- collection ) _LIBPACR-COLLECTION + ;

: LIBPA-COLLECTION-RECORD-VALID?  ( record-a record-u -- flag )
    DUP LIBPA-COLLECTION-RECORD-SIZE <> IF 2DROP 0 EXIT THEN
    OVER 0= IF 2DROP 0 EXIT THEN
    2DUP MSPAN-NONWRAPPING? 0= IF 2DROP 0 EXIT THEN
    DROP
    DUP _LIBPACR.MAGIC @ _LIBPA-COLLECTION-MAGIC <> IF DROP 0 EXIT THEN
    DUP _LIBPACR.PAYLOAD-U @ LIBPA-COLLECTION-RECORD-SIZE <> IF
        DROP 0 EXIT
    THEN
    _LIBPACR.COLLECTION LIBPA-COLLECTION-VALID? ;

: LIBPA-COLLECTION-RECORD-ENCODE
  ( collection destination -- status )
    >R
    DUP LIBPA-COLLECTION-VALID? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ LIBPA-COLLECTION-RECORD-SIZE MSPAN-NONWRAPPING? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP LIBPA-COLLECTION-SIZE R@ LIBPA-COLLECTION-RECORD-SIZE
        MSPAN-OVERLAP? IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ LIBPA-COLLECTION-RECORD-SIZE 0 FILL
    _LIBPA-COLLECTION-MAGIC R@ _LIBPACR.MAGIC !
    LIBPA-COLLECTION-RECORD-SIZE R@ _LIBPACR.PAYLOAD-U !
    R@ _LIBPACR.COLLECTION LIBPA-COLLECTION-SIZE MOVE
    R@ LIBPA-COLLECTION-RECORD-SIZE
        LIBPA-COLLECTION-RECORD-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: LIBPA-COLLECTION-RECORD-DECODE
  ( record-a record-u collection-destination -- status )
    >R
    2DUP LIBPA-COLLECTION-RECORD-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ LIBPA-COLLECTION-SIZE MSPAN-NONWRAPPING? 0= IF
        2DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    2DUP R@ LIBPA-COLLECTION-SIZE MSPAN-OVERLAP? IF
        2DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    DROP _LIBPACR.COLLECTION R@ LIBPA-COLLECTION-SIZE MOVE
    R> DROP LIBPA-S-OK ;

