\ Create and replacement retain the caller's immutable fact-span operands
\ across candidate/history helpers, which legitimately reuse the generic
\ member/total scratch cells during the same transaction.  FACTS-U=-1 is the
\ explicit inherit-current-PBLOB sentinel for non-fact mutations.
: _LIBPIX.FACTS-A  ( work -- a ) _LIBPIX-FACTS-A-OFF + ;
: _LIBPIX.FACTS-U  ( work -- a ) _LIBPIX-FACTS-U-OFF + ;
