    _LIBPIX-RETAINED-CONTENT-OFF + ;

: _LIBPIX-TREE  ( index work -- tree )
    SWAP PBTREE-SIZE * _LIBPIX-TREES-OFF + + ;

: _LIBPIX-ROOT  ( index work -- root )
    SWAP PBTREE-ROOT-SIZE * _LIBPIX-ROOTS-OFF + + ;

: _LIBPIX-STAGING-ROOT  ( index work -- root )
    SWAP PBTREE-ROOT-SIZE * _LIBPIX-STAGING-ROOTS-OFF + + ;

: _LIBPIX-SCOPE  ( index -- scope|0 )
    CASE
        _LIBPIX-SHARED-DIRECTORY OF
            _LIBPIX-SCOPE-SHARED-DIRECTORY ENDOF
        _LIBPIX-RID-DIRECTORY OF _LIBPIX-SCOPE-RID ENDOF
        _LIBPIX-OPERATION-RECEIPTS OF _LIBPIX-SCOPE-OPERATION ENDOF
        _LIBPIX-CREATION-ORDER OF _LIBPIX-SCOPE-CREATION ENDOF
        _LIBPIX-RECENCY-ORDER OF _LIBPIX-SCOPE-RECENCY ENDOF
        _LIBPIX-STATE-ORDER OF _LIBPIX-SCOPE-STATE ENDOF
        _LIBPIX-TITLE-ORDER OF _LIBPIX-SCOPE-TITLE ENDOF
        _LIBPIX-TAG-POSTINGS OF _LIBPIX-SCOPE-TAG ENDOF
        _LIBPIX-BODY-POSTINGS OF _LIBPIX-SCOPE-BODY ENDOF
        _LIBPIX-COLLECTION-DIRECTORY OF
            _LIBPIX-SCOPE-COLLECTION ENDOF
        _LIBPIX-COLLECTION-ORDER OF
            _LIBPIX-SCOPE-COLLECTION-ORDER ENDOF
        _LIBPIX-COLLECTION-TITLE OF
            _LIBPIX-SCOPE-COLLECTION-TITLE ENDOF
        _LIBPIX-MEMBERSHIP OF _LIBPIX-SCOPE-MEMBERSHIP ENDOF
        _LIBPIX-HISTORY OF _LIBPIX-SCOPE-HISTORY ENDOF
        _LIBPIX-STATE-RECENCY OF
            _LIBPIX-SCOPE-STATE-RECENCY ENDOF
        0 SWAP
    ENDCASE ;

: _LIBPIX-ALLOCATE  ( index-work store pstore-work -- page-id status )
    2 PICK _LIBPIX.STAGING-ACTIVE @ IF
        2 PICK _LIBPIX.RECLAIM-WORK >R
        PBTREE-HIGH-WATER-ALLOCATE
        DUP IF R> DROP EXIT THEN DROP
        DUP R@ RECLAIM-CLAIM-HIGH-WATER
        DUP IF
            >R DROP -1 R> R> DROP EXIT
        THEN
        R> DROP EXIT
    THEN
    1 3 PICK _LIBPIX.RECLAIM-STEP-CALLS +!
    RECLAIM-MAX-BATCH 3 PICK _LIBPIX.RECLAIM-WORK RECLAIM-STEP
    DUP IF
        >R DROP _LIBPA-DROP3 -1 R> EXIT
    THEN DROP
    3 PICK _LIBPIX.RECLAIM-MOVED +!
    ROT _LIBPIX.RECLAIM-WORK -ROT RECLAIM-ALLOCATE ;

: _LIBPIX-STATUS?  ( status -- flag )
    DUP LIBPA-S-OK >= SWAP LIBPA-S-FAULT <= AND ;

: _LIBPIX-AUDIT-MAP-BOUND?  ( work -- flag )
    >R
    R@ _LIBPIX.AUDIT-MAP-CAPACITY @ DUP 0< IF
        DROP R> DROP 0 EXIT
    THEN
    DUP 0= IF
        DROP R@ _LIBPIX.AUDIT-MAP @ 0= R> DROP EXIT
    THEN
    R@ _LIBPIX.AUDIT-MAP @ DUP 0= IF
        DROP DROP R> DROP 0 EXIT
    THEN
    SWAP 2DUP MSPAN-NONWRAPPING? 0= IF
        2DROP R> DROP 0 EXIT
    THEN
    2DUP R@ LIBPA-INDEX-WORK-SIZE MSPAN-OVERLAP? IF
        2DROP R> DROP 0 EXIT
    THEN
    2DUP R@ _LIBPIX.ADAPTER @ LIBPA-SIZE
        MSPAN-OVERLAP? IF
        2DROP R> DROP 0 EXIT
    THEN
    2DUP R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        PSTORE-SPAN-DISJOINT? 0= IF
        2DROP R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-WORK-SPAN-DISJOINT?
    R> DROP ;

: LIBPA-INDEX-WORK-VALID?  ( work -- flag )
    DUP 0= IF DROP 0 EXIT THEN
    DUP LIBPA-INDEX-WORK-SIZE MSPAN-NONWRAPPING? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.MAGIC @ _LIBPIX-MAGIC <> IF DROP 0 EXIT THEN
    DUP _LIBPIX.SELF @ OVER <> IF DROP 0 EXIT THEN
    DUP _LIBPIX.BUSY @ DUP 0= SWAP -1 = OR 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.STATE @ DUP _LIBPIX-STATE-READY >=
        SWAP _LIBPIX-STATE-REOPEN <= AND 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.STATUS @ _LIBPIX-STATUS? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.ADAPTER @ LIBPA-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.PSTORE-WORK @ PSTORE-WORK-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.RECLAIM RECLAIM-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.RECLAIM-WORK RECLAIM-WORK-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-WORK-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.BTREE-WORK PBTREE-WORK-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.BTREE-AUDIT-WORK
        PBTREE-AUDIT-WORK-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX.BLOB-WORK PBLOB-WORK-VALID? 0= IF DROP 0 EXIT THEN
    DUP _LIBPIX-AUDIT-MAP-BOUND? 0= IF DROP 0 EXIT THEN
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP 2 PICK _LIBPIX-TREE PBTREE-VALID? 0= IF 2DROP 0 EXIT THEN
        1+
    REPEAT
    DROP DROP -1 ;

: _LIBPIX-INIT-TREE  ( index work -- status )
    >R
    DUP R@ _LIBPIX.PAGE-ID !
    _LIBPIX-SCOPE DUP 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    ['] _LIBPIX-ALLOCATE R@
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-TREE
    PBTREE-INIT _LIBPA-PERSIST>STATUS R> DROP ;

: _LIBPIX-INIT-GEOMETRY?  ( pstore-work adapter work -- flag )
    2 PICK PSTORE-WORK-VALID? 0= IF _LIBPA-DROP3 0 EXIT THEN
    1 PICK LIBPA-VALID? 0= IF _LIBPA-DROP3 0 EXIT THEN
    DUP LIBPA-INDEX-WORK-SIZE MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP3 0 EXIT
    THEN
    DUP LIBPA-INDEX-WORK-SIZE 4 PICK PSTORE-WORK-SIZE
        MSPAN-OVERLAP? IF _LIBPA-DROP3 0 EXIT THEN
    DUP LIBPA-INDEX-WORK-SIZE 4 PICK
        PSTORE-WORK-SPAN-DISJOINT? 0= IF _LIBPA-DROP3 0 EXIT THEN
    DUP LIBPA-INDEX-WORK-SIZE 3 PICK LIBPA-SIZE
        MSPAN-OVERLAP? IF _LIBPA-DROP3 0 EXIT THEN
    1 PICK LIBPA-SIZE 4 PICK
        PSTORE-WORK-SPAN-DISJOINT? 0= IF _LIBPA-DROP3 0 EXIT THEN
    DUP LIBPA-INDEX-WORK-SIZE 3 PICK _LIBPA-D.STORE @
        PSTORE-SPAN-DISJOINT? 0= IF _LIBPA-DROP3 0 EXIT THEN
    2 PICK PSTORE-WORK-RECORD-BUFFER$
    DUP PBLOB-CHUNK-SIZE PERSIST-RECORD-HEADER-SIZE + < IF
        2DROP _LIBPA-DROP3 0 EXIT
    THEN
    2DUP 4 PICK LIBPA-INDEX-WORK-SIZE MSPAN-OVERLAP? IF
        2DROP _LIBPA-DROP3 0 EXIT
    THEN
    2DROP _LIBPA-DROP3 -1 ;

: _LIBPIX-INIT-AUDIT-MAP?  ( map-a map-cap pstore-work adapter work -- flag )
    3 PICK DUP 0< IF DROP _LIBPA-DROP5 0 EXIT THEN
    DUP 0= IF
        DROP 4 PICK 0= >R _LIBPA-DROP5 R> EXIT
    THEN
    DROP
    4 PICK DUP 0= IF DROP _LIBPA-DROP5 0 EXIT THEN
    DROP
    4 PICK 4 PICK MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP5 0 EXIT
    THEN
    4 PICK 4 PICK 2 PICK LIBPA-INDEX-WORK-SIZE
        MSPAN-OVERLAP? IF
        _LIBPA-DROP5 0 EXIT
    THEN
    4 PICK 4 PICK 3 PICK LIBPA-SIZE MSPAN-OVERLAP? IF
        _LIBPA-DROP5 0 EXIT
    THEN
    4 PICK 4 PICK 3 PICK _LIBPA-D.STORE @
        PSTORE-SPAN-DISJOINT? 0= IF
        _LIBPA-DROP5 0 EXIT
    THEN
    4 PICK 4 PICK 4 PICK PSTORE-WORK-SPAN-DISJOINT? 0= IF
        _LIBPA-DROP5 0 EXIT
    THEN
    _LIBPA-DROP5 -1 ;

: LIBPA-INDEX-WORK-INIT
  ( audit-map-a audit-map-cap pstore-work adapter work -- status )
    2 PICK 2 PICK 2 PICK _LIBPIX-INIT-GEOMETRY? 0= IF
        _LIBPA-DROP5 LIBPA-S-INVALID EXIT
    THEN
    4 PICK 4 PICK 4 PICK 4 PICK 4 PICK
        _LIBPIX-INIT-AUDIT-MAP? 0= IF
        _LIBPA-DROP5 LIBPA-S-INVALID EXIT
    THEN
    >R
    R@ LIBPA-INDEX-WORK-SIZE 0 FILL
    _LIBPIX-MAGIC R@ _LIBPIX.MAGIC !
    R@ R@ _LIBPIX.SELF !
    LIBPA-S-OK R@ _LIBPIX.STATUS !
    3 PICK R@ _LIBPIX.AUDIT-MAP !
    2 PICK R@ _LIBPIX.AUDIT-MAP-CAPACITY !
    OVER R@ _LIBPIX.PSTORE-WORK !
    DUP R@ _LIBPIX.ADAPTER !
    OVER R@ _LIBPIX.BTREE-WORK PBTREE-WORK-INIT
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    OVER R@ _LIBPIX.BTREE-AUDIT-WORK PBTREE-AUDIT-WORK-INIT
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.BLOB-WORK PBLOB-WORK-INIT
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.RECLAIM RECLAIM-INIT
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.RECLAIM-WORK RECLAIM-WORK-INIT
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.RECLAIM-AUDIT-WORK RECLAIM-AUDIT-WORK-INIT
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-INIT-TREE
        DUP IF >R DROP _LIBPA-DROP4 R> R> DROP EXIT THEN DROP
        1+
    REPEAT
    DROP _LIBPA-DROP4 R> DROP LIBPA-S-OK ;

: _LIBPA-INDEX-BOUND?  ( adapter index-work -- flag )
    >R
    DUP LIBPA-VALID? 0= IF DROP R> DROP 0 EXIT THEN
    R@ LIBPA-INDEX-WORK-VALID? 0= IF DROP R> DROP 0 EXIT THEN
    R@ _LIBPIX.ADAPTER @ OVER <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBPA-SIZE R@ LIBPA-INDEX-WORK-SIZE
        MSPAN-OVERLAP? IF DROP R> DROP 0 EXIT THEN
    DUP LIBPA-SIZE R@ _LIBPIX.PSTORE-WORK @
        PSTORE-WORK-SPAN-DISJOINT? 0= IF DROP R> DROP 0 EXIT THEN
    R@ LIBPA-INDEX-WORK-SIZE R@ _LIBPIX.PSTORE-WORK @
        PSTORE-WORK-SPAN-DISJOINT? 0= IF DROP R> DROP 0 EXIT THEN
    DUP _LIBPA-D.STORE @
    R@ LIBPA-INDEX-WORK-SIZE 2 PICK PSTORE-SPAN-DISJOINT?
    NIP NIP R> DROP ;

: _LIBPIX-ENTER  ( adapter work -- status )
    2DUP _LIBPA-INDEX-BOUND? 0= IF 2DROP LIBPA-S-INVALID EXIT THEN
    DUP _LIBPIX.BUSY @ IF 2DROP LIBPA-S-BUSY EXIT THEN
    -1 OVER _LIBPIX.BUSY !
    LIBPA-S-INVALID OVER _LIBPIX.STATUS !
    2DROP LIBPA-S-OK ;

: _LIBPIX-LEAVE  ( status adapter work -- status )
    >R
    OVER OVER _LIBPA-D.STATUS !
    OVER R@ _LIBPIX.STATUS !
    0 R@ _LIBPIX.BUSY !
    DROP R> DROP ;


\ ---------------------------------------------------------------------
\ Single indexed application root and indexed transaction lifetime
\ ---------------------------------------------------------------------

: _LIBPIX-WORK-CATCH  ( index-work body-xt -- status )
    >R DUP R> CATCH
    DUP IF
        2DROP LIBPA-S-FAULT
    ELSE
        DROP NIP
    THEN ;

: _LIBPIX-ROOT-INIT-ONE  ( index index-work -- status )
    >R
    DUP R@ _LIBPIX-TREE
    SWAP R@ _LIBPIX-ROOT
    PBTREE-ROOT-INIT _LIBPA-PERSIST>STATUS R> DROP ;

: _LIBPIX-ROOTS-INIT  ( index-work -- status )
    >R 0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-ROOT-INIT-ONE
        DUP IF >R DROP R> R> DROP EXIT THEN DROP
        1+
    REPEAT
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-ROOT-CURRENT?  ( index index-work -- flag )
    >R
    DUP R@ _LIBPIX-ROOT
    OVER R@ _LIBPIX-TREE PBTREE-ROOT-VALID? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP R@ _LIBPIX-ROOT PBTREE-ROOT-GENERATION@
    R@ _LIBPIX.BASE-GENERATION @ =
    NIP R> DROP ;

: _LIBPIX-ROOTS-CURRENT?  ( index-work -- flag )
    >R 0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-ROOT-CURRENT? 0= IF
            DROP R> DROP 0 EXIT
        THEN
        1+
    REPEAT
    DROP R> DROP -1 ;

: _LIBPIX-ROOT-ADVANCE-ONE  ( index index-work -- status )
    >R
    DUP R@ _LIBPIX-ROOT PBTREE-ROOT-GENERATION@
    DUP R@ _LIBPIX.BASE-GENERATION @ = IF
        DROP
        DUP R@ _LIBPIX-ROOT
        R@ _LIBPIX.TEMP-ROOT
        2 PICK R@ _LIBPIX-TREE PBTREE-ROOT-ADVANCE
        DUP IF
            _LIBPA-PERSIST>STATUS >R DROP R> R> DROP EXIT
        THEN DROP
        R@ _LIBPIX.TEMP-ROOT
        OVER R@ _LIBPIX-ROOT PBTREE-ROOT-COPY
        _LIBPA-PERSIST>STATUS NIP R> DROP EXIT
    THEN
    R@ _LIBPIX.BASE-GENERATION @ 1+ <> IF
        DROP R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-ROOTS-ADVANCE  ( index-work -- status )
    >R 0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-ROOT-ADVANCE-ONE
        DUP IF >R DROP R> R> DROP EXIT THEN DROP
        1+
    REPEAT
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-ROOTS>STAGING  ( index-work -- status )
    >R 0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-ROOT
        OVER R@ _LIBPIX-STAGING-ROOT
        PBTREE-ROOT-COPY
        DUP IF
            _LIBPA-PERSIST>STATUS >R DROP R> R> DROP EXIT
        THEN DROP
        1+
    REPEAT
    DROP
    -1 R@ _LIBPIX.STAGING-ACTIVE !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-STAGING-ROOT-ADVANCE-ONE  ( index index-work -- status )
    >R
    DUP R@ _LIBPIX-STAGING-ROOT PBTREE-ROOT-GENERATION@
    DUP R@ _LIBPIX.BASE-GENERATION @ = IF
        DROP
        DUP R@ _LIBPIX-STAGING-ROOT
        R@ _LIBPIX.TEMP-ROOT
        2 PICK R@ _LIBPIX-TREE PBTREE-ROOT-ADVANCE
        DUP IF
            _LIBPA-PERSIST>STATUS >R DROP R> R> DROP EXIT
        THEN DROP
        R@ _LIBPIX.TEMP-ROOT
        OVER R@ _LIBPIX-STAGING-ROOT PBTREE-ROOT-COPY
        _LIBPA-PERSIST>STATUS NIP R> DROP EXIT
    THEN
    R@ _LIBPIX.BASE-GENERATION @ 1+ <> IF
        DROP R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-STAGING-ROOTS-ADVANCE  ( index-work -- status )
    >R
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-STAGING-ROOT-ADVANCE-ONE
        DUP IF >R DROP R> R> DROP EXIT THEN DROP
        1+
    REPEAT
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-STAGING>ROOTS  ( index-work -- status )
    >R
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-STAGING-ROOT
        OVER R@ _LIBPIX-ROOT
        PBTREE-ROOT-COPY
        DUP IF
            _LIBPA-PERSIST>STATUS >R DROP R> R> DROP EXIT
        THEN DROP
        1+
    REPEAT
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-ROOT>WORK  ( payload-a payload-u index-work -- status )
    >R
    DUP PERSIST-PAGE-PAYLOAD-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER R@ _LIBPIX.PAGE PERSIST-PAGE-PAYLOAD-SIZE MOVE
    2DROP
    R@ _LIBPIX.PAGE _LIBPAR-MAGIC +
        _LIBPA-ROOT-MAGIC 8 _LIBPA-BYTES= 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-FLAGS + @ IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-LOGICAL-GENERATION + @ DUP 0< IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.LOGICAL-GENERATION !
    R@ _LIBPIX.PAGE _LIBPAR-MUTATION-SEQUENCE + @ DUP 0< IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.MUTATION-SEQUENCE !
    R@ _LIBPIX.PAGE _LIBPAR-DOCUMENT-COUNT + @ DUP 0< IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.DOCUMENT-COUNT !
    R@ _LIBPIX.PAGE _LIBPAR-COLLECTION-COUNT + @ DUP 0< IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.COLLECTION-COUNT !
    R@ _LIBPIX.PAGE _LIBPAR-MEMBERSHIP-COUNT + @ DUP 0< IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.MEMBERSHIP-COUNT !
    R@ _LIBPIX.PAGE _LIBPAR-BOOTSTRAP-ID +
    DUP RID-PRESENT? OVER RID-SIZE _LIBPA-ZERO? OR 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.BOOTSTRAP-ID RID-COPY
    R@ _LIBPIX.PAGE _LIBPAR-RESERVED +
        PERSIST-PAGE-PAYLOAD-SIZE _LIBPAR-RESERVED -
        _LIBPA-ZERO? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX.PAGE-ID !
        R@ _LIBPIX.PAGE _LIBPAR-ROOTS +
            R@ _LIBPIX.PAGE-ID @ PBTREE-ROOT-SIZE * +
        R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT PBTREE-ROOT-COPY
        DUP IF
            _LIBPA-PERSIST>STATUS >R DROP R> R> DROP EXIT
        THEN DROP
        R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT
        R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-TREE
            PBTREE-ROOT-VALID? 0= IF
            DROP R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT PBTREE-ROOT-GENERATION@
        R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-GENERATION@ <> IF
            DROP R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        1+
    REPEAT
    DROP
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE + RECLAIM-STATE-SIZE
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ R@ _LIBPIX.RECLAIM
        RECLAIM-OPEN _LIBPA-PERSIST>STATUS
    DUP IF R> DROP EXIT THEN DROP
    R> DROP LIBPA-S-OK ;

: _LIBPIX-WORK>ROOT  ( index-work -- status )
    >R
    R@ _LIBPIX.PAGE PERSIST-PAGE-PAYLOAD-SIZE 0 FILL
    _LIBPA-ROOT-MAGIC R@ _LIBPIX.PAGE _LIBPAR-MAGIC + 8 MOVE
    R@ _LIBPIX.LOGICAL-GENERATION @
        R@ _LIBPIX.PAGE _LIBPAR-LOGICAL-GENERATION + !
    R@ _LIBPIX.MUTATION-SEQUENCE @
        R@ _LIBPIX.PAGE _LIBPAR-MUTATION-SEQUENCE + !
    R@ _LIBPIX.DOCUMENT-COUNT @
        R@ _LIBPIX.PAGE _LIBPAR-DOCUMENT-COUNT + !
    R@ _LIBPIX.COLLECTION-COUNT @
        R@ _LIBPIX.PAGE _LIBPAR-COLLECTION-COUNT + !
    R@ _LIBPIX.MEMBERSHIP-COUNT @
        R@ _LIBPIX.PAGE _LIBPAR-MEMBERSHIP-COUNT + !
    R@ _LIBPIX.BOOTSTRAP-ID
        R@ _LIBPIX.PAGE _LIBPAR-BOOTSTRAP-ID + RID-COPY
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-ROOT
        OVER PBTREE-ROOT-SIZE *
            R@ _LIBPIX.PAGE _LIBPAR-ROOTS + +
        PBTREE-ROOT-COPY
        DUP IF
            _LIBPA-PERSIST>STATUS >R DROP R> R> DROP EXIT
        THEN DROP
        1+
    REPEAT
    DROP
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE + RECLAIM-STATE-SIZE
    R@ _LIBPIX.RECLAIM-WORK RECLAIM-STATE!
    _LIBPA-PERSIST>STATUS R> DROP ;

: _LIBPIX-AUDIT-ROOT?  ( index-work -- status )
    >R
    R@ _LIBPIX.PAGE _LIBPAR-MAGIC +
        _LIBPA-ROOT-MAGIC 8 _LIBPA-BYTES= 0= IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-FLAGS + @ IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-LOGICAL-GENERATION + @ 0< IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-MUTATION-SEQUENCE + @ 0< IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-DOCUMENT-COUNT + @ 0< IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-COLLECTION-COUNT + @ 0< IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-MEMBERSHIP-COUNT + @ 0< IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE _LIBPAR-BOOTSTRAP-ID +
    DUP RID-PRESENT? OVER RID-SIZE _LIBPA-ZERO? OR 0= IF
        DROP R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    DROP
    R@ _LIBPIX.PAGE _LIBPAR-RESERVED +
        PERSIST-PAGE-PAYLOAD-SIZE _LIBPAR-RESERVED -
        _LIBPA-ZERO? 0= IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        R@ _LIBPIX.PAGE _LIBPAR-ROOTS +
            OVER PBTREE-ROOT-SIZE * + DUP
        2 PICK R@ _LIBPIX-TREE PBTREE-ROOT-VALID? 0= IF
            2DROP R> DROP PERSIST-S-CORRUPT EXIT
        THEN
        DUP PBTREE-ROOT-GENERATION@
            R@ _LIBPIX.AUDIT-GENERATION @ <> IF
            2DROP R> DROP PERSIST-S-CORRUPT EXIT
        THEN
        OVER R@ _LIBPIX-STAGING-ROOT PBTREE-ROOT-COPY
        DUP IF
            2DROP R> DROP PERSIST-S-FAULT EXIT
        THEN
        DROP 1+
    REPEAT
    DROP R> DROP PERSIST-S-OK ;

: _LIBPIX-AUDIT-PAGE  ( page-id expected-height reclaim-audit -- status )
    SWAP DROP RECLAIM-AUDIT-APPLICATION-PAGE ;

: _LIBPIX-AUDIT-READ-STATUS  ( status -- status )
    DUP PERSIST-S-ABSENT =
    OVER PERSIST-S-NOT-FOUND = OR IF
        DROP PERSIST-S-CORRUPT
    THEN ;

: _LIBPIX-AUDIT-TREES  ( index-work -- status )
    >R 0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPIX-STAGING-ROOT
        R@ _LIBPIX.AUDIT-GENERATION @
        R@ _LIBPIX.AUDIT-PAGE-COUNT @
        R@ _LIBPIX.AUDIT-DATA-BANK @
        ['] _LIBPIX-AUDIT-PAGE
        R@ _LIBPIX.RECLAIM-AUDIT-WORK
        6 PICK R@ _LIBPIX-TREE
        R@ _LIBPIX.BTREE-AUDIT-WORK
        PBTREE-AUDIT-SNAPSHOT-TX
        DUP IF
            >R 2DROP DROP R> R> DROP EXIT
        THEN
        DROP 2DROP 1+
    REPEAT
    DROP R> DROP PERSIST-S-OK ;

: _LIBPIX-AUDIT-EMPTY-SNAPSHOT  ( index-work -- status )
    >R
    R@ _LIBPIX.SNAPSHOT-ROOT PROOTV.APPLICATION-ROOT @ -1 <> IF
        R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    -1 R@ _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-APPLICATION-ROOT!
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE +
        RECLAIM-STATE-SIZE RECLAIM-STATE-INIT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE +
        RECLAIM-STATE-SIZE R@ _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-STATE!
    DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-APPLICATION-COMPLETE ;

: _LIBPIX-AUDIT-SNAPSHOT  ( index-work -- status )
    >R
    R@ _LIBPIX.AUDIT-PAGE-COUNT @ 0= IF
        R> _LIBPIX-AUDIT-EMPTY-SNAPSHOT EXIT
    THEN
    R@ _LIBPIX.SNAPSHOT-ROOT PROOTV.APPLICATION-ROOT @ DUP
        R@ _LIBPIX.AUDIT-PAGE-COUNT @ U>= IF
        DROP R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    DUP R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-PAGE-SNAPSHOT-TX
    DUP IF
        NIP _LIBPIX-AUDIT-READ-STATUS R> DROP EXIT
    THEN
    DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-PAGE-PAYLOAD$
    DUP PERSIST-PAGE-PAYLOAD-SIZE <> IF
        2DROP DROP R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    DROP R@ _LIBPIX.PAGE PERSIST-PAGE-PAYLOAD-SIZE MOVE
    DROP
    R@ _LIBPIX-AUDIT-ROOT? DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.SNAPSHOT-ROOT PROOTV.APPLICATION-ROOT @
        R@ _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-APPLICATION-ROOT!
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE +
        RECLAIM-STATE-SIZE R@ _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-STATE!
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-AUDIT-TREES DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX.RECLAIM-AUDIT-WORK
        RECLAIM-AUDIT-APPLICATION-COMPLETE ;

: _LIBPIX-RECLAIM-ENUMERATOR
  ( snapshot-root generation slot reclaim-audit index-work -- status )
    >R
    DUP R@ _LIBPIX.RECLAIM-AUDIT-WORK <> IF
        _LIBPA-DROP4 R> DROP PERSIST-S-INVALID EXIT
    THEN
    DROP DROP
    DUP R@ _LIBPIX.AUDIT-GENERATION !
    OVER PROOTV.PAGE-COUNT @ R@ _LIBPIX.AUDIT-PAGE-COUNT !
    OVER PROOTV.DATA-BANK @ R@ _LIBPIX.AUDIT-DATA-BANK !
    DROP
    R@ _LIBPIX.SNAPSHOT-ROOT PERSIST-ROOT-VALUE-SIZE MOVE
    R> _LIBPIX-AUDIT-SNAPSHOT ;

: _LIBPIX-AUDIT-SLOT-SIZE  ( slot index-work -- status )
    >R
    DUP R@ _LIBPIX.SNAPSHOT-ROOT
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-ROOT-SLOT@
    DUP PERSIST-S-OK = IF
        DROP 2DROP
        R@ _LIBPIX.SNAPSHOT-ROOT PROOTV.PAGE-COUNT @
        R@ _LIBPIX.AUDIT-MAP-U @ MAX
        R@ _LIBPIX.AUDIT-MAP-U !
        R> DROP PERSIST-S-OK EXIT
    THEN
    DUP PERSIST-S-ABSENT =
    OVER PERSIST-S-CORRUPT = OR IF
        DROP 2DROP R> DROP PERSIST-S-OK EXIT
    THEN
    DUP PERSIST-S-BUSY = IF
        DROP 2DROP R> DROP PERSIST-S-CONFLICT EXIT
    THEN
    >R 2DROP R> R> DROP ;

: _LIBPIX-COLD-AUDIT-TX  ( index-work -- status )
    >R
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.AUDIT-MAP-U !
    GPAIR-SLOT-A R@ _LIBPIX-AUDIT-SLOT-SIZE
    DUP IF R> DROP EXIT THEN DROP
    GPAIR-SLOT-B R@ _LIBPIX-AUDIT-SLOT-SIZE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.AUDIT-MAP-U @ RECLAIM-AUDIT-MAP-BYTES?
    DUP IF NIP R> DROP EXIT THEN DROP
    DUP R@ _LIBPIX.AUDIT-MAP-CAPACITY @ > IF
        DROP R> DROP PERSIST-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX.AUDIT-MAP-U !
    R@ _LIBPIX.AUDIT-MAP @ R@ _LIBPIX.AUDIT-MAP-U @
    ['] _LIBPIX-RECLAIM-ENUMERATOR R@
    R@ _LIBPIX.RECLAIM
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @
    R@ _LIBPIX.RECLAIM-AUDIT-WORK
    RECLAIM-AUDIT-CURRENT
    R> DROP ;

: _LIBPIX-COLD-AUDIT  ( index-work -- status )
    >R
    R@ ['] _LIBPIX-COLD-AUDIT-TX CATCH
    DUP IF
        2DROP PERSIST-S-FAULT
    ELSE
        DROP
    THEN
    DUP R@ _LIBPIX.TEMP-STATUS !
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-PROPOSED-ROOT@ IF
        R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        R@ _LIBPIX.PSTORE-WORK @ PSTORE-ABORT
        DUP IF R@ _LIBPIX.TEMP-STATUS ! ELSE DROP THEN
    THEN
    DROP R@ _LIBPIX.TEMP-STATUS @ R> DROP ;

: _LIBPIX-LOAD-CURRENT  ( index-work -- status )
    >R
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-CURRENT-ROOT@
    DUP 0= IF DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    PROOTV.APPLICATION-ROOT @ DUP 0< IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE-ID !
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX.APP-ROOT-PAGE !
    R@ _LIBPIX.PAGE-ID @
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-PAGE
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-PAGE-PAYLOAD$
    R> _LIBPIX-ROOT>WORK ;

: _LIBPIX-BIND-EMPTY-RECLAIM  ( index-work -- status )
    >R
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE + RECLAIM-STATE-SIZE
        RECLAIM-STATE-INIT
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PAGE _LIBPAR-RECLAIM-STATE + RECLAIM-STATE-SIZE
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ R@ _LIBPIX.RECLAIM
        RECLAIM-OPEN _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPIX-OPEN-EMPTY  ( index-work -- status )
    >R
    R@ _LIBPIX-ROOTS-INIT DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-BIND-EMPTY-RECLAIM DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.LOGICAL-GENERATION !
    0 R@ _LIBPIX.MUTATION-SEQUENCE !
    0 R@ _LIBPIX.DOCUMENT-COUNT !
    0 R@ _LIBPIX.COLLECTION-COUNT !
    0 R@ _LIBPIX.MEMBERSHIP-COUNT !
    0 R@ _LIBPIX.AUDIT-MAP-U !
    R@ _LIBPIX.BOOTSTRAP-ID RID-SIZE 0 FILL
    0 R@ _LIBPIX.STAGING-ACTIVE !
    -1 R@ _LIBPIX.APP-ROOT-PAGE !
    _LIBPIX-STATE-READY R@ _LIBPIX.STATE !
    R> DROP LIBPA-S-ABSENT ;

: _LIBPIX-OPEN-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE = IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    _LIBPIX-STATE-REOPEN R@ _LIBPIX.STATE !
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-OPEN
    DUP PERSIST-S-ABSENT = IF
        DROP R> _LIBPIX-OPEN-EMPTY EXIT
    THEN
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-CURRENT-ROOT@
    DUP 0= IF DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    PROOTV.APPLICATION-ROOT @ 0< IF
        R> _LIBPIX-OPEN-EMPTY EXIT
    THEN
    R@ _LIBPIX-LOAD-CURRENT
    DUP IF R> DROP EXIT THEN DROP
    _LIBPIX-STATE-REOPEN R@ _LIBPIX.STATE !
    R@ _LIBPIX-COLD-AUDIT _LIBPA-PERSIST>STATUS
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.RECLAIM RECLAIM-AUDITED-GENERATION@
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-GENERATION@ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    _LIBPIX-STATE-READY R@ _LIBPIX.STATE !
    R> DROP LIBPA-S-OK ;

: LIBPA-INDEX-OPEN  ( adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R 2DROP R> EXIT
    THEN DROP
    DUP ['] _LIBPIX-OPEN-RUN _LIBPIX-WORK-CATCH
    ROT ROT _LIBPIX-LEAVE ;

: LIBPA-INDEX-REBIND  ( adapter index-work -- status )
    LIBPA-INDEX-OPEN ;

: _LIBPIX-ABORT-ACTIVE  ( primary-status index-work -- final-status )
    >R
    DUP R@ _LIBPIX.TEMP-STATUS !
    \ Reclaim abort deliberately follows the page-store abort.  The
    \ reclaimer's proposal-local allocation/discard ledger remains fenced
    \ while PSTORE still advertises an active proposed root.
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-PROPOSED-ROOT@ IF
        R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        R@ _LIBPIX.PSTORE-WORK @ PSTORE-ABORT
        DUP PERSIST-S-OK <> IF
            _LIBPA-PERSIST>STATUS R@ _LIBPIX.TEMP-STATUS !
        ELSE
            DROP
        THEN
    THEN
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-PROPOSED-ROOT@ 0= IF
        R@ _LIBPIX.RECLAIM-WORK RECLAIM-ABORT
        DUP PERSIST-S-OK <> IF
            _LIBPA-PERSIST>STATUS R@ _LIBPIX.TEMP-STATUS !
        ELSE
            DROP
        THEN
    THEN
    _LIBPIX-STATE-REOPEN R@ _LIBPIX.STATE !
    DROP R@ _LIBPIX.TEMP-STATUS @ R> DROP ;

: _LIBPIX-FAIL-ACTIVE  ( status index-work -- status )
    >R
    DUP IF
        R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE = IF
            R@ _LIBPIX-ABORT-ACTIVE
        THEN
    THEN
    R> DROP ;

: _LIBPIX-ABORT-STORE-PRIMARY  ( primary-status index-work -- final-status )
    >R
    DUP R@ _LIBPIX.TEMP-STATUS !
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-ABORT
    DUP PERSIST-S-OK <> IF
        _LIBPA-PERSIST>STATUS R@ _LIBPIX.TEMP-STATUS !
    ELSE
        DROP
    THEN
    DROP R@ _LIBPIX.TEMP-STATUS @ R> DROP ;

: _LIBPIX-BEGIN-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE = IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-REOPEN = IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-GENERATION@
        R@ _LIBPIX.BASE-GENERATION !
    R@ _LIBPIX.RECLAIM RECLAIM-STORE@ 0= IF
        R@ _LIBPIX.BASE-GENERATION @ IF
            R> DROP LIBPA-S-CONFLICT EXIT
        THEN
        R@ _LIBPIX-BIND-EMPTY-RECLAIM
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPIX.BASE-GENERATION @ IF
        R@ _LIBPIX-ROOTS-CURRENT? 0= IF
            R> DROP LIBPA-S-CONFLICT EXIT
        THEN
    THEN
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-CURRENT-ROOT@
    DUP IF
        PROOTV.APPLICATION-ROOT @
    ELSE
        DROP -1
    THEN
    R@ _LIBPIX.OLD-ROOT-PAGE !
    0 R@ _LIBPIX.RECLAIM-STEP-CALLS !
    0 R@ _LIBPIX.RECLAIM-MOVED !
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-BEGIN
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.RECLAIM
    R@ _LIBPIX.RECLAIM-WORK RECLAIM-TX-BEGIN
    DUP IF
        _LIBPA-PERSIST>STATUS R@ _LIBPIX-ABORT-STORE-PRIMARY
        R> DROP EXIT
    THEN DROP
    _LIBPIX-STATE-ACTIVE R@ _LIBPIX.STATE !
    R@ _LIBPIX.OLD-ROOT-PAGE @ 0>= IF
        R@ _LIBPIX.OLD-ROOT-PAGE 1 R@ _LIBPIX.RECLAIM-WORK
            RECLAIM-RETIRE-BATCH
        DUP IF
            _LIBPA-PERSIST>STATUS R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
        THEN DROP
    THEN
    R@ _LIBPIX.BASE-GENERATION @ 0= IF
        R@ _LIBPIX-ROOTS-INIT DUP IF
            R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
        THEN DROP
    THEN
    0 R@ _LIBPIX.DOCUMENT-N !
    0 R@ _LIBPIX.EDGE-N !
    0 R@ _LIBPIX.RAW-N !
    0 R@ _LIBPIX.PHYSICAL-ONLY-N !
    -1 R@ _LIBPIX.APP-ROOT-PAGE !
    R@ _LIBPIX.BLOB PBLOB-SIZE 0 FILL
    R> DROP LIBPA-S-OK ;

: LIBPA-INDEX-BEGIN  ( adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R 2DROP R> EXIT THEN DROP
    DUP ['] _LIBPIX-BEGIN-RUN _LIBPIX-WORK-CATCH
    OVER _LIBPIX-FAIL-ACTIVE
    ROT ROT _LIBPIX-LEAVE ;

: _LIBPIX-ABORT-RUN  ( index-work -- status )
    DUP _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        DROP LIBPA-S-BUSY EXIT
    THEN
    LIBPA-S-OK SWAP _LIBPIX-ABORT-ACTIVE ;

: LIBPA-INDEX-ABORT  ( adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R 2DROP R> EXIT THEN DROP
    DUP ['] _LIBPIX-ABORT-RUN _LIBPIX-WORK-CATCH
    ROT ROT _LIBPIX-LEAVE ;

\ ---------------------------------------------------------------------
\ Indexed construction: real Library records, history, and raw content
\ ---------------------------------------------------------------------

: _LIBPIX-SPAN-SAFE?  ( a u index-work -- flag )
    >R
    DUP IF OVER 0= IF 2DROP R> DROP 0 EXIT THEN THEN
    2DUP MSPAN-NONWRAPPING? 0= IF 2DROP R> DROP 0 EXIT THEN
    2DUP R@ LIBPA-INDEX-WORK-SIZE MSPAN-OVERLAP? IF
        2DROP R> DROP 0 EXIT
    THEN
    2DUP R@ _LIBPIX.PSTORE-WORK @ PSTORE-WORK-SIZE
        MSPAN-OVERLAP? IF 2DROP R> DROP 0 EXIT THEN
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-WORK-RECORD-BUFFER$
    2OVER MSPAN-OVERLAP? IF 2DROP R> DROP 0 EXIT THEN
    2DUP R@ _LIBPIX.ADAPTER @ LIBPA-SIZE
        MSPAN-OVERLAP? IF 2DROP R> DROP 0 EXIT THEN
    2DUP R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        PSTORE-SPAN-DISJOINT? 0= IF 2DROP R> DROP 0 EXIT THEN
    2DROP R> DROP -1 ;

: _LIBPIX-RID-INPUT?  ( rid index-work -- flag )
    >R
    DUP RID-SIZE R@ _LIBPIX-SPAN-SAFE? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    RID-PRESENT? R> DROP ;

: _LIBPIX-COUNT-RESULT  ( status index-work -- count status )
    >R
    DUP IF 0 SWAP ELSE R@ _LIBPIX.RESULT-N @ SWAP THEN
    R> DROP ;

: _LIBPIX-MEMORY-SOURCE
  ( logical-offset destination-a requested-u source-a -- actual-u status )
    >R
    DUP 3 PICK R@ + 3 PICK 3 PICK MOVE
    >R 2DROP DROP R> PERSIST-S-OK
    R> DROP ;

: _LIBPIX-APPEND  ( payload-a payload-u output-ref index-work -- status )
    >R
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-APPEND-RECORD
    _LIBPA-PERSIST>STATUS R> DROP ;

: _LIBPIX-PUT  ( key-a key-u value-a value-u tree-index index-work -- status )
    >R
    DUP 0< OVER _LIBPIX-TREE-COUNT >= OR IF
        DROP _LIBPA-DROP4 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP R@ _LIBPIX.PAGE-ID ! DROP
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-PUT
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.BTREE-WORK PBTREE-RETIRED-PAGES$
    DUP IF
        R@ _LIBPIX.RECLAIM-WORK RECLAIM-RELEASE-BATCH
        DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    ELSE
        2DROP
    THEN
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT PBTREE-ROOT-COPY
    _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPIX-DELETE  ( key-a key-u tree-index index-work -- status )
    >R
    DUP 0< OVER _LIBPIX-TREE-COUNT >= OR IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP R@ _LIBPIX.PAGE-ID ! DROP
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-DELETE
    DUP PERSIST-S-NOT-FOUND = IF
        DROP R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.BTREE-WORK PBTREE-RETIRED-PAGES$
    DUP IF
        R@ _LIBPIX.RECLAIM-WORK RECLAIM-RELEASE-BATCH
        DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    ELSE
        2DROP
    THEN
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-ROOT PBTREE-ROOT-COPY
    _LIBPA-PERSIST>STATUS
    R> DROP ;

\ Hidden staging roots deliberately do not release the pages retired by their
\ copy-on-write mutations.  The visible roots remain authoritative until the
\ final publication, so those old pages are still live.  Intermediate shadow
\ pages become ordinary unreachable compaction input if a process dies before
\ publication.
: _LIBPIX-PUT-STAGED-RAW
  ( key-a key-u value-a value-u tree-index index-work -- status )
    >R
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        _LIBPA-DROP5 R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    DUP 0< OVER _LIBPIX-TREE-COUNT >= OR IF
        DROP _LIBPA-DROP4 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP R@ _LIBPIX.PAGE-ID ! DROP
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-STAGING-ROOT
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-PUT
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.BTREE-WORK PBTREE-RETIRED-PAGES$ 2DROP
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-STAGING-ROOT PBTREE-ROOT-COPY
    _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPIX-DELETE-STAGED-RAW
  ( key-a key-u tree-index index-work -- status )
    >R
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    DUP 0< OVER _LIBPIX-TREE-COUNT >= OR IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP R@ _LIBPIX.PAGE-ID ! DROP
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-STAGING-ROOT
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-DELETE
    DUP PERSIST-S-NOT-FOUND = IF
        DROP R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.BTREE-WORK PBTREE-RETIRED-PAGES$ 2DROP
    R@ _LIBPIX.TEMP-ROOT
    R@ _LIBPIX.PAGE-ID @ R@ _LIBPIX-STAGING-ROOT PBTREE-ROOT-COPY
    _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPIX-GET-STAGED-TX
  ( key-a key-u tree-index index-work -- value-a value-u status )
    >R
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        _LIBPA-DROP3 0 0 LIBPA-S-CONFLICT R> DROP EXIT
    THEN
    DUP 0< OVER _LIBPIX-TREE-COUNT >= OR IF
        _LIBPA-DROP3 0 0 LIBPA-S-INVALID R> DROP EXIT
    THEN
    DUP R@ _LIBPIX-STAGING-ROOT
    OVER R@ _LIBPIX-TREE
    ROT DROP
    R@ _LIBPIX.BTREE-WORK PBTREE-GET-TX
    _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPIX-GET-REF-STAGED
  ( key-a key-u tree-index destination-ref index-work -- status )
    >R
    DUP R@ _LIBPIX.CALLBACK-CONTEXT ! DROP
    R@ _LIBPIX-GET-STAGED-TX
    DUP IF
        >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP PERSIST-REF-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER PERSIST-REF-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER R@ _LIBPIX.CALLBACK-CONTEXT @ PERSIST-REF-COPY
    2DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-ENCODE-LIBRARY-CONTENT  ( content index-work -- status )
    >R
    DUP LIB-CONTENT-VALID? 0= IF DROP R> DROP LIBPA-S-INVALID EXIT THEN
    DUP LIBCT.DATA-U @ R@ _LIBPIX.BLOB PBLOB-TOTAL@ <> IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE DUP LIBPA-CONTENT-DESCRIPTOR-SIZE 0 FILL
    _LIBPA-CONTENT-MAGIC OVER _LIBPAC.MAGIC !
    0 OVER _LIBPAC.FLAGS !
    OVER LIBCT.ID OVER _LIBPAC.RID RID-COPY
    OVER LIBCT.DOMAIN-REVISION @ OVER _LIBPAC.DOMAIN-REVISION !
    OVER LIBCT.CONTENT-REVISION @ OVER _LIBPAC.CONTENT-REVISION !
    OVER LIBCT.KIND @ OVER _LIBPAC.KIND !
    OVER LIBCT.MEDIA @ OVER _LIBPAC.MEDIA !
    OVER LIBCT.DATA-U @ OVER _LIBPAC.DATA-U !
    OVER LIBCT.DIGEST OVER _LIBPAC.DIGEST RID-COPY
    R@ _LIBPIX.BLOB OVER _LIBPAC.BLOB PBLOB-COPY
    DUP IF _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT THEN DROP
    DUP LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    2DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-CONTENT-APPEND  ( index-work -- status )
    >R
    R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-SIZE
    R@ _LIBPIX.HISTORY-REF R@ _LIBPIX-APPEND
    R> DROP ;

: _LIBPIX-METADATA-VALIDATE  ( index-work -- status )
    >R
    R@ _LIBPIX.FACTS-U @ 0< IF R> DROP LIBPA-S-INVALID EXIT THEN
    R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
    R@ _LIBPIX.METADATA-SUMMARY LIB-METADATA-SUMMARIZE
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.METADATA-SUMMARY
    R@ _LIBPIX.ENTRY-ARG @
        LIB-METADATA-SUMMARY-MATCHES-ENTRY? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-METADATA-BLOB-WRITE  ( index-work -- status )
    >R
    R@ _LIBPIX-METADATA-VALIDATE DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.FACTS-U @
    ['] _LIBPIX-MEMORY-SOURCE
    R@ _LIBPIX.FACTS-A @
    R@ _LIBPIX.BLOB
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK PBLOB-WRITE
    _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPIX-METADATA-BLOB-SELECT  ( index-work -- status )
    >R
    R@ _LIBPIX.FACTS-U @ 0>= IF
        R> _LIBPIX-METADATA-BLOB-WRITE EXIT
    THEN
    R@ _LIBPIX.OLD-METADATA-BLOB
    R@ _LIBPIX.BLOB PBLOB-COPY
    _LIBPA-PERSIST>STATUS
    R> DROP ;


: _LIBPIX-COMMIT-DURABLE?  ( index-work -- flag )
    >R
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-GENERATION@
    R@ _LIBPIX.BASE-GENERATION @ 1+ =
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-PROPOSED-ROOT@ 0= AND
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @ PSTORE-UNCERTAIN? 0= AND
    R> DROP ;

: _LIBPIX-PUBLISH-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPIX-ROOTS-ADVANCE DUP IF
        R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN DROP
    R@
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ _LIBPIX-ALLOCATE
    DUP IF
        _LIBPA-PERSIST>STATUS >R DROP R> R@ _LIBPIX-ABORT-ACTIVE
        R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.APP-ROOT-PAGE !
    \ Claim the allocated application-root slot before reclaim finalization.
    \ A fresh high-water id is thereby reflected in the proposed page count;
    \ a reused id is already excluded by the allocation ledger.  Finalization
    \ can consequently allocate its own metadata without aliasing this slot.
    R@ _LIBPIX.PAGE PERSIST-PAGE-PAYLOAD-SIZE 0 FILL
    R@ _LIBPIX.PAGE PERSIST-PAGE-PAYLOAD-SIZE
    R@ _LIBPIX.APP-ROOT-PAGE @
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-WRITE-PAGE-TX
    DUP IF
        _LIBPA-PERSIST>STATUS R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.RECLAIM-WORK RECLAIM-FINALIZE
    DUP IF
        _LIBPA-PERSIST>STATUS R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN DROP
    R@ _LIBPIX-WORK>ROOT DUP IF
        R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.PAGE PERSIST-PAGE-PAYLOAD-SIZE
    R@ _LIBPIX.APP-ROOT-PAGE @
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-WRITE-PAGE-TX
    DUP IF
        _LIBPA-PERSIST>STATUS R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.APP-ROOT-PAGE @
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-APPLICATION-ROOT!
    DUP IF
        _LIBPA-PERSIST>STATUS R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-COMMIT
    _LIBPA-PERSIST>STATUS R@ _LIBPIX.TEMP-STATUS !
    R@ _LIBPIX-COMMIT-DURABLE? IF
        R@ _LIBPIX.RECLAIM-WORK R@ _LIBPIX.RECLAIM RECLAIM-ADOPT
        DUP IF
            _LIBPA-PERSIST>STATUS
            R@ _LIBPIX.TEMP-STATUS @ LIBPA-S-OK = IF
                R@ _LIBPIX.TEMP-STATUS !
            ELSE
                DROP
            THEN
            _LIBPIX-STATE-REOPEN R@ _LIBPIX.STATE !
        ELSE
            DROP
            _LIBPIX-STATE-READY R@ _LIBPIX.STATE !
        THEN
    ELSE
        R@ _LIBPIX.TEMP-STATUS @ R@ _LIBPIX-ABORT-ACTIVE DROP
    THEN
    R@ _LIBPIX.TEMP-STATUS @ R> DROP ;

: _LIBPIX-COMMIT-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPIX.DOCUMENT-N @ R@ _LIBPIX.RAW-N @ OR
    R@ _LIBPIX.EDGE-N @ OR R@ _LIBPIX.PHYSICAL-ONLY-N @ OR 0= IF
        LIBPA-S-INVALID R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN
    R@ _LIBPIX.PHYSICAL-ONLY-N @ 0= IF
        R@ _LIBPIX.LOGICAL-GENERATION @ PERSIST-MAX-SIGNED >= IF
            LIBPA-S-CAPACITY R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
        THEN
        1 R@ _LIBPIX.LOGICAL-GENERATION +!
    THEN
    R@ _LIBPIX-PUBLISH-RUN
    R> DROP ;

\ Staged copy-on-write mutations retain their intermediate paths until the
\ logical publication. Reserve against the transaction's live public reclaim
\ ledgers, not a fixed number of rows: one mutation can claim 2h+1 strict
\ high-water pages at the tallest current staging root, and final publication
\ needs one consumer-issued application-root page. The staging claims cannot
\ drain ready buckets. Retirement reserve instead covers the maintenance
\ source/output pair, application-root allocation, and each bounded
\ pending/discard metadata allocation during reclaim finalization.
RECLAIM-RETIRED-MAX RECLAIM-MAX-BATCH 1- +
    RECLAIM-MAX-BATCH /
RECLAIM-DISCARD-MAX RECLAIM-MAX-BATCH 1- +
    RECLAIM-MAX-BATCH / +
    CONSTANT _LIBPIX-RECLAIM-FINALIZER-PAGE-MAX
2 CONSTANT _LIBPIX-RECLAIM-STEP-RETIRE-PAGE-MAX

: _LIBPIX-STAGING-MUTATION-PAGES  ( index-work -- count )
    0
    _LIBPIX-TREE-COUNT 0 ?DO
        I 2 PICK _LIBPIX-STAGING-ROOT PBTREE-ROOT-HEIGHT@ MAX
    LOOP
    2 * 1+
    NIP ;

: _LIBPIX-STAGE-NEXT-ROOM?  ( index-work -- flag )
    >R
    R@ _LIBPIX-STAGING-MUTATION-PAGES 1+
    _LIBPIX-RECLAIM-STEP-RETIRE-PAGE-MAX
    1+ _LIBPIX-RECLAIM-FINALIZER-PAGE-MAX +
    0 R@ _LIBPIX.RECLAIM-WORK RECLAIM-TX-ROOM?
    R> DROP ;

: _LIBPIX-STAGE-BEGIN  ( index-work -- status )
    >R
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        R@ _LIBPIX-ROOTS>STAGING
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPIX-BEGIN-RUN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-STAGE-NEXT-ROOM? 0= IF
        LIBPA-S-CAPACITY R@ _LIBPIX-ABORT-ACTIVE
        R> DROP EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-STAGE-PUBLISH  ( index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPIX-STAGING-ROOTS-ADVANCE
    DUP IF R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT THEN DROP
    1 R@ _LIBPIX.PHYSICAL-ONLY-N !
    R@ _LIBPIX-PUBLISH-RUN
    R> DROP ;

: _LIBPIX-STAGE-FINAL-PUBLISH  ( index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPIX.LOGICAL-GENERATION @ PERSIST-MAX-SIGNED >= IF
        LIBPA-S-CAPACITY R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT
    THEN
    R@ _LIBPIX-STAGING-ROOTS-ADVANCE
    DUP IF R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT THEN DROP
    R@ _LIBPIX-STAGING>ROOTS
    DUP IF R@ _LIBPIX-ABORT-ACTIVE R> DROP EXIT THEN DROP
    1 R@ _LIBPIX.LOGICAL-GENERATION +!
    0 R@ _LIBPIX.PHYSICAL-ONLY-N !
    R@ _LIBPIX-PUBLISH-RUN
    0 R@ _LIBPIX.STAGING-ACTIVE !
    R> DROP ;

: _LIBPIX-STAGE-DISCARD  ( primary-status index-work -- final-status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE = IF
        R@ _LIBPIX-ABORT-ACTIVE
        \ Exact one-call mutations own their complete transaction lifetime.
        \ Restore the durable index view after abort so a rejected value does
        \ not force the semantic owner to perform an out-of-band rebind.
        R@ _LIBPIX-OPEN-RUN
        DUP LIBPA-S-OK =
        OVER LIBPA-S-ABSENT = OR
        IF DROP ELSE NIP THEN
    THEN
    0 R@ _LIBPIX.STAGING-ACTIVE !
    R> DROP ;

: _LIBPIX-STAGE-ENSURE-NEXT  ( index-work -- status )
    >R
    R@ _LIBPIX-STAGE-NEXT-ROOM? IF
        R> DROP LIBPA-S-OK EXIT
    THEN
    \ The just-completed mutation was admitted with room for this publication.
    \ Persist the visible roots without advancing the logical generation, then
    \ continue from the in-memory staging roots in a fresh transaction.
    R@ _LIBPIX-STAGE-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-STAGE-BEGIN
    R> DROP ;

: _LIBPIX-PUT-STAGED
  ( key-a key-u value-a value-u tree-index index-work -- status )
    >R
    \ Publication cannot occur before the mutation because callers commonly
    \ construct keys/values in this same work object's scratch spans.  The
    \ previous mutation (or STAGE-BEGIN) guarantees this precondition.
    R@ _LIBPIX-STAGE-NEXT-ROOM? 0= IF
        _LIBPA-DROP5 R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX-PUT-STAGED-RAW
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-STAGE-ENSURE-NEXT
    R> DROP ;

: _LIBPIX-DELETE-STAGED
  ( key-a key-u tree-index index-work -- status )
    >R
    R@ _LIBPIX-STAGE-NEXT-ROOM? 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX-DELETE-STAGED-RAW
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-STAGE-ENSURE-NEXT
    R> DROP ;

: _LIBPIX-COMMIT-FINALIZE  ( primary-status index-work -- final-status )
    >R
    DUP R@ _LIBPIX.TEMP-STATUS !
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        R> DROP EXIT
    THEN
    R@ _LIBPIX-COMMIT-DURABLE? IF
        R@ _LIBPIX.RECLAIM-WORK R@ _LIBPIX.RECLAIM RECLAIM-ADOPT
        DUP IF
            _LIBPA-PERSIST>STATUS
            R@ _LIBPIX.TEMP-STATUS @ LIBPA-S-OK = IF
                R@ _LIBPIX.TEMP-STATUS !
            ELSE
                DROP
            THEN
            _LIBPIX-STATE-REOPEN R@ _LIBPIX.STATE !
        ELSE
            DROP
            _LIBPIX-STATE-READY R@ _LIBPIX.STATE !
        THEN
    ELSE
        R@ _LIBPIX-ABORT-ACTIVE
    THEN
    DROP R@ _LIBPIX.TEMP-STATUS @ R> DROP ;

: LIBPA-INDEX-COMMIT  ( adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R 2DROP R> EXIT THEN DROP
    DUP ['] _LIBPIX-COMMIT-RUN _LIBPIX-WORK-CATCH
    OVER _LIBPIX-COMMIT-FINALIZE
    ROT ROT _LIBPIX-LEAVE ;

\ ---------------------------------------------------------------------
\ Point lookup, explicit edges, and bounded stable-key slices
\ ---------------------------------------------------------------------

: _LIBPIX-READY?  ( index-work -- flag )
    DUP _LIBPIX.STATE @ _LIBPIX-STATE-READY =
    OVER _LIBPIX.RECLAIM RECLAIM-STORE@ 0<> AND
    SWAP DROP ;

: LIBPA-INDEX-LOGICAL-GENERATION@  ( index-work -- generation|-1 )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP -1 EXIT THEN
    DUP _LIBPIX-READY? IF _LIBPIX.LOGICAL-GENERATION @ ELSE DROP -1 THEN ;

: LIBPA-INDEX-MUTATION-SEQUENCE@  ( index-work -- sequence|-1 )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP -1 EXIT THEN
    DUP _LIBPIX-READY? IF _LIBPIX.MUTATION-SEQUENCE @ ELSE DROP -1 THEN ;

: LIBPA-INDEX-DOCUMENT-COUNT@  ( index-work -- count|-1 )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP -1 EXIT THEN
    DUP _LIBPIX-READY? IF _LIBPIX.DOCUMENT-COUNT @ ELSE DROP -1 THEN ;

: LIBPA-INDEX-COLLECTION-COUNT@  ( index-work -- count|-1 )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP -1 EXIT THEN
    DUP _LIBPIX-READY? IF _LIBPIX.COLLECTION-COUNT @ ELSE DROP -1 THEN ;

: LIBPA-INDEX-MEMBERSHIP-COUNT@  ( index-work -- count|-1 )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP -1 EXIT THEN
    DUP _LIBPIX-READY? IF _LIBPIX.MEMBERSHIP-COUNT @ ELSE DROP -1 THEN ;

: LIBPA-INDEX-ACTIVE-ROOT@  ( index-work -- application-root-page|-1 )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP -1 EXIT THEN
    DUP _LIBPIX-READY? IF _LIBPIX.APP-ROOT-PAGE @ ELSE DROP -1 THEN ;

: LIBPA-INDEX-BOOTSTRAP-ID@
  ( destination index-work -- status )
    >R
    R@ LIBPA-INDEX-WORK-VALID? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX-READY? 0= IF DROP R> DROP LIBPA-S-BUSY EXIT THEN
    DUP RID-SIZE R@ _LIBPIX-SPAN-SAFE? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.BOOTSTRAP-ID RID-SIZE _LIBPA-ZERO? IF
        DROP R> DROP LIBPA-S-ABSENT EXIT
    THEN
    R@ _LIBPIX.BOOTSTRAP-ID SWAP RID-COPY
    R> DROP LIBPA-S-OK ;

: _LIBPIX-BOOTSTRAP-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.BOOTSTRAP-ID RID-SIZE _LIBPA-ZERO? 0= IF
        R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.BOOTSTRAP-ID RID=
        IF LIBPA-S-OK ELSE LIBPA-S-CONFLICT THEN
        R> DROP EXIT
    THEN
    R@ _LIBPIX-BEGIN-RUN DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.BOOTSTRAP-ID RID-COPY
    1 R@ _LIBPIX.PHYSICAL-ONLY-N !
    R@ _LIBPIX-COMMIT-RUN
    R> DROP ;

: LIBPA-INDEX-BOOTSTRAP-EXACT
  ( bootstrap-id adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP3 R> EXIT
    THEN DROP
    >R
    OVER R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-BOOTSTRAP-RUN _LIBPIX-WORK-CATCH
    R@ _LIBPIX-FAIL-ACTIVE
    SWAP R@ _LIBPIX-LEAVE
    >R DROP R> R> DROP ;

\ The explicit name used by the complete owner.  Provisioning is set-once:
\ replay of the same exact 32 bytes is a no-op and a different identity
\ conflicts.
: LIBPA-INDEX-PROVISION  ( bootstrap-id adapter index-work -- status )
    LIBPA-INDEX-BOOTSTRAP-EXACT ;

: _LIBPIX-GET-REF
  ( key-a key-u tree-index destination-ref index-work -- status )
    >R
    DUP R@ _LIBPIX.CALLBACK-CONTEXT ! DROP
    DUP 0< OVER _LIBPIX-TREE-COUNT >= OR IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP R@ _LIBPIX.PAGE-ID !
    DUP R@ _LIBPIX-ROOT
    OVER R@ _LIBPIX-TREE
    ROT DROP
    R@ _LIBPIX.BTREE-WORK PBTREE-GET
    DUP IF
        _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP PERSIST-REF-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER PERSIST-REF-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER R@ _LIBPIX.CALLBACK-CONTEXT @ PERSIST-REF-COPY
    2DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-RID-LOOKUP-CORE  ( index-work -- status )
    >R
    R@ _LIBPIX.RID-ARG @ RID-PRESENT? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.KEY0 LIBPI-RID-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RID-KEY-SIZE _LIBPIX-RID-DIRECTORY
    R@ _LIBPIX.RECORD-REF R@ _LIBPIX-GET-REF
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.RECORD-REF
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-RECORD-PAYLOAD$
    2DUP LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-SIZE MOVE
    R@ _LIBPIX.PAGE LIBPA-DOCUMENT-RECORD-DECODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.PAGE LIBE.ID R@ _LIBPIX.RID-ARG @ RID= 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: _LIBPIX-RID-LOOKUP-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE R@ _LIBPIX-SPAN-SAFE? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R> _LIBPIX-RID-LOOKUP-CORE ;

: LIBPA-INDEX-RID-LOOKUP  ( rid entry-destination adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R _LIBPA-DROP4 R> EXIT THEN DROP
    >R
    1 PICK R@ _LIBPIX.ENTRY-ARG !
    2 PICK R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-RID-LOOKUP-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R 2DROP R> R> DROP ;

: _LIBPIX-LOAD-CURRENT-CONTENT  ( index-work -- status )
    >R
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-SIZE
        LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE _LIBPAD.CONTENT-REF DUP PERSIST-REF-VALID? 0= IF
        DROP R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-RECORD-PAYLOAD$
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-LOAD-HISTORY  ( rid revision index-work -- status )
    >R
    2DUP R@ _LIBPIX.KEY0 LIBPI-HISTORY-KEY
    DUP IF _LIBPA-LIB>STATUS >R 2DROP R> R> DROP EXIT THEN DROP
    2DROP
    R@ _LIBPIX.KEY0 LIBPI-HISTORY-KEY-SIZE _LIBPIX-HISTORY
    R@ _LIBPIX.HISTORY-REF R@ _LIBPIX-GET-REF
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.HISTORY-REF
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-RECORD-PAYLOAD$
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE LIBPA-CONTENT-RID@
    R@ _LIBPIX.RID-ARG @ RID= 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE DUP LIBPA-CONTENT-RAW? IF
        LIBPA-CONTENT-REVISION@
    ELSE
        LIBPA-CONTENT-DOMAIN-REVISION@
    THEN
    R@ _LIBPIX.REVISION-ARG @ <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-HISTORY-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.REVISION-ARG @ 0> 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.CONTENT-ARG @ LIBPA-CONTENT-DESCRIPTOR-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP LIBPA-S-INVALID EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.REVISION-ARG @
    R@ _LIBPIX-LOAD-HISTORY DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.STAGE R@ _LIBPIX.CONTENT-ARG @
        LIBPA-CONTENT-DESCRIPTOR-COPY
    R> DROP ;

: LIBPA-INDEX-HISTORY
  ( rid revision descriptor-destination adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R _LIBPA-DROP5 R> EXIT THEN DROP
    >R
    1 PICK R@ _LIBPIX.CONTENT-ARG !
    2 PICK R@ _LIBPIX.REVISION-ARG !
    3 PICK R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-HISTORY-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP3 R> R> DROP ;

: _LIBPIX-MEMBER-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OTHER-RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    0 R@ _LIBPIX.RESULT-N !
    \ Ordered membership keys include the member's immutable creation
    \ sequence.  Resolve that semantic field before the point lookup instead
    \ of probing the obsolete unordered edge-key shape in the same tree.
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.ACTIVE-RID RID-COPY
    R@ _LIBPIX.OTHER-RID-ARG @ R@ _LIBPIX.RID-ARG !
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
    R@ _LIBPIX-RID-LOOKUP-CORE
    DUP LIBPA-S-NOT-FOUND = IF
        DROP R> DROP LIBPA-S-OK EXIT
    THEN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ACTIVE-RID
    R@ _LIBPIX.OLD-ENTRY LIBE.CREATED-VALUE @
    R@ _LIBPIX.OLD-ENTRY LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-KEY-SIZE
    _LIBPIX-MEMBERSHIP R@ _LIBPIX-ROOT
    _LIBPIX-MEMBERSHIP R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-GET
    DUP PERSIST-S-NOT-FOUND = IF
        DROP 2DROP R> DROP LIBPA-S-OK EXIT
    THEN
    DUP IF
        _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP 0<> IF 2DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    2DROP
    -1 R@ _LIBPIX.RESULT-N !
    R> DROP LIBPA-S-OK ;

: LIBPA-INDEX-MEMBER?
  ( collection-rid member-rid adapter index-work -- member? status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP4 0 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.OTHER-RID-ARG !
    2 PICK R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-MEMBER-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    R@ _LIBPIX-COUNT-RESULT
    >R >R 2DROP R> R> R> DROP ;

: _LIBPIX-TAG-MEMBER-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-VALID? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    0 R@ _LIBPIX.RESULT-N !
    R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.CREATED-VALUE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-TAG-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-TAG-KEY-SIZE
    _LIBPIX-TAG-POSTINGS R@ _LIBPIX-ROOT
    _LIBPIX-TAG-POSTINGS R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-GET
    DUP PERSIST-S-NOT-FOUND = IF
        DROP 2DROP R> DROP LIBPA-S-OK EXIT
    THEN
    DUP IF
        _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP RID-SIZE <> IF 2DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    OVER R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID= 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    2DROP
    -1 R@ _LIBPIX.RESULT-N !
    R> DROP LIBPA-S-OK ;

: LIBPA-INDEX-TAG?
  ( tag-a tag-u entry adapter index-work -- tagged? status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP5 0 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.ENTRY-ARG !
    2 PICK R@ _LIBPIX.TOTAL-ARG !
    3 PICK R@ _LIBPIX.MEMBER-ARG !
    R@ ['] _LIBPIX-TAG-MEMBER-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    R@ _LIBPIX-COUNT-RESULT
    >R >R _LIBPA-DROP3 R> R> R> DROP ;


: _LIBPIX-RANGE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIBPA-CONTENT-DESCRIPTOR-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP LIBPA-S-INVALID EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ _LIBPAC.BLOB
    R@ _LIBPIX.REVISION-ARG @ R@ _LIBPIX.TOTAL-ARG @
    R@ _LIBPIX.CALLBACK-XT @ R@ _LIBPIX.CALLBACK-CONTEXT @
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK
        PBLOB-READ-RANGE _LIBPA-PERSIST>STATUS
    R> DROP ;

: LIBPA-CONTENT-RANGE
  ( descriptor offset requested-u sink-xt sink-context adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP6 DROP R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.CALLBACK-CONTEXT !
    2 PICK R@ _LIBPIX.CALLBACK-XT !
    3 PICK R@ _LIBPIX.TOTAL-ARG !
    4 PICK R@ _LIBPIX.REVISION-ARG !
    5 PICK R@ _LIBPIX.ENTRY-ARG !
    R@ ['] _LIBPIX-RANGE-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP5 R> R> DROP ;

: _LIBPIX-STREAM-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIBPA-CONTENT-DESCRIPTOR-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP LIBPA-S-INVALID EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ _LIBPAC.BLOB
    R@ _LIBPIX.REVISION-ARG @
    R@ _LIBPIX.CALLBACK-XT @ R@ _LIBPIX.CALLBACK-CONTEXT @
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK
        PBLOB-STREAM _LIBPA-PERSIST>STATUS
    R> DROP ;

: LIBPA-CONTENT-STREAM
  ( descriptor offset sink-xt sink-context adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R _LIBPA-DROP6 R> EXIT THEN DROP
    >R
    1 PICK R@ _LIBPIX.CALLBACK-CONTEXT !
    2 PICK R@ _LIBPIX.CALLBACK-XT !
    3 PICK R@ _LIBPIX.REVISION-ARG !
    4 PICK R@ _LIBPIX.ENTRY-ARG !
    R@ ['] _LIBPIX-STREAM-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP4 R> R> DROP ;

: LIBPA-INDEX-PAGE-READS@  ( index-work -- u )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP 0 EXIT THEN
    0
    _LIBPIX-TREE-COUNT 0 ?DO
        OVER I SWAP _LIBPIX-TREE PBTREE-PAGE-READS@ +
    LOOP
    NIP ;

: LIBPA-INDEX-PAGE-WRITES@  ( index-work -- u )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP 0 EXIT THEN
    0
    _LIBPIX-TREE-COUNT 0 ?DO
        OVER I SWAP _LIBPIX-TREE PBTREE-PAGE-WRITES@ +
    LOOP
    NIP ;

: LIBPA-INDEX-COMPARISONS@  ( index-work -- u )
    DUP LIBPA-INDEX-WORK-VALID? 0= IF DROP 0 EXIT THEN
    0
    _LIBPIX-TREE-COUNT 0 ?DO
        OVER I SWAP _LIBPIX-TREE PBTREE-COMPARISONS@ +
    LOOP
    NIP ;

: LIBPA-INDEX-WORKING-BYTES@  ( index-work -- u )
    DUP LIBPA-INDEX-WORK-VALID? IF
        DROP LIBPA-INDEX-WORK-SIZE
    ELSE
        DROP 0
    THEN ;

: LIBPA-INDEX-AUDIT-MAP-CAPACITY@  ( index-work -- u|-1 )
    DUP LIBPA-INDEX-WORK-VALID? IF
        _LIBPIX.AUDIT-MAP-CAPACITY @
    ELSE
        DROP -1
    THEN ;

: LIBPA-INDEX-AUDIT-MAP-REQUIRED@  ( index-work -- u|-1 )
    DUP LIBPA-INDEX-WORK-VALID? IF
        _LIBPIX.AUDIT-MAP-U @
    ELSE
        DROP -1
    THEN ;

: LIBPA-INDEX-AUDITED-GENERATION@  ( index-work -- generation|-1 )
    DUP LIBPA-INDEX-WORK-VALID? IF
        _LIBPIX.RECLAIM RECLAIM-AUDITED-GENERATION@
    ELSE
        DROP -1
    THEN ;

: LIBPA-RECLAIM-STEP-CALLS@  ( index-work -- u )
    DUP LIBPA-INDEX-WORK-VALID? IF
        _LIBPIX.RECLAIM-STEP-CALLS @
    ELSE
        DROP 0
    THEN ;

: LIBPA-RECLAIM-MOVED@  ( index-work -- u )
    DUP LIBPA-INDEX-WORK-VALID? IF
        _LIBPIX.RECLAIM-MOVED @
    ELSE
        DROP 0
    THEN ;


\ =====================================================================
\ Complete-owner exact document surface
\ =====================================================================
\ These calls are the L12 authority seam.  They pin the Library logical
\ generation independently of PSTORE's physical generation and publish
\ caller-owned outputs only after the final logical root is durable.

1 CONSTANT LIBPA-CANDIDATE-TITLE
2 CONSTANT LIBPA-CANDIDATE-BODY
PBLOB-CHUNK-SIZE LIBPI-MEMBERSHIP-KEY-SIZE /
    CONSTANT _LIBPIX-MEMBERSHIP-SCRATCH-MAX

: _LIBPIX-CANDIDATE-BATCH-NOTE  ( index-work -- status )
    1 SWAP _LIBPIX.PROGRESS +!
    LIBPA-S-OK ;

: _LIBPIX-CANDIDATE-KEY  ( candidate-a candidate-u index-work -- status )
    >R
    R@ _LIBPIX.ENTRY-ARG @ LIBE.CREATED-VALUE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-BODY-KEY
    _LIBPA-LIB>STATUS
    R> DROP ;

: _LIBPIX-CANDIDATE-OR
  ( candidate-a candidate-u mask index-work -- status )
    >R
    DUP LIBPA-CANDIDATE-TITLE =
    OVER LIBPA-CANDIDATE-BODY = OR 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND !
    R@ _LIBPIX-CANDIDATE-KEY
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-BODY-KEY-SIZE
    _LIBPIX-BODY-POSTINGS R@ _LIBPIX-GET-STAGED-TX
    DUP PERSIST-S-NOT-FOUND = IF
        DROP 2DROP 0
    ELSE
        DUP IF
            >R 2DROP R> R> DROP EXIT
        THEN DROP
        DUP 1 <> IF
            2DROP R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        DROP C@
    THEN
    DUP R@ _LIBPIX.OPERATION-KIND @ AND IF
        DROP R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND @ OR R@ _LIBPIX.TEMP-STATUS !
    R@ _LIBPIX.KEY0 LIBPI-BODY-KEY-SIZE
    R@ _LIBPIX.TEMP-STATUS 1
    _LIBPIX-BODY-POSTINGS R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX-CANDIDATE-BATCH-NOTE ;

: _LIBPIX-CANDIDATE-DIFFERS-FROM-PREVIOUS?
  ( candidate-u index-work -- flag )
    >R
    R@ _LIBPIX.TOTAL-ARG @ 0= IF
        DROP R> DROP -1 EXIT
    THEN
    R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @ +
    R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @ 1- +
    ROT _LIBPA-BYTES= 0=
    R> DROP ;

: _LIBPIX-CANDIDATES-ADD
  ( bytes-a bytes-u field-mask index-work -- status )
    >R
    DUP LIBPA-CANDIDATE-TITLE =
    OVER LIBPA-CANDIDATE-BODY = OR 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND !
    DUP 0< IF 2DROP R> DROP LIBPA-S-INVALID EXIT THEN
    DUP 0> IF
        OVER 0= IF 2DROP R> DROP LIBPA-S-INVALID EXIT THEN
        2DUP MSPAN-NONWRAPPING? 0= IF
            2DROP R> DROP LIBPA-S-INVALID EXIT
        THEN
    THEN
    DUP R@ _LIBPIX.PROGRESS-LIMIT !
    OVER R@ _LIBPIX.MEMBER-ARG !
    0 R@ _LIBPIX.TOTAL-ARG !
    2DROP
    BEGIN
        R@ _LIBPIX.TOTAL-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @ <
    WHILE
        1 R@ _LIBPIX-CANDIDATE-DIFFERS-FROM-PREVIOUS? IF
            R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @ + 1
            R@ _LIBPIX.OPERATION-KIND @
            R@ _LIBPIX-CANDIDATE-OR
            DUP IF R> DROP EXIT THEN DROP
        THEN
        R@ _LIBPIX.TOTAL-ARG @ 2 +
            R@ _LIBPIX.PROGRESS-LIMIT @ <= IF
            2 R@ _LIBPIX-CANDIDATE-DIFFERS-FROM-PREVIOUS? IF
                R@ _LIBPIX.MEMBER-ARG @
                R@ _LIBPIX.TOTAL-ARG @ + 2
                R@ _LIBPIX.OPERATION-KIND @
                R@ _LIBPIX-CANDIDATE-OR
                DUP IF R> DROP EXIT THEN DROP
            THEN
        THEN
        R@ _LIBPIX.TOTAL-ARG @ 3 +
            R@ _LIBPIX.PROGRESS-LIMIT @ <= IF
            3 R@ _LIBPIX-CANDIDATE-DIFFERS-FROM-PREVIOUS? IF
                R@ _LIBPIX.MEMBER-ARG @
                R@ _LIBPIX.TOTAL-ARG @ + 3
                R@ _LIBPIX.OPERATION-KIND @
                R@ _LIBPIX-CANDIDATE-OR
                DUP IF R> DROP EXIT THEN DROP
            THEN
        THEN
        1 R@ _LIBPIX.TOTAL-ARG +!
    REPEAT
    R> DROP LIBPA-S-OK ;

: _LIBPIX-KEY-ABSENT-STAGED
  ( key-a key-u tree-index index-work -- status )
    >R
    R@ _LIBPIX-GET-STAGED-TX
    DUP PERSIST-S-NOT-FOUND = IF
        DROP 2DROP R> DROP LIBPA-S-OK EXIT
    THEN
    DUP IF
        >R 2DROP R> R> DROP EXIT
    THEN
    DROP 2DROP R> DROP LIBPA-S-CONFLICT ;

: _LIBPIX-TOKEN-CLASS-ABSENT-STAGED
  ( token class index-work -- status )
    >R
    OVER OVER R@ _LIBPIX.KEY0 LIBPI-DIRECTORY-KEY
    DUP IF
        _LIBPA-LIB>STATUS >R _LIBPA-DROP3 R> R> DROP EXIT
    THEN DROP
    2DROP
    R@ _LIBPIX.KEY0 LIBPI-DIRECTORY-KEY-SIZE
    _LIBPIX-SHARED-DIRECTORY R@ _LIBPIX-KEY-ABSENT-STAGED
    R> DROP ;

: _LIBPIX-TOKEN-ABSENT-STAGED  ( token index-work -- status )
    >R
    DUP LIBPI-DIRECTORY-DOCUMENT
        R@ _LIBPIX-TOKEN-CLASS-ABSENT-STAGED
    DUP IF >R DROP R> R> DROP EXIT THEN DROP
    DUP LIBPI-DIRECTORY-COLLECTION
        R@ _LIBPIX-TOKEN-CLASS-ABSENT-STAGED
    DUP IF >R DROP R> R> DROP EXIT THEN DROP
    LIBPI-DIRECTORY-RECEIPT
        R@ _LIBPIX-TOKEN-CLASS-ABSENT-STAGED
    R> DROP ;

: _LIBPIX-DIRECTORY-PUT-STAGED  ( token class index-work -- status )
    >R
    OVER OVER R@ _LIBPIX.KEY0 LIBPI-DIRECTORY-KEY
    DUP IF
        _LIBPA-LIB>STATUS >R _LIBPA-DROP3 R> R> DROP EXIT
    THEN DROP
    2DROP
    R@ _LIBPIX.KEY0 LIBPI-DIRECTORY-KEY-SIZE
    0 0 _LIBPIX-SHARED-DIRECTORY R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-DOCUMENT-DIRECTORIES-PUT-STAGED
  ( entry index-work -- status )
    >R
    DUP LIBE.ID LIBPI-DIRECTORY-DOCUMENT
        R@ _LIBPIX-DIRECTORY-PUT-STAGED
    DUP IF >R DROP R> R> DROP EXIT THEN DROP
    DUP LIBE.RECEIPT LIBR.OPERATION-KEY
    LIBPI-DIRECTORY-RECEIPT R@ _LIBPIX-DIRECTORY-PUT-STAGED
    DUP IF >R DROP R> R> DROP EXIT THEN DROP
    DUP LIBE.RECEIPT LIBR.OPERATION-KEY
    R@ _LIBPIX.KEY0 LIBPI-OPERATION-KEY
    DUP IF _LIBPA-LIB>STATUS >R DROP R> R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY1 LIBPA-OPERATION-VALUE-SIZE 0 FILL
    LIBPA-OPERATION-DOCUMENT R@ _LIBPIX.KEY1 !
    DUP LIBE.ID R@ _LIBPIX.KEY1 8 + RID-COPY
    DROP
    R@ _LIBPIX.KEY0 LIBPI-OPERATION-KEY-SIZE
    R@ _LIBPIX.KEY1 LIBPA-OPERATION-VALUE-SIZE
    _LIBPIX-OPERATION-RECEIPTS R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-TAG-PUT-STAGED  ( tag-a tag-u index-work -- status )
    >R
    2DUP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.CREATED-VALUE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-TAG-KEY
    DUP IF
        _LIBPA-LIB>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    2DROP
    R@ _LIBPIX.KEY0 LIBPI-TAG-KEY-SIZE
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-TAG-POSTINGS R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-DOCUMENT-TAGS-PUT-STAGED  ( index-work -- status )
    >R
    0 R@ _LIBPIX.PROGRESS !
    BEGIN
        R@ _LIBPIX.PROGRESS @ R@ _LIBPIX.FACTS-U @ <
    WHILE
        R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.PROGRESS @ +
        DUP LIBMF.KIND @ LIB-METADATA-FACT-TAG <> IF
            DROP R> DROP LIBPA-S-OK EXIT
        THEN
        DUP LIBMF.PAYLOAD-U @
        DUP 1 < OVER LIB-TAG-TEXT-MAX > OR IF
            2DROP R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        OVER LIBMF.PAYLOAD SWAP R@ _LIBPIX-TAG-PUT-STAGED
        DUP IF >R DROP R> R> DROP EXIT THEN
        DROP DROP
        R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.PROGRESS @ +
        LIBMF.PAYLOAD-U @ LIB-METADATA-FACT-HEADER-SIZE +
        R@ _LIBPIX.PROGRESS +!
    REPEAT
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-KEYS-ABSENT-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID R@ _LIBPIX-TOKEN-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.RECEIPT LIBR.OPERATION-KEY
        R@ _LIBPIX-TOKEN-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID R@ _LIBPIX.KEY0 LIBPI-RID-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RID-KEY-SIZE
    _LIBPIX-RID-DIRECTORY R@ _LIBPIX-KEY-ABSENT-STAGED
    R> DROP ;

: _LIBPIX-DOCUMENT-FINAL-KEYS-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX-DOCUMENT-DIRECTORIES-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID R@ _LIBPIX.KEY0 LIBPI-RID-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RID-KEY-SIZE
    R@ _LIBPIX.RECORD-REF PERSIST-REF-SIZE
    _LIBPIX-RID-DIRECTORY R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.ENTRY-ARG @ LIBE.CREATED-VALUE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-ORDER-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-ORDER-KEY-SIZE
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-CREATION-ORDER R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-RECENCY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RECENCY-KEY-SIZE
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-RECENCY-ORDER R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.ENTRY-ARG @ LIBE.LIFECYCLE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.KIND @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.MEDIA @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.CREATED-VALUE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-STATE-CREATION-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-STATE-CREATION-KEY-SIZE
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-STATE-ORDER R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.ENTRY-ARG @ LIBE.LIFECYCLE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.KIND @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.MEDIA @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-STATE-RECENCY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-STATE-RECENCY-KEY-SIZE
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-STATE-RECENCY R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.ENTRY-ARG @ LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED <> IF
        R@ _LIBPIX.ENTRY-ARG @ LIBE-TITLE$
        R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
        R@ _LIBPIX.KEY0 LIBPI-TITLE-KEY
        DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
        R@ _LIBPIX.KEY0 LIBPI-TITLE-KEY-SIZE
        R@ _LIBPIX.ENTRY-ARG @ LIBE.ID RID-SIZE
        _LIBPIX-TITLE-ORDER R@ _LIBPIX-PUT-STAGED
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.FACTS-U @ 0>= IF
            R@ _LIBPIX-DOCUMENT-TAGS-PUT-STAGED
            DUP IF R> DROP EXIT THEN DROP
        THEN
    THEN

    R@ _LIBPIX.ENTRY-ARG @ LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED <> IF
        R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
        R@ _LIBPIX.ENTRY-ARG @ LIBE.DOMAIN-REVISION @
        R@ _LIBPIX.KEY0 LIBPI-HISTORY-DOMAIN-KEY
        DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
        R@ _LIBPIX.KEY0 LIBPI-HISTORY-DOMAIN-KEY-SIZE
        R@ _LIBPIX.HISTORY-REF PERSIST-REF-SIZE
        _LIBPIX-HISTORY R@ _LIBPIX-PUT-STAGED
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-OPERATION-LOOKUP-READY  ( operation-key index-work -- status )
    >R
    DUP R@ _LIBPIX-RID-INPUT? 0= IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.KEY0 LIBPI-OPERATION-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-OPERATION-KEY-SIZE
    _LIBPIX-OPERATION-RECEIPTS R@ _LIBPIX-ROOT
    _LIBPIX-OPERATION-RECEIPTS R@ _LIBPIX-TREE
    R@ _LIBPIX.BTREE-WORK PBTREE-GET
    DUP IF
        _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP LIBPA-OPERATION-VALUE-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP
    DUP @ DUP LIBPA-OPERATION-DOCUMENT =
    OVER LIBPA-OPERATION-COLLECTION = OR 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.TEMP-STATUS !
    DUP 8 + RID-PRESENT? 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    8 + R@ _LIBPIX.ACTIVE-RID RID-COPY
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-READY@
  ( rid destination index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF
        2DROP R> DROP LIBPA-S-BUSY EXIT
    THEN
    DUP R@ _LIBPIX.ENTRY-ARG !
    OVER R@ _LIBPIX.RID-ARG !
    R@ _LIBPIX-RID-LOOKUP-CORE
    >R 2DROP R> R> DROP ;

: _LIBPIX-DOCUMENT-STAGED@
  ( rid destination index-work -- status )
    >R
    R@ _LIBPIX.STATE @ _LIBPIX-STATE-ACTIVE <> IF
        2DROP R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPIX.STAGING-ACTIVE @ 0= IF
        2DROP R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    DUP R@ _LIBPIX.ENTRY-ARG !
    OVER R@ _LIBPIX.RID-ARG !
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.KEY0 LIBPI-RID-KEY
    DUP IF
        _LIBPA-LIB>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RID-KEY-SIZE _LIBPIX-RID-DIRECTORY
    R@ _LIBPIX.RECORD-REF R@ _LIBPIX-GET-REF-STAGED
    DUP IF >R 2DROP R> R> DROP EXIT THEN DROP
    R@ _LIBPIX.RECORD-REF
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-RECORD-TX
    DUP IF
        _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-RECORD-PAYLOAD$
    2DUP LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        2DROP 2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    OVER R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-SIZE MOVE
    R@ _LIBPIX.PAGE LIBPA-DOCUMENT-RECORD-DECODE
    DUP IF >R 2DROP R> R> DROP EXIT THEN DROP
    R@ _LIBPIX.PAGE LIBE.ID R@ _LIBPIX.RID-ARG @ RID= 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.PAGE R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE MOVE
    2DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-CREATE-ARGS?  ( index-work -- flag )
    >R
    R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.CONTENT-ARG @ LIB-CONTENT-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX.CONTENT-ARG @
        _LIBPA-PAIR-VALID? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIBE.DOMAIN-REVISION @ 1 <> IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ LIBE.LIFECYCLE @
        LIB-LIFECYCLE-ACTIVE <> IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.CONTENT-ARG @ LIBCT-DATA$
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-U @ DUP 0<
        SWAP LIB-METADATA-LENGTH-MAX > OR IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE
    R@ _LIBPIX.CONTENT-ARG @ LIB-CONTENT-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
    R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
    R@ _LIBPIX.CONTENT-ARG @ LIB-CONTENT-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
    R@ _LIBPIX.ENTRY-ARG @ LIB-ENTRY-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
    R@ _LIBPIX.CONTENT-ARG @ LIB-CONTENT-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        MSPAN-OVERLAP? 0=
    R> DROP ;

: _LIBPIX-DOCUMENT-CREATE-RETRY  ( index-work -- status )
    >R
    R@ _LIBPIX.ENTRY-ARG @ LIBE.RECEIPT LIBR.OPERATION-KEY
        R@ _LIBPIX-OPERATION-LOOKUP-READY
    DUP LIBPA-S-NOT-FOUND = IF R> DROP EXIT THEN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-OPERATION-DOCUMENT <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.ACTIVE-RID R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX-DOCUMENT-READY@
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.RECEIPT
    R@ _LIBPIX.OLD-ENTRY LIBE.RECEIPT LIB-RECEIPT= 0= IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.OUTPUT-ARG @
        LIB-ENTRY-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-BLOB-STAGE  ( index-work -- status )
    >R
    R@ _LIBPIX.CONTENT-ARG @ LIBCT.DATA-U @
    ['] _LIBPIX-MEMORY-SOURCE
    R@ _LIBPIX.CONTENT-ARG @ LIBCT.DATA-A @
    R@ _LIBPIX.BLOB
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK PBLOB-WRITE
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.CONTENT-ARG @ R@ _LIBPIX-ENCODE-LIBRARY-CONTENT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-CONTENT-APPEND
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-METADATA-BLOB-SELECT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX.HISTORY-REF
    R@ _LIBPIX.BLOB
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-ENCODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-SIZE
    R@ _LIBPIX.RECORD-REF R@ _LIBPIX-APPEND
    R> DROP ;

: _LIBPIX-DOCUMENT-CREATE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX-DOCUMENT-CREATE-ARGS? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX-METADATA-VALIDATE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-CREATE-RETRY
    DUP LIBPA-S-OK = IF R> DROP EXIT THEN
    DUP LIBPA-S-NOT-FOUND <> IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.EXPECTED-LOGICAL @
        R@ _LIBPIX.LOGICAL-GENERATION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    0 R@ _LIBPIX.PROGRESS !
    R@ _LIBPIX-STAGE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.ID
        R@ _LIBPIX-TOKEN-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.RECEIPT LIBR.OPERATION-KEY
        R@ _LIBPIX-TOKEN-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-KEYS-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-BLOB-STAGE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE-TITLE$
    LIBPA-CANDIDATE-TITLE R@ _LIBPIX-CANDIDATES-ADD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.CONTENT-ARG @ LIBCT-DATA$
    LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATES-ADD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-FINAL-KEYS-STAGED
    DUP IF R> DROP EXIT THEN DROP
    1 R@ _LIBPIX.DOCUMENT-COUNT +!
    R@ _LIBPIX.ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.MUTATION-SEQUENCE @ MAX
    R@ _LIBPIX.MUTATION-SEQUENCE !
    R@ _LIBPIX-STAGE-FINAL-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX.OUTPUT-ARG @
        LIB-ENTRY-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-DOCUMENT-CREATE-EXACT
  ( entry content facts-a facts-u expected-logical output-entry adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP8 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.OUTPUT-ARG !
    2 PICK R@ _LIBPIX.EXPECTED-LOGICAL !
    3 PICK R@ _LIBPIX.FACTS-U !
    4 PICK R@ _LIBPIX.FACTS-A !
    5 PICK R@ _LIBPIX.CONTENT-ARG !
    6 PICK R@ _LIBPIX.ENTRY-ARG !
    R@ ['] _LIBPIX-DOCUMENT-CREATE-RUN _LIBPIX-WORK-CATCH
    R@ _LIBPIX-STAGE-DISCARD
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP6 R> R> DROP ;

\ ---------------------------------------------------------------------
\ Exact current-document point read
\ ---------------------------------------------------------------------

: _LIBPIX-DESCRIPTOR-AGREES?  ( entry descriptor -- flag )
    >R
    R@ LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    R@ LIBPA-CONTENT-RAW? IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.ID R@ LIBPA-CONTENT-RID@ RID= 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.DOMAIN-REVISION @
        R@ LIBPA-CONTENT-DOMAIN-REVISION@ < IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.CURRENT-CONTENT-REVISION @
        R@ _LIBPAC.CONTENT-REVISION @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.KIND @ R@ _LIBPAC.KIND @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.MEDIA @ R@ _LIBPAC.MEDIA @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.CONTENT-U @ R@ _LIBPAC.DATA-U @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    LIBE.CONTENT-DIGEST R@ _LIBPAC.DIGEST SHA3-256-COMPARE
    R> DROP ;

: _LIBPIX-DOCUMENT-READ-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.CONTENT-ARG @ LIBPA-CONTENT-DESCRIPTOR-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
    R@ _LIBPIX.CONTENT-ARG @ LIBPA-CONTENT-DESCRIPTOR-SIZE
        MSPAN-OVERLAP? IF R> DROP LIBPA-S-INVALID EXIT THEN
    \ RID lookup and descriptor loading are both fallible.  Keep their
    \ results wholly inside caller-owned index-work until the complete
    \ document agrees; a failed second read must not publish the entry from
    \ the successful first read.
    R@ _LIBPIX-RID-LOOKUP-CORE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED = IF
        R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX.OUTPUT-ARG @
            LIB-ENTRY-SIZE MOVE
        R@ _LIBPIX.CONTENT-ARG @ LIBPA-CONTENT-DESCRIPTOR-SIZE 0 FILL
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX-LOAD-CURRENT-CONTENT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX.STAGE
        _LIBPIX-DESCRIPTOR-AGREES? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ R@ _LIBPIX.OUTPUT-ARG @
        LIB-ENTRY-SIZE MOVE
    R@ _LIBPIX.STAGE R@ _LIBPIX.CONTENT-ARG @
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-DOCUMENT-READ
  ( rid entry-destination descriptor-destination adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP5 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.CONTENT-ARG !
    2 PICK R@ _LIBPIX.OUTPUT-ARG !
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
    3 PICK R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-DOCUMENT-READ-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP3 R> R> DROP ;

: _LIBPIX-OPERATION-READ-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ 8 R@ _LIBPIX-SPAN-SAFE? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.CONTENT-ARG @ RID-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.ENTRY-ARG @ 8
    R@ _LIBPIX.CONTENT-ARG @ RID-SIZE MSPAN-OVERLAP? IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-OPERATION-LOOKUP-READY
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.TEMP-STATUS @ R@ _LIBPIX.ENTRY-ARG @ !
    R@ _LIBPIX.ACTIVE-RID R@ _LIBPIX.CONTENT-ARG @ RID-COPY
    R> DROP LIBPA-S-OK ;

: LIBPA-OPERATION-LOOKUP
  ( operation-key kind-out rid-out adapter work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP5 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.CONTENT-ARG !
    2 PICK R@ _LIBPIX.ENTRY-ARG !
    3 PICK R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-OPERATION-READ-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP3 R> R> DROP ;

\ Successor spelling for exact-domain history point reads.
: LIBPA-HISTORY-READ
  ( rid exact-domain descriptor-destination adapter index-work -- status )
    LIBPA-INDEX-HISTORY ;

\ ---------------------------------------------------------------------
\ Targeted secondary-key removal for exact replacement
\ ---------------------------------------------------------------------

: _LIBPIX-CANDIDATE-AND-NOT
  ( candidate-a candidate-u mask index-work -- status )
    >R
    DUP LIBPA-CANDIDATE-TITLE =
    OVER LIBPA-CANDIDATE-BODY = OR 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND !
    R@ _LIBPIX-CANDIDATE-KEY
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-BODY-KEY-SIZE
    _LIBPIX-BODY-POSTINGS R@ _LIBPIX-GET-STAGED-TX
    DUP LIBPA-S-NOT-FOUND = IF
        DROP 2DROP R> DROP LIBPA-S-OK EXIT
    THEN
    DUP IF
        >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP 1 <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP C@
    DUP R@ _LIBPIX.OPERATION-KIND @ AND 0= IF
        DROP R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND @ INVERT AND
    LIBPA-CANDIDATE-TITLE LIBPA-CANDIDATE-BODY OR AND
    DUP R@ _LIBPIX.TEMP-STATUS !
    IF
        R@ _LIBPIX.KEY0 LIBPI-BODY-KEY-SIZE
        R@ _LIBPIX.TEMP-STATUS 1
        _LIBPIX-BODY-POSTINGS R@ _LIBPIX-PUT-STAGED
    ELSE
        R@ _LIBPIX.KEY0 LIBPI-BODY-KEY-SIZE
        _LIBPIX-BODY-POSTINGS R@ _LIBPIX-DELETE-STAGED
    THEN
    DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX-CANDIDATE-BATCH-NOTE ;

: _LIBPIX-CANDIDATES-REMOVE
  ( bytes-a bytes-u field-mask index-work -- status )
    >R
    DUP LIBPA-CANDIDATE-TITLE =
    OVER LIBPA-CANDIDATE-BODY = OR 0= IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND !
    DUP 0< IF 2DROP R> DROP LIBPA-S-INVALID EXIT THEN
    DUP 0> IF
        OVER 0= IF 2DROP R> DROP LIBPA-S-INVALID EXIT THEN
        2DUP MSPAN-NONWRAPPING? 0= IF
            2DROP R> DROP LIBPA-S-INVALID EXIT
        THEN
    THEN
    DUP R@ _LIBPIX.PROGRESS-LIMIT !
    OVER R@ _LIBPIX.MEMBER-ARG !
    0 R@ _LIBPIX.TOTAL-ARG !
    2DROP
    BEGIN
        R@ _LIBPIX.TOTAL-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @ <
    WHILE
        R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @ + 1
        R@ _LIBPIX.OPERATION-KIND @
        R@ _LIBPIX-CANDIDATE-AND-NOT
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.TOTAL-ARG @ 2 +
            R@ _LIBPIX.PROGRESS-LIMIT @ <= IF
            R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @ + 2
            R@ _LIBPIX.OPERATION-KIND @
            R@ _LIBPIX-CANDIDATE-AND-NOT
            DUP IF R> DROP EXIT THEN DROP
        THEN
        R@ _LIBPIX.TOTAL-ARG @ 3 +
            R@ _LIBPIX.PROGRESS-LIMIT @ <= IF
            R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.TOTAL-ARG @ + 3
            R@ _LIBPIX.OPERATION-KIND @
            R@ _LIBPIX-CANDIDATE-AND-NOT
            DUP IF R> DROP EXIT THEN DROP
        THEN
        1 R@ _LIBPIX.TOTAL-ARG +!
    REPEAT
    R> DROP LIBPA-S-OK ;

: _LIBPIX-BOUNDARY-CANDIDATE-REMOVE
  ( bytes-a bytes-u index-work -- status )
    >R
    LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATE-AND-NOT
    R> DROP ;

: _LIBPIX-BOUNDARY-CANDIDATE-ADD
  ( bytes-a bytes-u index-work -- status )
    >R
    LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATE-OR
    R> DROP ;

: _LIBPIX-OLD-CONTENT-BOUNDARY  ( chunk-u index-work -- status )
    >R
    R@ _LIBPIX.TOTAL-ARG @ 2 = IF
        DUP 0> IF
            R@ _LIBPIX.KEY1 C@ R@ _LIBPIX.STAGE C!
            R@ _LIBPIX.KEY1 1+ C@ R@ _LIBPIX.STAGE 1+ C!
            R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.STAGE 2 + C!
            R@ _LIBPIX.STAGE 3 R@ _LIBPIX-BOUNDARY-CANDIDATE-REMOVE
            DUP IF NIP R> DROP EXIT THEN DROP
            R@ _LIBPIX.KEY1 1+ C@ R@ _LIBPIX.STAGE C!
            R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.STAGE 1+ C!
            R@ _LIBPIX.STAGE 2 R@ _LIBPIX-BOUNDARY-CANDIDATE-REMOVE
            DUP IF NIP R> DROP EXIT THEN DROP
            DUP 1 > IF
                R@ _LIBPIX.CONTENT-SCRATCH 1+ C@
                    R@ _LIBPIX.STAGE 2 + C!
                R@ _LIBPIX.STAGE 3
                    R@ _LIBPIX-BOUNDARY-CANDIDATE-REMOVE
                DUP IF NIP R> DROP EXIT THEN DROP
            THEN
        THEN
        DROP R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.TOTAL-ARG @ 1 = OVER 0> AND IF
        R@ _LIBPIX.KEY1 C@ R@ _LIBPIX.STAGE C!
        R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.STAGE 1+ C!
        R@ _LIBPIX.STAGE 2 R@ _LIBPIX-BOUNDARY-CANDIDATE-REMOVE
        DUP IF NIP R> DROP EXIT THEN DROP
        DUP 1 > IF
            R@ _LIBPIX.CONTENT-SCRATCH 1+ C@
                R@ _LIBPIX.STAGE 2 + C!
            R@ _LIBPIX.STAGE 3
                R@ _LIBPIX-BOUNDARY-CANDIDATE-REMOVE
            DUP IF NIP R> DROP EXIT THEN DROP
        THEN
    THEN
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-OLD-CONTENT-TAIL!  ( chunk-u index-work -- )
    >R
    DUP 2 >= IF
        DUP 2 - R@ _LIBPIX.CONTENT-SCRATCH +
        R@ _LIBPIX.KEY1 2 MOVE
        DROP 2 R@ _LIBPIX.TOTAL-ARG !
        R> DROP EXIT
    THEN
    DUP 1 = IF
        R@ _LIBPIX.TOTAL-ARG @ IF
            R@ _LIBPIX.KEY1 R@ _LIBPIX.TOTAL-ARG @ 1- + C@
                R@ _LIBPIX.KEY1 C!
            R@ _LIBPIX.CONTENT-SCRATCH C@
                R@ _LIBPIX.KEY1 1+ C!
            2 R@ _LIBPIX.TOTAL-ARG !
        ELSE
            R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.KEY1 C!
            1 R@ _LIBPIX.TOTAL-ARG !
        THEN
    THEN
    DROP R> DROP ;

: _LIBPIX-RESTORED-CONTENT-BOUNDARY  ( chunk-u index-work -- status )
    >R
    R@ _LIBPIX.TOTAL-ARG @ 2 = IF
        DUP 0> IF
            R@ _LIBPIX.KEY1 C@ R@ _LIBPIX.STAGE C!
            R@ _LIBPIX.KEY1 1+ C@ R@ _LIBPIX.STAGE 1+ C!
            R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.STAGE 2 + C!
            R@ _LIBPIX.STAGE 3 R@ _LIBPIX-BOUNDARY-CANDIDATE-ADD
            DUP IF NIP R> DROP EXIT THEN DROP
            R@ _LIBPIX.KEY1 1+ C@ R@ _LIBPIX.STAGE C!
            R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.STAGE 1+ C!
            R@ _LIBPIX.STAGE 2 R@ _LIBPIX-BOUNDARY-CANDIDATE-ADD
            DUP IF NIP R> DROP EXIT THEN DROP
            DUP 1 > IF
                R@ _LIBPIX.CONTENT-SCRATCH 1+ C@
                    R@ _LIBPIX.STAGE 2 + C!
                R@ _LIBPIX.STAGE 3
                    R@ _LIBPIX-BOUNDARY-CANDIDATE-ADD
                DUP IF NIP R> DROP EXIT THEN DROP
            THEN
        THEN
        DROP R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.TOTAL-ARG @ 1 = OVER 0> AND IF
        R@ _LIBPIX.KEY1 C@ R@ _LIBPIX.STAGE C!
        R@ _LIBPIX.CONTENT-SCRATCH C@ R@ _LIBPIX.STAGE 1+ C!
        R@ _LIBPIX.STAGE 2 R@ _LIBPIX-BOUNDARY-CANDIDATE-ADD
        DUP IF NIP R> DROP EXIT THEN DROP
        DUP 1 > IF
            R@ _LIBPIX.CONTENT-SCRATCH 1+ C@
                R@ _LIBPIX.STAGE 2 + C!
            R@ _LIBPIX.STAGE 3
                R@ _LIBPIX-BOUNDARY-CANDIDATE-ADD
            DUP IF NIP R> DROP EXIT THEN DROP
        THEN
    THEN
    DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-OLD-CONTENT-SINK
  ( logical-offset source-a source-u index-work -- persist-status )
    >R
    DUP 0< OVER PBLOB-CHUNK-SIZE > OR IF
        _LIBPA-DROP3 R> DROP PERSIST-S-INVALID EXIT
    THEN
    DUP R@ _LIBPIX.PROGRESS-LIMIT !
    OVER R@ _LIBPIX.CONTENT-SCRATCH 2 PICK MOVE
    _LIBPA-DROP3
    R@ _LIBPIX.PROGRESS-LIMIT @ R@ _LIBPIX-OLD-CONTENT-BOUNDARY
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.CONTENT-SCRATCH R@ _LIBPIX.PROGRESS-LIMIT @
    LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATES-REMOVE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.PROGRESS-LIMIT @ R@ _LIBPIX-OLD-CONTENT-TAIL!
    R> DROP PERSIST-S-OK ;

: _LIBPIX-OLD-CONTENT-CHUNK-SINK
  ( logical-offset source-a source-u index-work -- persist-status )
    >R
    DUP 0< OVER PBLOB-CHUNK-SIZE > OR IF
        _LIBPA-DROP3 R> DROP PERSIST-S-INVALID EXIT
    THEN
    2 PICK R@ _LIBPIX.RESULT-N @ <> IF
        _LIBPA-DROP3 R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    DUP R@ _LIBPIX.PROGRESS-LIMIT !
    OVER R@ _LIBPIX.CONTENT-SCRATCH 2 PICK MOVE
    _LIBPA-DROP3 R> DROP PERSIST-S-OK ;

: _LIBPIX-OLD-BODY-CANDIDATES-REMOVE  ( index-work -- status )
    >R
    0 R@ _LIBPIX.RESULT-N !
    0 R@ _LIBPIX.TOTAL-ARG !
    BEGIN
        R@ _LIBPIX.RESULT-N @
        R@ _LIBPIX.OLD-CONTENT _LIBPAC.DATA-U @ <
    WHILE
        R@ _LIBPIX.OLD-CONTENT _LIBPAC.BLOB
        R@ _LIBPIX.RESULT-N @ PBLOB-CHUNK-SIZE
        ['] _LIBPIX-OLD-CONTENT-CHUNK-SINK R@
        R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK
        PBLOB-READ-RANGE
        DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
        R@ _LIBPIX.PROGRESS-LIMIT @ DUP 0> 0= IF
            DROP R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        0 R@ _LIBPIX.PROGRESS !
        R@ _LIBPIX-STAGE-BEGIN
        DUP IF NIP R> DROP EXIT THEN DROP
        DUP R@ _LIBPIX-OLD-CONTENT-BOUNDARY
        DUP IF NIP R> DROP EXIT THEN DROP
        R@ _LIBPIX.CONTENT-SCRATCH OVER
        LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATES-REMOVE
        DUP IF NIP R> DROP EXIT THEN DROP
        DUP R@ _LIBPIX-OLD-CONTENT-TAIL!
        R@ _LIBPIX-STAGE-PUBLISH
        DUP IF NIP R> DROP EXIT THEN DROP
        R@ _LIBPIX.RESULT-N +!
    REPEAT
    0 R@ _LIBPIX.PROGRESS !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-RESTORED-BODY-CANDIDATES-ADD  ( index-work -- status )
    >R
    0 R@ _LIBPIX.RESULT-N !
    0 R@ _LIBPIX.TOTAL-ARG !
    BEGIN
        R@ _LIBPIX.RESULT-N @
        R@ _LIBPIX.RETAINED-CONTENT _LIBPAC.DATA-U @ <
    WHILE
        R@ _LIBPIX.RETAINED-CONTENT _LIBPAC.BLOB
        R@ _LIBPIX.RESULT-N @ PBLOB-CHUNK-SIZE
        ['] _LIBPIX-OLD-CONTENT-CHUNK-SINK R@
        R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
        R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK
        PBLOB-READ-RANGE
        DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
        R@ _LIBPIX.PROGRESS-LIMIT @ DUP 0> 0= IF
            DROP R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        0 R@ _LIBPIX.PROGRESS !
        R@ _LIBPIX-STAGE-BEGIN
        DUP IF NIP R> DROP EXIT THEN DROP
        DUP R@ _LIBPIX-RESTORED-CONTENT-BOUNDARY
        DUP IF NIP R> DROP EXIT THEN DROP
        R@ _LIBPIX.CONTENT-SCRATCH OVER
        LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATES-ADD
        DUP IF NIP R> DROP EXIT THEN DROP
        DUP R@ _LIBPIX-OLD-CONTENT-TAIL!
        R@ _LIBPIX-STAGE-PUBLISH
        DUP IF NIP R> DROP EXIT THEN DROP
        R@ _LIBPIX.RESULT-N +!
    REPEAT
    0 R@ _LIBPIX.PROGRESS !
    R> DROP LIBPA-S-OK ;

0 CONSTANT _LIBPIX-REPLACE-INHERIT
1 CONSTANT _LIBPIX-REPLACE-CONTENT
2 CONSTANT _LIBPIX-REPLACE-TOMBSTONE
3 CONSTANT _LIBPIX-REPLACE-RESTORE

: _LIBPIX-ENTRY-BYTES=  ( a b -- flag )
    SWAP LIB-ENTRY-SIZE ROT LIB-ENTRY-SIZE COMPARE 0= ;

: _LIBPIX-CONTENT-DESCRIPTOR=  ( content descriptor -- flag )
    >R
    DUP LIB-CONTENT-VALID? 0= IF DROP R> DROP 0 EXIT THEN
    R@ LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    R@ LIBPA-CONTENT-RAW? IF DROP R> DROP 0 EXIT THEN
    DUP LIBCT.ID R@ _LIBPAC.RID RID= 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBCT.DOMAIN-REVISION @
        R@ _LIBPAC.DOMAIN-REVISION @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBCT.CONTENT-REVISION @
        R@ _LIBPAC.CONTENT-REVISION @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBCT.KIND @ R@ _LIBPAC.KIND @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBCT.MEDIA @ R@ _LIBPAC.MEDIA @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBCT.DATA-U @ R@ _LIBPAC.DATA-U @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    LIBCT.DIGEST R@ _LIBPAC.DIGEST SHA3-256-COMPARE
    R> DROP ;

: _LIBPIX-DOCUMENT-TRANSITION?  ( old-entry next-entry -- flag )
    >R
    R@ LIB-ENTRY-VALID? 0= IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED = IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.ID R@ LIBE.ID RID= 0= IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.KIND @ R@ LIBE.KIND @ <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.RECEIPT R@ LIBE.RECEIPT LIB-RECEIPT= 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.DOMAIN-REVISION @ 1+
        R@ LIBE.DOMAIN-REVISION @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.MUTATION-SEQUENCE @
        R@ LIBE.MUTATION-SEQUENCE @ >= IF
        DROP R> DROP 0 EXIT
    THEN
    R@ LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED = IF
        DROP R> DROP -1 EXIT
    THEN
    DUP LIBE.MEDIA @ R@ LIBE.MEDIA @ <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBE.CREATED-CLOCK @ R@ LIBE.CREATED-CLOCK @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.CREATED-VALUE @ R@ LIBE.CREATED-VALUE @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.IMPORTED-CLOCK @ R@ LIBE.IMPORTED-CLOCK @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.IMPORTED-VALUE @ R@ LIBE.IMPORTED-VALUE @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.ORIGIN-N @ R@ LIBE.ORIGIN-N @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.CURRENT-CONTENT-REVISION @
        R@ LIBE.CURRENT-CONTENT-REVISION @ > IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBE.CURRENT-CONTENT-REVISION @
        R@ LIBE.CURRENT-CONTENT-REVISION @ = IF
        DUP LIBE.CONTENT-U @ R@ LIBE.CONTENT-U @ <> IF
            DROP R> DROP 0 EXIT
        THEN
        DUP LIBE.CONTENT-DIGEST R@ LIBE.CONTENT-DIGEST
            SHA3-256-COMPARE 0= IF
            DROP R> DROP 0 EXIT
        THEN
    THEN
    DROP R> DROP -1 ;

: _LIBPIX-DELETE-STAGED-NOTE
  ( key-a key-u tree-index index-work -- status )
    >R
    R@ _LIBPIX-DELETE-STAGED
    DUP LIBPA-S-NOT-FOUND = IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX-CANDIDATE-BATCH-NOTE ;

: _LIBPIX-METADATA-RANGE-SINK
  ( logical-offset payload-a payload-u index-work -- persist-status )
    >R
    DUP 0< IF _LIBPA-DROP3 R> DROP PERSIST-S-INVALID EXIT THEN
    2 PICK R@ _LIBPIX.REVISION-ARG @ < IF
        _LIBPA-DROP3 R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    2 PICK R@ _LIBPIX.REVISION-ARG @ -
    DUP 2 PICK + R@ _LIBPIX.EDGE-N @ > IF
        DROP _LIBPA-DROP3 R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.CALLBACK-CONTEXT @ +
    2 PICK SWAP 2 PICK MOVE
    DUP R@ _LIBPIX.TOTAL-ARG +!
    _LIBPA-DROP3 R> DROP PERSIST-S-OK ;

: _LIBPIX-METADATA-READ-EXACT
  ( blob offset exact-u destination index-work -- status )
    >R
    DUP R@ _LIBPIX.CALLBACK-CONTEXT !
    2 PICK R@ _LIBPIX.REVISION-ARG !
    1 PICK R@ _LIBPIX.EDGE-N !
    \ RESULT-N can hold a pending history-prune count across this read.
    \ TOTAL-ARG is disposable before the later candidate pass.
    0 R@ _LIBPIX.TOTAL-ARG !
    _LIBPA-DROP4
    R@ _LIBPIX.OLD-METADATA-BLOB
    R@ _LIBPIX.REVISION-ARG @ R@ _LIBPIX.EDGE-N @
    ['] _LIBPIX-METADATA-RANGE-SINK R@
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ R@ _LIBPIX.BLOB-WORK
    PBLOB-READ-RANGE-TX
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.TOTAL-ARG @ R@ _LIBPIX.EDGE-N @ <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-TAG-DELETE-STAGED  ( tag-a tag-u index-work -- status )
    >R
    2DUP
    R@ _LIBPIX.OLD-ENTRY LIBE.CREATED-VALUE @
    R@ _LIBPIX.OLD-ENTRY LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-TAG-KEY
    DUP IF
        _LIBPA-LIB>STATUS >R 2DROP R> R> DROP EXIT
    THEN DROP
    2DROP
    R@ _LIBPIX.KEY0 LIBPI-TAG-KEY-SIZE
    _LIBPIX-TAG-POSTINGS R@ _LIBPIX-DELETE-STAGED-NOTE
    R> DROP ;

: _LIBPIX-DOCUMENT-TAGS-DELETE-STAGED  ( index-work -- status )
    >R
    0 R@ _LIBPIX.RAW-N !
    BEGIN
        R@ _LIBPIX.RAW-N @ R@ _LIBPIX.OLD-ENTRY LIBE.METADATA-U @ <
    WHILE
        R@ _LIBPIX.OLD-METADATA-BLOB
        R@ _LIBPIX.RAW-N @ LIB-METADATA-FACT-HEADER-SIZE
        R@ _LIBPIX.KEY1 R@ _LIBPIX-METADATA-READ-EXACT
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.KEY1 LIBMF.KIND @ DUP
        R@ _LIBPIX.TEMP-STATUS !
        LIB-METADATA-FACT-TAG <> IF R> DROP LIBPA-S-OK EXIT THEN
        R@ _LIBPIX.KEY1 LIBMF.PAYLOAD-U @ DUP
        R@ _LIBPIX.DOCUMENT-N !
        DUP 1 < SWAP LIB-TAG-TEXT-MAX > OR IF
            R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        R@ _LIBPIX.RAW-N @ LIB-METADATA-FACT-HEADER-SIZE +
        R@ _LIBPIX.DOCUMENT-N @
        +
        R@ _LIBPIX.OLD-ENTRY LIBE.METADATA-U @ > IF
            R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        R@ _LIBPIX.OLD-METADATA-BLOB
        R@ _LIBPIX.RAW-N @ LIB-METADATA-FACT-HEADER-SIZE +
        R@ _LIBPIX.DOCUMENT-N @
        R@ _LIBPIX.KEY1 R@ _LIBPIX-METADATA-READ-EXACT
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.KEY1 R@ _LIBPIX.DOCUMENT-N @
        R@ _LIBPIX-TAG-DELETE-STAGED
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.DOCUMENT-N @
        LIB-METADATA-FACT-HEADER-SIZE +
        R@ _LIBPIX.RAW-N +!
    REPEAT
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-OLD-SECONDARIES-REMOVE  ( index-work -- status )
    >R
    R@ _LIBPIX.OLD-ENTRY LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.OLD-ENTRY LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-RECENCY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RECENCY-KEY-SIZE
    _LIBPIX-RECENCY-ORDER R@ _LIBPIX-DELETE-STAGED-NOTE
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.OLD-ENTRY LIBE.LIFECYCLE @
    R@ _LIBPIX.OLD-ENTRY LIBE.KIND @
    R@ _LIBPIX.OLD-ENTRY LIBE.MEDIA @
    R@ _LIBPIX.OLD-ENTRY LIBE.CREATED-VALUE @
    R@ _LIBPIX.OLD-ENTRY LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-STATE-CREATION-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-STATE-CREATION-KEY-SIZE
    _LIBPIX-STATE-ORDER R@ _LIBPIX-DELETE-STAGED-NOTE
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.OLD-ENTRY LIBE.LIFECYCLE @
    R@ _LIBPIX.OLD-ENTRY LIBE.KIND @
    R@ _LIBPIX.OLD-ENTRY LIBE.MEDIA @
    R@ _LIBPIX.OLD-ENTRY LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.OLD-ENTRY LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-STATE-RECENCY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-STATE-RECENCY-KEY-SIZE
    _LIBPIX-STATE-RECENCY R@ _LIBPIX-DELETE-STAGED-NOTE
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.OLD-ENTRY LIBE-TITLE$
    R@ _LIBPIX.OLD-ENTRY LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-TITLE-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-TITLE-KEY-SIZE
    _LIBPIX-TITLE-ORDER R@ _LIBPIX-DELETE-STAGED-NOTE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-TOMBSTONE =
    R@ _LIBPIX.FACTS-U @ 0>= OR IF
        R@ _LIBPIX-DOCUMENT-TAGS-DELETE-STAGED
        DUP IF R> DROP EXIT THEN DROP
    THEN

    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
    R@ _LIBPIX.OLD-ENTRY LIBE-TITLE$
    LIBPA-CANDIDATE-TITLE R@ _LIBPIX-CANDIDATES-REMOVE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-U64-BE@  ( source -- nonnegative-u )
    DUP 8 + SWAP 0
    BEGIN
        2 PICK 2 PICK <>
    WHILE
        1 PICK C@ SWAP 8 LSHIFT OR
        SWAP 1+ SWAP
    REPEAT
    >R 2DROP R> ;

: _LIBPIX-HISTORY-COLLECT-ROW
  ( key-a key-u value-a value-u persist-status index-work -- status )
    >R
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    2 PICK LIBPI-HISTORY-DOMAIN-KEY-SIZE <> IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    3 PICK R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
        RID= 0= IF
        _LIBPA-DROP4 R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    DUP PERSIST-REF-SIZE <> IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    1 PICK PERSIST-REF-VALID? 0= IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    3 PICK RID-SIZE + _LIBPIX-U64-BE@
        R@ _LIBPIX.REVISION-ARG !
    1 PICK R@ _LIBPIX.HISTORY-REF PERSIST-REF-COPY
    _LIBPA-DROP4
    R@ _LIBPIX.HISTORY-REF
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-RECORD-PAYLOAD$
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE LIBPA-CONTENT-RAW? IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE _LIBPAC.RID
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID RID= 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE _LIBPAC.DOMAIN-REVISION @
    R@ _LIBPIX.REVISION-ARG @ <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-TOMBSTONE =
    R@ _LIBPIX.STAGE _LIBPAC.CONTENT-REVISION @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.OLDEST-CONTENT-REVISION @
        < OR IF
        R@ _LIBPIX.RESULT-N @ LIB-RETAINED-REVISION-MAX >= IF
            R> DROP LIBPA-S-CORRUPT EXIT
        THEN
        R@ _LIBPIX.REVISION-ARG @
        R@ _LIBPIX.CONTENT-SCRATCH R@ _LIBPIX.RESULT-N @ 8 * + !
        1 R@ _LIBPIX.RESULT-N +!
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-HISTORY-COLLECT-NEXT  ( index-work -- status )
    >R
    _LIBPIX-HISTORY R@ _LIBPIX-ROOT
    _LIBPIX-HISTORY R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-NEXT
    R@ _LIBPIX-HISTORY-COLLECT-ROW
    R> DROP ;

: _LIBPIX-HISTORY-PRUNE-COLLECT  ( index-work -- status )
    >R
    0 R@ _LIBPIX.RESULT-N !
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-INHERIT = IF
        R> DROP LIBPA-S-OK EXIT
    THEN
    _LIBPIX-HISTORY R@ _LIBPIX-ROOT
    _LIBPIX-HISTORY R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR PBTREE-CURSOR-INIT
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-HISTORY-PREFIX
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 RID-SIZE
    _LIBPIX-HISTORY R@ _LIBPIX-ROOT
    _LIBPIX-HISTORY R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-SEEK
    R@ _LIBPIX-HISTORY-COLLECT-ROW
    DUP LIBPA-S-NOT-FOUND = IF DROP R> DROP LIBPA-S-OK EXIT THEN
    DUP IF R> DROP EXIT THEN DROP
    BEGIN
        R@ _LIBPIX-HISTORY-COLLECT-NEXT
        DUP LIBPA-S-NOT-FOUND = IF
            DROP R> DROP LIBPA-S-OK EXIT
        THEN
        DUP IF R> DROP EXIT THEN DROP
    AGAIN ;

: _LIBPIX-HISTORY-PRUNE-ONE-STAGED
  ( exact-domain-revision index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    SWAP
    R@ _LIBPIX.KEY0 LIBPI-HISTORY-DOMAIN-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-HISTORY-DOMAIN-KEY-SIZE
    _LIBPIX-HISTORY R@ _LIBPIX-DELETE-STAGED-NOTE
    R> DROP ;

: _LIBPIX-HISTORY-PRUNE-STAGED  ( index-work -- status )
    DUP _LIBPIX.RESULT-N @ 0 ?DO
        DUP _LIBPIX.CONTENT-SCRATCH I 8 * + @
        OVER _LIBPIX-HISTORY-PRUNE-ONE-STAGED
        DUP IF NIP UNLOOP EXIT THEN DROP
    LOOP
    DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-REPLACE-ARGS?  ( index-work -- flag )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-SIZE
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-VALID? 0= IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.EXPECTED-LOGICAL @ 0< IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.EXPECTED-REVISION @ 0> 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-U @ -1 < IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.FACTS-U @ 0>= IF
        R@ _LIBPIX.FACTS-U @ LIB-METADATA-LENGTH-MAX > IF
            R> DROP 0 EXIT
        THEN
        R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
            R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
        R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-SIZE
            MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
        R@ _LIBPIX.FACTS-A @ R@ _LIBPIX.FACTS-U @
        R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
            MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    THEN
    R@ _LIBPIX.CONTENT-ARG @ ?DUP IF
        DUP LIB-CONTENT-SIZE R@ _LIBPIX-SPAN-SAFE? 0= IF
            DROP R> DROP 0 EXIT
        THEN
        DUP LIBCT-DATA$ R@ _LIBPIX-SPAN-SAFE? 0= IF
            DROP R> DROP 0 EXIT
        THEN
        DUP R@ _LIBPIX.NEXT-ENTRY-ARG @ SWAP
            _LIBPA-PAIR-VALID? 0= IF R> DROP 0 EXIT THEN
        DUP LIB-CONTENT-SIZE
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-SIZE
            MSPAN-OVERLAP? IF DROP R> DROP 0 EXIT THEN
        DUP LIB-CONTENT-SIZE
        R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
            MSPAN-OVERLAP? IF DROP R> DROP 0 EXIT THEN
        DROP
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.LIFECYCLE @
            LIB-LIFECYCLE-TOMBSTONED = IF R> DROP 0 EXIT THEN
    ELSE
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.LIFECYCLE @
            LIB-LIFECYCLE-TOMBSTONED =
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MEDIA @
            LIB-MEDIA-NONE = = 0= IF R> DROP 0 EXIT THEN
    THEN
    R> DROP -1 ;

: _LIBPIX-DOCUMENT-OLD-LOAD  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID R@ _LIBPIX.RID-ARG !
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
    R@ _LIBPIX-RID-LOOKUP-CORE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OLD-ENTRY LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED = IF
        R@ _LIBPIX.OLD-CONTENT LIBPA-CONTENT-DESCRIPTOR-SIZE 0 FILL
        R@ _LIBPIX.OLD-METADATA-BLOB PBLOB-SIZE 0 FILL
        R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.STAGE _LIBPAD.METADATA-BLOB
    R@ _LIBPIX.OLD-METADATA-BLOB PBLOB-COPY
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.STAGE _LIBPAD.CONTENT-REF
    R@ _LIBPIX.HISTORY-REF PERSIST-REF-COPY
    R@ _LIBPIX-LOAD-CURRENT-CONTENT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.STAGE
        _LIBPIX-DESCRIPTOR-AGREES? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE R@ _LIBPIX.OLD-CONTENT
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-RESTORE-STAGE  ( index-work -- status )
    >R
    R@ _LIBPIX.RETAINED-CONTENT R@ _LIBPIX.STAGE
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.DOMAIN-REVISION @
        R@ _LIBPIX.STAGE _LIBPAC.DOMAIN-REVISION !
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.CURRENT-CONTENT-REVISION @
        R@ _LIBPIX.STAGE _LIBPAC.CONTENT-REVISION !
    R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.STAGE LIBPA-CONTENT-DESCRIPTOR-SIZE
    R@ _LIBPIX.HISTORY-REF R@ _LIBPIX-APPEND
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-METADATA-BLOB-SELECT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.HISTORY-REF
    R@ _LIBPIX.BLOB
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-ENCODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-SIZE
    R@ _LIBPIX.RECORD-REF R@ _LIBPIX-APPEND
    R> DROP ;

: _LIBPIX-DOCUMENT-RECORD-STAGE  ( index-work -- status )
    >R
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-CONTENT = IF
        R> _LIBPIX-DOCUMENT-BLOB-STAGE EXIT
    THEN
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-RESTORE = IF
        R> _LIBPIX-DOCUMENT-RESTORE-STAGE EXIT
    THEN
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-TOMBSTONE = IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ 0 0
    ELSE
        R@ _LIBPIX-METADATA-BLOB-SELECT
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.HISTORY-REF
        R@ _LIBPIX.BLOB
    THEN
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-ENCODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.STAGE LIBPA-DOCUMENT-RECORD-SIZE
    R@ _LIBPIX.RECORD-REF R@ _LIBPIX-APPEND
    R> DROP ;

: _LIBPIX-DOCUMENT-NEW-SECONDARIES  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-RID-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RID-KEY-SIZE
    R@ _LIBPIX.RECORD-REF PERSIST-REF-SIZE
    _LIBPIX-RID-DIRECTORY R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    \ Tombstones remain addressable by RID but are not visible query rows.
    \ Their compacted form follows the same direct-directory-only contract.
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-TOMBSTONE = IF
        R> DROP LIBPA-S-OK EXIT
    THEN

    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-RECENCY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-RECENCY-KEY-SIZE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-RECENCY-ORDER R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.LIFECYCLE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.KIND @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MEDIA @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.CREATED-VALUE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-STATE-CREATION-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-STATE-CREATION-KEY-SIZE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-STATE-ORDER R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.LIFECYCLE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.KIND @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MEDIA @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.KEY0 LIBPI-STATE-RECENCY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-STATE-RECENCY-KEY-SIZE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID RID-SIZE
    _LIBPIX-STATE-RECENCY R@ _LIBPIX-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-TOMBSTONE <> IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE-TITLE$
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
        R@ _LIBPIX.KEY0 LIBPI-TITLE-KEY
        DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
        R@ _LIBPIX.KEY0 LIBPI-TITLE-KEY-SIZE
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID RID-SIZE
        _LIBPIX-TITLE-ORDER R@ _LIBPIX-PUT-STAGED
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.FACTS-U @ 0>= IF
            R@ _LIBPIX-DOCUMENT-TAGS-PUT-STAGED
            DUP IF R> DROP EXIT THEN DROP
        THEN
    THEN

    R@ _LIBPIX.AUX-ARG @ DUP _LIBPIX-REPLACE-CONTENT =
    SWAP _LIBPIX-REPLACE-RESTORE = OR IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.DOMAIN-REVISION @
        R@ _LIBPIX.KEY0 LIBPI-HISTORY-DOMAIN-KEY
        DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
        R@ _LIBPIX.KEY0 LIBPI-HISTORY-DOMAIN-KEY-SIZE
        R@ _LIBPIX.HISTORY-REF PERSIST-REF-SIZE
        _LIBPIX-HISTORY R@ _LIBPIX-PUT-STAGED
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-REPLACE-RETRY?  ( index-work -- flag )
    >R
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.NEXT-ENTRY-ARG @
        _LIBPIX-ENTRY-BYTES= 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.CONTENT-ARG @ ?DUP IF
        R@ _LIBPIX.OLD-ENTRY LIBE.LIFECYCLE @
            LIB-LIFECYCLE-TOMBSTONED = IF
            DROP R> DROP 0 EXIT
        THEN
        R@ _LIBPIX.OLD-CONTENT _LIBPIX-CONTENT-DESCRIPTOR=
    ELSE
        -1
    THEN
    R> DROP ;

: _LIBPIX-DOCUMENT-REPLACE-MODE  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED = IF
        _LIBPIX-REPLACE-TOMBSTONE R@ _LIBPIX.AUX-ARG !
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.CONTENT-ARG @ IF
        R@ _LIBPIX.OLD-ENTRY LIBE.CURRENT-CONTENT-REVISION @ 1+
        R@ _LIBPIX.NEXT-ENTRY-ARG @
            LIBE.CURRENT-CONTENT-REVISION @ <> IF
            R> DROP LIBPA-S-INVALID EXIT
        THEN
        _LIBPIX-REPLACE-CONTENT R@ _LIBPIX.AUX-ARG !
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.OLD-CONTENT
        _LIBPIX-DESCRIPTOR-AGREES? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    _LIBPIX-REPLACE-INHERIT R@ _LIBPIX.AUX-ARG !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-REPLACE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX-DOCUMENT-REPLACE-ARGS? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX-DOCUMENT-OLD-LOAD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.FACTS-U @ 0>= IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
        R@ _LIBPIX-METADATA-VALIDATE
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPIX-DOCUMENT-REPLACE-RETRY? IF
        R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.OUTPUT-ARG @
            LIB-ENTRY-SIZE MOVE
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.EXPECTED-LOGICAL @
        R@ _LIBPIX.LOGICAL-GENERATION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.EXPECTED-REVISION @
        R@ _LIBPIX.OLD-ENTRY LIBE.DOMAIN-REVISION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.NEXT-ENTRY-ARG @
        _LIBPIX-DOCUMENT-TRANSITION? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.MUTATION-SEQUENCE @ 1+
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX-DOCUMENT-REPLACE-MODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-INHERIT <> IF
        R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
        R@ _LIBPIX-OLD-BODY-CANDIDATES-REMOVE
        DUP IF R> DROP EXIT THEN DROP
        R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
    THEN
    R@ _LIBPIX-HISTORY-PRUNE-COLLECT
    DUP IF R> DROP EXIT THEN DROP

    0 R@ _LIBPIX.PROGRESS !
    R@ _LIBPIX-STAGE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-OLD-SECONDARIES-REMOVE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-HISTORY-PRUNE-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-RECORD-STAGE
    DUP IF R> DROP EXIT THEN DROP

    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-TOMBSTONE <> IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE-TITLE$
        LIBPA-CANDIDATE-TITLE R@ _LIBPIX-CANDIDATES-ADD
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPIX.AUX-ARG @ _LIBPIX-REPLACE-CONTENT = IF
        R@ _LIBPIX.CONTENT-ARG @ LIBCT-DATA$
        LIBPA-CANDIDATE-BODY R@ _LIBPIX-CANDIDATES-ADD
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPIX-DOCUMENT-NEW-SECONDARIES
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
        R@ _LIBPIX.MUTATION-SEQUENCE !
    R@ _LIBPIX-STAGE-FINAL-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.OUTPUT-ARG @
        LIB-ENTRY-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-DOCUMENT-REPLACE-EXACT
  ( next content|0 facts-a facts-u expected-logical expected-domain out owner work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP9 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.OUTPUT-ARG !
    2 PICK R@ _LIBPIX.EXPECTED-REVISION !
    3 PICK R@ _LIBPIX.EXPECTED-LOGICAL !
    4 PICK R@ _LIBPIX.FACTS-U !
    5 PICK R@ _LIBPIX.FACTS-A !
    6 PICK R@ _LIBPIX.CONTENT-ARG !
    7 PICK R@ _LIBPIX.NEXT-ENTRY-ARG !
    R@ ['] _LIBPIX-DOCUMENT-REPLACE-RUN _LIBPIX-WORK-CATCH
    R@ _LIBPIX-STAGE-DISCARD
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP7 R> R> DROP ;

: LIBPA-DOCUMENT-CONTENT-REPLACE-EXACT
  ( next content expected-logical expected-domain out adapter work -- status )
    >R >R >R >R >R
    0 -1 R> R> R> R> R>
    LIBPA-DOCUMENT-REPLACE-EXACT ;

: _LIBPIX-DOCUMENT-NO-CONTENT-REPLACE
  ( next expected-logical expected-domain out adapter work -- status )
    >R >R >R >R >R
    0 0 -1 R> R> R> R> R>
    LIBPA-DOCUMENT-REPLACE-EXACT ;

: LIBPA-DOCUMENT-METADATA-REPLACE-EXACT
  ( next facts-a facts-u expected-logical expected-domain out adapter work -- status )
    >R >R >R >R >R >R >R
    0 R> R> R> R> R> R> R>
    LIBPA-DOCUMENT-REPLACE-EXACT ;

: LIBPA-DOCUMENT-LIFECYCLE-REPLACE-EXACT
  ( next expected-logical expected-domain out adapter work -- status )
    _LIBPIX-DOCUMENT-NO-CONTENT-REPLACE ;

: LIBPA-DOCUMENT-TOMBSTONE-EXACT
  ( next expected-logical expected-domain out adapter work -- status )
    OVER DROP
    _LIBPIX-DOCUMENT-NO-CONTENT-REPLACE ;

\ ---------------------------------------------------------------------
\ Exact retained-content restore
\ ---------------------------------------------------------------------
\ Restore creates one new semantic content revision while reusing the checked
\ immutable PBLOB named by an existing retained descriptor.  Content bytes are
\ read only through bounded PBLOB chunks for posting maintenance; they are
\ never staged as one Library value and PBLOB-WRITE is never called here.

: _LIBPIX-DOCUMENT-RESTORE-ARGS?  ( index-work -- flag )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-SIZE
    R@ _LIBPIX.OUTPUT-ARG @ LIB-ENTRY-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-ENTRY-VALID? 0= IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.KIND @
        LIB-KIND-MANAGED-DOCUMENT <> IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED = IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.REVISION-ARG @ 0> 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.EXPECTED-LOGICAL @ 0< IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.EXPECTED-REVISION @ 0> 0= IF R> DROP 0 EXIT THEN
    R> DROP -1 ;

: _LIBPIX-DOCUMENT-RESTORE-TARGET  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.ID
    R@ _LIBPIX.REVISION-ARG @ R@ _LIBPIX-LOAD-HISTORY
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.STAGE R@ _LIBPIX.RETAINED-CONTENT
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPIX.RETAINED-CONTENT
    R@ _LIBPIX.RETAINED-FACTS
        _LIBPA-DESCRIPTOR>RETAINED-FACTS
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OLD-ENTRY
    R@ _LIBPIX.RETAINED-FACTS
    R@ _LIBPIX.MUTATION-SEQUENCE @ 1+
    R@ _LIBPIX.PAGE
        LIBRARY-SERVICE-PREPARE-RETAINED-RESTORE
    DUP IF
        DROP R> DROP LIBPA-S-INVALID EXIT
    THEN DROP
    R@ _LIBPIX.PAGE R@ _LIBPIX.NEXT-ENTRY-ARG @
        _LIBPIX-ENTRY-BYTES= 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-DOCUMENT-RESTORE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX-DOCUMENT-RESTORE-ARGS? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    -1 R@ _LIBPIX.FACTS-U !
    0 R@ _LIBPIX.FACTS-A !
    0 R@ _LIBPIX.CONTENT-ARG !
    R@ _LIBPIX-DOCUMENT-OLD-LOAD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.NEXT-ENTRY-ARG @
        _LIBPIX-ENTRY-BYTES= IF
        R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.OUTPUT-ARG @
            LIB-ENTRY-SIZE MOVE
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.EXPECTED-LOGICAL @
        R@ _LIBPIX.LOGICAL-GENERATION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.EXPECTED-REVISION @
        R@ _LIBPIX.OLD-ENTRY LIBE.DOMAIN-REVISION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.NEXT-ENTRY-ARG @
        _LIBPIX-DOCUMENT-TRANSITION? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.MUTATION-SEQUENCE @ 1+
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX-DOCUMENT-RESTORE-TARGET
    DUP IF R> DROP EXIT THEN DROP
    _LIBPIX-REPLACE-RESTORE R@ _LIBPIX.AUX-ARG !

    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
    R@ _LIBPIX-OLD-BODY-CANDIDATES-REMOVE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
    R@ _LIBPIX-RESTORED-BODY-CANDIDATES-ADD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-HISTORY-PRUNE-COLLECT
    DUP IF R> DROP EXIT THEN DROP

    0 R@ _LIBPIX.PROGRESS !
    R@ _LIBPIX-STAGE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-OLD-SECONDARIES-REMOVE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-HISTORY-PRUNE-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-RECORD-STAGE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.ENTRY-ARG !
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE-TITLE$
    LIBPA-CANDIDATE-TITLE R@ _LIBPIX-CANDIDATES-ADD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-DOCUMENT-NEW-SECONDARIES
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBE.MUTATION-SEQUENCE @
        R@ _LIBPIX.MUTATION-SEQUENCE !
    R@ _LIBPIX-STAGE-FINAL-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.OUTPUT-ARG @
        LIB-ENTRY-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-DOCUMENT-RESTORE-RETAINED-EXACT
  ( next retained-domain expected-logical expected-domain out adapter work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP7 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.OUTPUT-ARG !
    2 PICK R@ _LIBPIX.EXPECTED-REVISION !
    3 PICK R@ _LIBPIX.EXPECTED-LOGICAL !
    4 PICK R@ _LIBPIX.REVISION-ARG !
    5 PICK R@ _LIBPIX.NEXT-ENTRY-ARG !
    R@ ['] _LIBPIX-DOCUMENT-RESTORE-RUN _LIBPIX-WORK-CATCH
    R@ _LIBPIX-STAGE-DISCARD
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP5 R> R> DROP ;

\ ---------------------------------------------------------------------
\ Exact current collection read
\ ---------------------------------------------------------------------

: _LIBPIX-COLLECTION-READ-CORE  ( index-work -- status )
    >R
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX.KEY0 LIBPI-COLLECTION-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-KEY-SIZE
    _LIBPIX-COLLECTION-DIRECTORY
    R@ _LIBPIX.RECORD-REF R@ _LIBPIX-GET-REF
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.RECORD-REF
    R@ _LIBPIX.ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.PSTORE-WORK @ PSTORE-RECORD-PAYLOAD$
    2DUP LIBPA-COLLECTION-RECORD-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP R@ _LIBPIX.COLLECTION-STAGE
        LIBPA-COLLECTION-RECORD-SIZE MOVE
    R@ _LIBPIX.COLLECTION-STAGE LIBPA-COLLECTION-RECORD-SIZE
    R@ _LIBPIX.OUTPUT-ARG @ LIBPA-COLLECTION-RECORD-DECODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OUTPUT-ARG @ LIBPAC.ID
    R@ _LIBPIX.RID-ARG @ RID= 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-COLLECTION-READ-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX.RID-ARG @ R@ _LIBPIX-RID-INPUT? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIBPA-COLLECTION-SIZE
    R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP LIBPA-S-INVALID EXIT THEN
    R> _LIBPIX-COLLECTION-READ-CORE ;

: LIBPA-COLLECTION-READ
  ( collection-rid destination adapter index-work -- status )
    2DUP _LIBPIX-ENTER DUP IF >R _LIBPA-DROP4 R> EXIT THEN DROP
    >R
    1 PICK R@ _LIBPIX.OUTPUT-ARG !
    2 PICK R@ _LIBPIX.RID-ARG !
    R@ ['] _LIBPIX-COLLECTION-READ-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    >R 2DROP R> R> DROP ;

\ ---------------------------------------------------------------------
\ Complete-owner exact collection surface
\ ---------------------------------------------------------------------
\ MEMBER-RIDS is a canonical raw-RID ascending set.  Membership itself is
\ stored as an unbounded ordered keyset; the collection record carries only
\ its exact aggregate count.  Replacement reconciles the old keyset instead
\ of clearing it, which preserves the creation-order keys of members that
\ have subsequently been tombstoned.

: _LIBPIX-COLLECTION-ARGS?  ( index-work -- flag )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-COLLECTION-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIBPA-COLLECTION-SIZE
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.TOTAL-ARG @ DUP 0< IF DROP R> DROP 0 EXIT THEN
    DUP PERSIST-MAX-SIGNED RID-SIZE / > IF DROP R> DROP 0 EXIT THEN
    RID-SIZE *
    R@ _LIBPIX.MEMBER-LIST-ARG @ SWAP
    R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.MEMBER-LIST-ARG @ R@ _LIBPIX.TOTAL-ARG @
        _LIBPA-CANONICAL-RIDS? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-COLLECTION-VALID? 0= IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.MEMBER-N @
        R@ _LIBPIX.TOTAL-ARG @ <> IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-COLLECTION-SIZE
    R@ _LIBPIX.OUTPUT-ARG @ LIBPA-COLLECTION-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-COLLECTION-SIZE
    R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.TOTAL-ARG @ RID-SIZE *
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.OUTPUT-ARG @ LIBPA-COLLECTION-SIZE
    R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.TOTAL-ARG @ RID-SIZE *
        MSPAN-OVERLAP? 0=
    R> DROP ;

: _LIBPIX-COLLECTION-CREATE-ARGS?  ( index-work -- flag )
    DUP _LIBPIX-COLLECTION-ARGS? 0= IF DROP 0 EXIT THEN
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.REVISION @ 1 <> IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.CREATED-SEQUENCE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.MUTATION-SEQUENCE @ <> IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @
    R@ _LIBPIX.MEMBER-LIST-ARG @ R@ _LIBPIX.TOTAL-ARG @
        _LIBPA-COLLECTION-REQUEST-MATCHES?
    R> DROP ;

: _LIBPIX-COLLECTION-TRANSITION?  ( old next -- flag )
    DUP LIBPA-COLLECTION-VALID? 0= IF 2DROP 0 EXIT THEN
    OVER LIBPA-COLLECTION-VALID? 0= IF 2DROP 0 EXIT THEN
    >R
    DUP LIBC.ID R@ LIBC.ID RID= 0= IF DROP R> DROP 0 EXIT THEN
    DUP LIBC.OPERATION-KEY R@ LIBC.OPERATION-KEY RID= 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBC.REQUEST-SEAL R@ LIBC.REQUEST-SEAL
        SHA3-256-COMPARE 0= IF DROP R> DROP 0 EXIT THEN
    DUP LIBC.REVISION @ PERSIST-MAX-SIGNED >= IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBC.REVISION @ 1+ R@ LIBC.REVISION @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DUP LIBC.CREATED-SEQUENCE @
        R@ LIBC.CREATED-SEQUENCE @ <> IF
        DROP R> DROP 0 EXIT
    THEN
    DROP R> DROP -1 ;

: _LIBPIX-COLLECTION-RECORD-STAGE  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.COLLECTION-STAGE
        LIBPA-COLLECTION-RECORD-ENCODE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.COLLECTION-STAGE LIBPA-COLLECTION-RECORD-SIZE
    R@ _LIBPIX.HISTORY-REF R@ _LIBPIX-APPEND
    R> DROP ;

: _LIBPIX-COLLECTION-DIRECTORIES-PUT-STAGED
  ( collection index-work -- status )
    >R
    DUP LIBC.ID LIBPI-DIRECTORY-COLLECTION
        R@ _LIBPIX-DIRECTORY-PUT-STAGED
    DUP IF >R DROP R> R> DROP EXIT THEN DROP
    DUP LIBC.OPERATION-KEY LIBPI-DIRECTORY-RECEIPT
        R@ _LIBPIX-DIRECTORY-PUT-STAGED
    DUP IF >R DROP R> R> DROP EXIT THEN DROP
    DUP LIBC.OPERATION-KEY R@ _LIBPIX.KEY0 LIBPI-OPERATION-KEY
    DUP IF _LIBPA-LIB>STATUS >R DROP R> R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY1 LIBPA-OPERATION-VALUE-SIZE 0 FILL
    LIBPA-OPERATION-COLLECTION R@ _LIBPIX.KEY1 !
    DUP LIBC.ID R@ _LIBPIX.KEY1 8 + RID-COPY
    DROP
    R@ _LIBPIX.KEY0 LIBPI-OPERATION-KEY-SIZE
    R@ _LIBPIX.KEY1 LIBPA-OPERATION-VALUE-SIZE
    _LIBPIX-OPERATION-RECEIPTS R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-COLLECTION-CURRENT-PUT-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID
        R@ _LIBPIX.KEY0 LIBPI-COLLECTION-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-KEY-SIZE
    R@ _LIBPIX.HISTORY-REF PERSIST-REF-SIZE
    _LIBPIX-COLLECTION-DIRECTORY R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-COLLECTION-ORDER-PUT-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.CREATED-SEQUENCE @
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-ORDER-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-ORDER-KEY-SIZE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID RID-SIZE
    _LIBPIX-COLLECTION-ORDER R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-COLLECTION-TITLE-PUT-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC-TITLE$
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-TITLE-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-TITLE-KEY-SIZE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID RID-SIZE
    _LIBPIX-COLLECTION-TITLE R@ _LIBPIX-PUT-STAGED
    R> DROP ;

: _LIBPIX-COLLECTION-TITLE-DELETE-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.OLD-COLLECTION LIBC-TITLE$
    R@ _LIBPIX.OLD-COLLECTION LIBC.ID
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-TITLE-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-COLLECTION-TITLE-KEY-SIZE
    _LIBPIX-COLLECTION-TITLE R@ _LIBPIX-DELETE-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX-CANDIDATE-BATCH-NOTE ;

: _LIBPIX-COLLECTION-CREATE-KEYS-STAGED  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @
        R@ _LIBPIX-COLLECTION-DIRECTORIES-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-CURRENT-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-ORDER-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R> _LIBPIX-COLLECTION-TITLE-PUT-STAGED ;

: _LIBPIX-TARGET-CONTAINS?  ( member-rid index-work -- flag )
    >R
    0 R@ _LIBPIX.RAW-N !
    R@ _LIBPIX.TOTAL-ARG @ R@ _LIBPIX.EDGE-N !
    BEGIN
        R@ _LIBPIX.RAW-N @ R@ _LIBPIX.EDGE-N @ <
    WHILE
        R@ _LIBPIX.RAW-N @ R@ _LIBPIX.EDGE-N @ + 2/
        R@ _LIBPIX.TEMP-STATUS !
        DUP
        R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.TEMP-STATUS @ RID-SIZE * +
        RID= IF
            DROP R> DROP -1 EXIT
        THEN
        DUP RID-SIZE
        R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.TEMP-STATUS @ RID-SIZE * + RID-SIZE
        COMPARE
        0< IF
            R@ _LIBPIX.TEMP-STATUS @ R@ _LIBPIX.EDGE-N !
        ELSE
            R@ _LIBPIX.TEMP-STATUS @ 1+
                R@ _LIBPIX.RAW-N !
        THEN
    REPEAT
    DROP R> DROP 0 ;

: _LIBPIX-OLD-MEMBERSHIP-ROW
  ( key-a key-u value-a value-u persist-status index-work -- status )
    >R
    DUP PERSIST-S-NOT-FOUND = IF
        DROP _LIBPA-DROP4 R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    DUP IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    2DROP
    DUP LIBPI-MEMBERSHIP-PREFIX-SIZE < IF
        2DROP R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    OVER R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-PREFIX-SIZE
        _LIBPA-BYTES= 0= IF
        2DROP R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    DUP LIBPI-MEMBERSHIP-KEY-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    2DUP R@ _LIBPIX.KEY1 SWAP MOVE
    OVER RID-SIZE 8 + +
    R@ _LIBPIX-TARGET-CONTAINS? IF
        2DROP
        1 R@ _LIBPIX.PROGRESS-LIMIT +!
        R> DROP LIBPA-S-OK EXIT
    THEN
    2DROP
    R@ _LIBPIX.KEY1
    R@ _LIBPIX.CONTENT-SCRATCH
    R@ _LIBPIX.RESULT-N @ LIBPI-MEMBERSHIP-KEY-SIZE * +
    LIBPI-MEMBERSHIP-KEY-SIZE MOVE
    1 R@ _LIBPIX.RESULT-N +!
    R> DROP LIBPA-S-OK ;

: _LIBPIX-OLD-MEMBERSHIP-DELETES-FLUSH  ( index-work -- status )
    >R
    R@ _LIBPIX.RESULT-N @ 0= IF
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX-STAGE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.RAW-N !
    BEGIN
        R@ _LIBPIX.RAW-N @ R@ _LIBPIX.RESULT-N @ <
    WHILE
        R@ _LIBPIX.CONTENT-SCRATCH
        R@ _LIBPIX.RAW-N @ LIBPI-MEMBERSHIP-KEY-SIZE * +
        LIBPI-MEMBERSHIP-KEY-SIZE
        _LIBPIX-MEMBERSHIP R@ _LIBPIX-DELETE-STAGED
        DUP IF R> DROP EXIT THEN DROP
        1 R@ _LIBPIX.RAW-N +!
    REPEAT
    R@ _LIBPIX-STAGE-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.RESULT-N !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-OLD-MEMBERSHIPS-RECONCILE  ( index-work -- status )
    >R
    R@ _LIBPIX.OLD-COLLECTION LIBC.ID
        R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-PREFIX
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.PROGRESS-LIMIT !
    0 R@ _LIBPIX.RESULT-N !
    0 R@ _LIBPIX.CALLBACK-XT !
    BEGIN
        R@ _LIBPIX.CALLBACK-XT @ IF
            R@ _LIBPIX.KEY1 LIBPI-MEMBERSHIP-KEY-SIZE
            _LIBPIX-MEMBERSHIP R@ _LIBPIX-ROOT
            _LIBPIX-MEMBERSHIP R@ _LIBPIX-TREE
            R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-RESUME
        ELSE
            R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-PREFIX-SIZE
            _LIBPIX-MEMBERSHIP R@ _LIBPIX-ROOT
            _LIBPIX-MEMBERSHIP R@ _LIBPIX-TREE
            R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-SEEK
        THEN
        R@ _LIBPIX-OLD-MEMBERSHIP-ROW
        DUP LIBPA-S-NOT-FOUND = IF
            DROP
            R> _LIBPIX-OLD-MEMBERSHIP-DELETES-FLUSH EXIT
        THEN
        DUP IF R> DROP EXIT THEN DROP
        -1 R@ _LIBPIX.CALLBACK-XT !
        R@ _LIBPIX.RESULT-N @ _LIBPIX-MEMBERSHIP-SCRATCH-MAX = IF
            R@ _LIBPIX-OLD-MEMBERSHIP-DELETES-FLUSH
            DUP IF R> DROP EXIT THEN DROP
        THEN
    AGAIN ;

: _LIBPIX-MEMBERSHIP-TARGET-PUT  ( member-rid index-work -- status )
    >R
    R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX-DOCUMENT-STAGED@
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OLD-ENTRY LIBE.LIFECYCLE @
        LIB-LIFECYCLE-TOMBSTONED = IF
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID
    R@ _LIBPIX.OLD-ENTRY LIBE.CREATED-VALUE @
    R@ _LIBPIX.RID-ARG @
    R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-KEY-SIZE
    _LIBPIX-MEMBERSHIP R@ _LIBPIX-GET-STAGED-TX
    DUP PERSIST-S-NOT-FOUND = IF
        DROP 2DROP
        R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-KEY-SIZE
        0 0 _LIBPIX-MEMBERSHIP R@ _LIBPIX-PUT-STAGED
        DUP IF R> DROP EXIT THEN DROP
        1 R@ _LIBPIX.PROGRESS-LIMIT +!
        R> _LIBPIX-CANDIDATE-BATCH-NOTE EXIT
    THEN
    DUP IF
        >R 2DROP R> R> DROP EXIT
    THEN DROP
    DUP IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    2DROP R> DROP LIBPA-S-OK ;

: _LIBPIX-MEMBERSHIP-TARGETS-PUT  ( index-work -- status )
    >R
    0 R@ _LIBPIX.RAW-N !
    BEGIN
        R@ _LIBPIX.RAW-N @ R@ _LIBPIX.TOTAL-ARG @ <
    WHILE
        R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.RAW-N @ RID-SIZE * +
        R@ _LIBPIX-MEMBERSHIP-TARGET-PUT
        DUP IF R> DROP EXIT THEN DROP
        1 R@ _LIBPIX.RAW-N +!
    REPEAT
    R@ _LIBPIX.PROGRESS-LIMIT @ R@ _LIBPIX.TOTAL-ARG @ <> IF
        R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-COLLECTION-MEMBERSHIP-COUNT-SET  ( index-work -- status )
    >R
    R@ _LIBPIX.MEMBERSHIP-COUNT @
    R@ _LIBPIX.OLD-COLLECTION LIBC.MEMBER-N @ -
    DUP 0< IF DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    R@ _LIBPIX.TOTAL-ARG @
    PERSIST-MAX-SIGNED 2 PICK - > IF
        DROP R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX.TOTAL-ARG @ +
        R@ _LIBPIX.MEMBERSHIP-COUNT !
    R> DROP LIBPA-S-OK ;

: _LIBPIX-COLLECTION-CREATE-RETRY  ( index-work -- status )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.OPERATION-KEY
        R@ _LIBPIX-OPERATION-LOOKUP-READY
    DUP LIBPA-S-NOT-FOUND = IF R> DROP EXIT THEN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-OPERATION-COLLECTION <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.ACTIVE-RID R@ _LIBPIX.RID-ARG !
    R@ _LIBPIX.OLD-COLLECTION R@ _LIBPIX.OUTPUT-ARG !
    R@ _LIBPIX-COLLECTION-READ-CORE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.OLD-COLLECTION
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIB-COLLECTION-RETRY= 0= IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.OLD-COLLECTION R@ _LIBPIX.AUX-ARG @
        LIBPA-COLLECTION-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: _LIBPIX-COLLECTION-CREATE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX-COLLECTION-CREATE-ARGS? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.OUTPUT-ARG @ R@ _LIBPIX.AUX-ARG !
    R@ _LIBPIX-COLLECTION-CREATE-RETRY
    DUP LIBPA-S-OK = IF R> DROP EXIT THEN
    DUP LIBPA-S-NOT-FOUND <> IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.EXPECTED-LOGICAL @
        R@ _LIBPIX.LOGICAL-GENERATION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.MUTATION-SEQUENCE @ PERSIST-MAX-SIGNED >= IF
        R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.MUTATION-SEQUENCE @
        R@ _LIBPIX.MUTATION-SEQUENCE @ 1+ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.COLLECTION-COUNT @ PERSIST-MAX-SIGNED >= IF
        R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX.MEMBERSHIP-COUNT @
    R@ _LIBPIX.TOTAL-ARG @
        PERSIST-MAX-SIGNED 2 PICK - > IF
        DROP R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    DROP
    0 R@ _LIBPIX.PROGRESS !
    R@ _LIBPIX-STAGE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID
        R@ _LIBPIX-TOKEN-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.OPERATION-KEY
        R@ _LIBPIX-TOKEN-ABSENT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.PROGRESS-LIMIT !
    R@ _LIBPIX-MEMBERSHIP-TARGETS-PUT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-RECORD-STAGE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-CREATE-KEYS-STAGED
    DUP IF R> DROP EXIT THEN DROP
    1 R@ _LIBPIX.COLLECTION-COUNT +!
    R@ _LIBPIX.TOTAL-ARG @ R@ _LIBPIX.MEMBERSHIP-COUNT +!
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.MUTATION-SEQUENCE @
        R@ _LIBPIX.MUTATION-SEQUENCE !
    R@ _LIBPIX-STAGE-FINAL-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.AUX-ARG @
        LIBPA-COLLECTION-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-COLLECTION-CREATE-EXACT
  ( collection member-rids member-n expected-logical out adapter work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP7 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.OUTPUT-ARG !
    2 PICK R@ _LIBPIX.EXPECTED-LOGICAL !
    3 PICK R@ _LIBPIX.TOTAL-ARG !
    4 PICK R@ _LIBPIX.MEMBER-LIST-ARG !
    5 PICK R@ _LIBPIX.NEXT-ENTRY-ARG !
    R@ ['] _LIBPIX-COLLECTION-CREATE-RUN _LIBPIX-WORK-CATCH
    R@ _LIBPIX-STAGE-DISCARD
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP5 R> R> DROP ;

: _LIBPIX-COLLECTION-REPLACE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX-COLLECTION-ARGS? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.EXPECTED-LOGICAL @
        R@ _LIBPIX.LOGICAL-GENERATION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.ID R@ _LIBPIX.RID-ARG !
    R@ _LIBPIX.OLD-COLLECTION R@ _LIBPIX.OUTPUT-ARG !
    R@ _LIBPIX-COLLECTION-READ-CORE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.EXPECTED-REVISION @
    R@ _LIBPIX.OLD-COLLECTION LIBC.REVISION @ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX.OLD-COLLECTION R@ _LIBPIX.NEXT-ENTRY-ARG @
        _LIBPIX-COLLECTION-TRANSITION? 0= IF
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ _LIBPIX.MUTATION-SEQUENCE @ PERSIST-MAX-SIGNED >= IF
        R> DROP LIBPA-S-CAPACITY EXIT
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.MUTATION-SEQUENCE @
        R@ _LIBPIX.MUTATION-SEQUENCE @ 1+ <> IF
        R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    R@ _LIBPIX-OLD-MEMBERSHIPS-RECONCILE
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPIX.PROGRESS !
    R@ _LIBPIX-STAGE-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-MEMBERSHIP-TARGETS-PUT
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-TITLE-DELETE-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-RECORD-STAGE
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-CURRENT-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-TITLE-PUT-STAGED
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX-COLLECTION-MEMBERSHIP-COUNT-SET
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBC.MUTATION-SEQUENCE @
        R@ _LIBPIX.MUTATION-SEQUENCE !
    R@ _LIBPIX-STAGE-FINAL-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.AUX-ARG @
        LIBPA-COLLECTION-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: LIBPA-COLLECTION-REPLACE-EXACT
  ( next member-rids member-n expected-logical expected-revision out adapter work -- status )
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP8 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.OUTPUT-ARG !
    2 PICK R@ _LIBPIX.EXPECTED-REVISION !
    3 PICK R@ _LIBPIX.EXPECTED-LOGICAL !
    4 PICK R@ _LIBPIX.TOTAL-ARG !
    5 PICK R@ _LIBPIX.MEMBER-LIST-ARG !
    6 PICK R@ _LIBPIX.NEXT-ENTRY-ARG !
    R@ _LIBPIX.OUTPUT-ARG @ R@ _LIBPIX.AUX-ARG !
    R@ ['] _LIBPIX-COLLECTION-REPLACE-RUN _LIBPIX-WORK-CATCH
    R@ _LIBPIX-STAGE-DISCARD
    SWAP R@ _LIBPIX-LEAVE
    >R _LIBPA-DROP6 R> R> DROP ;

\ =====================================================================
\ Stable semantic keyset ranges
\ =====================================================================

1  CONSTANT LIBPA-RANGE-DOCUMENT-CREATION
2  CONSTANT LIBPA-RANGE-DOCUMENT-RECENCY
3  CONSTANT LIBPA-RANGE-DOCUMENT-STATE-CREATION
4  CONSTANT LIBPA-RANGE-DOCUMENT-STATE-RECENCY
5  CONSTANT LIBPA-RANGE-DOCUMENT-TITLE
6  CONSTANT LIBPA-RANGE-EXACT-TAG
7  CONSTANT LIBPA-RANGE-CANDIDATE
8  CONSTANT LIBPA-RANGE-COLLECTION-ORDER
9  CONSTANT LIBPA-RANGE-COLLECTION-TITLE
10 CONSTANT LIBPA-RANGE-MEMBERSHIP
11 CONSTANT LIBPA-RANGE-HISTORY

0 CONSTANT LIBPA-CONTINUATION-SEEDED
1 CONSTANT LIBPA-CONTINUATION-AFTER
2 CONSTANT LIBPA-CONTINUATION-BEFORE

 0 CONSTANT _LIBPAROW-RID
32 CONSTANT _LIBPAROW-ORDER
40 CONSTANT _LIBPAROW-VALUE
48 CONSTANT LIBPA-RANGE-ROW-SIZE

: LIBPA-RANGE-ROW.RID    ( row -- rid ) _LIBPAROW-RID + ;
: LIBPA-RANGE-ROW.ORDER  ( row -- a ) _LIBPAROW-ORDER + ;
: LIBPA-RANGE-ROW.VALUE  ( row -- a ) _LIBPAROW-VALUE + ;

: LIBPA-RANGE-ROW-RID@  ( row -- rid|0 )
    DUP 0= IF DROP 0 EXIT THEN
    DUP LIBPA-RANGE-ROW-SIZE MSPAN-NONWRAPPING? 0= IF DROP 0 EXIT THEN
    LIBPA-RANGE-ROW.RID ;

: LIBPA-RANGE-ROW-ORDER@  ( row -- order|-1 )
    DUP 0= IF DROP -1 EXIT THEN
    DUP LIBPA-RANGE-ROW-SIZE MSPAN-NONWRAPPING? 0= IF DROP -1 EXIT THEN
    LIBPA-RANGE-ROW.ORDER @ ;

: LIBPA-RANGE-ROW-DOMAIN@  ( row -- exact-domain|-1 )
    LIBPA-RANGE-ROW-ORDER@ ;

: LIBPA-RANGE-ROW-VALUE@  ( row -- value|-1 )
    DUP 0= IF DROP -1 EXIT THEN
    DUP LIBPA-RANGE-ROW-SIZE MSPAN-NONWRAPPING? 0= IF DROP -1 EXIT THEN
    LIBPA-RANGE-ROW.VALUE @ ;

0x4C50434F4E543031 CONSTANT _LIBPACONT-MAGIC  \ "LPCONT01"

  0 CONSTANT _LIBPACONT-MAGIC-OFF
  8 CONSTANT _LIBPACONT-FAMILY-OFF
 16 CONSTANT _LIBPACONT-DIRECTION-OFF
 24 CONSTANT _LIBPACONT-LOGICAL-OFF
 32 CONSTANT _LIBPACONT-PREFIX-U-OFF
 40 CONSTANT _LIBPACONT-PREFIX-SEAL-OFF
 72 CONSTANT _LIBPACONT-FIRST-U-OFF
 80 CONSTANT _LIBPACONT-LAST-U-OFF
 88 CONSTANT _LIBPACONT-FIRST-KEY-OFF
344 CONSTANT _LIBPACONT-LAST-KEY-OFF
600 CONSTANT _LIBPACONT-RESERVED-OFF
608 CONSTANT LIBPA-CONTINUATION-SIZE

: _LIBPACONT.MAGIC       ( continuation -- a )
    _LIBPACONT-MAGIC-OFF + ;
: _LIBPACONT.FAMILY      ( continuation -- a )
    _LIBPACONT-FAMILY-OFF + ;
: _LIBPACONT.DIRECTION   ( continuation -- a )
    _LIBPACONT-DIRECTION-OFF + ;
: _LIBPACONT.LOGICAL     ( continuation -- a )
    _LIBPACONT-LOGICAL-OFF + ;
: _LIBPACONT.PREFIX-U    ( continuation -- a )
    _LIBPACONT-PREFIX-U-OFF + ;
: _LIBPACONT.PREFIX-SEAL ( continuation -- digest )
    _LIBPACONT-PREFIX-SEAL-OFF + ;
: _LIBPACONT.FIRST-U     ( continuation -- a )
    _LIBPACONT-FIRST-U-OFF + ;
: _LIBPACONT.LAST-U      ( continuation -- a )
    _LIBPACONT-LAST-U-OFF + ;
: _LIBPACONT.FIRST-KEY   ( continuation -- key )
    _LIBPACONT-FIRST-KEY-OFF + ;
: _LIBPACONT.LAST-KEY    ( continuation -- key )
    _LIBPACONT-LAST-KEY-OFF + ;
: _LIBPACONT.RESERVED    ( continuation -- a )
    _LIBPACONT-RESERVED-OFF + ;

: LIBPA-CONTINUATION-FAMILY@  ( continuation -- family|-1 )
    DUP 0= IF DROP -1 EXIT THEN _LIBPACONT.FAMILY @ ;

: LIBPA-CONTINUATION-DIRECTION@  ( continuation -- direction|-1 )
    DUP 0= IF DROP -1 EXIT THEN _LIBPACONT.DIRECTION @ ;

: LIBPA-CONTINUATION-LOGICAL-GENERATION@
  ( continuation -- logical-generation|-1 )
    DUP 0= IF DROP -1 EXIT THEN _LIBPACONT.LOGICAL @ ;

: _LIBPA-RANGE-FAMILY?  ( family -- flag )
    DUP LIBPA-RANGE-DOCUMENT-CREATION >=
    SWAP LIBPA-RANGE-HISTORY <= AND ;

: _LIBPA-RANGE-KEY-SIZE  ( family -- bytes|0 )
    CASE
        LIBPA-RANGE-DOCUMENT-CREATION OF
            LIBPI-ORDER-KEY-SIZE ENDOF
        LIBPA-RANGE-DOCUMENT-RECENCY OF
            LIBPI-RECENCY-KEY-SIZE ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-CREATION OF
            LIBPI-STATE-CREATION-KEY-SIZE ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-RECENCY OF
            LIBPI-STATE-RECENCY-KEY-SIZE ENDOF
        LIBPA-RANGE-DOCUMENT-TITLE OF
            LIBPI-TITLE-KEY-SIZE ENDOF
        LIBPA-RANGE-EXACT-TAG OF LIBPI-TAG-KEY-SIZE ENDOF
        LIBPA-RANGE-CANDIDATE OF LIBPI-BODY-KEY-SIZE ENDOF
        LIBPA-RANGE-COLLECTION-ORDER OF
            LIBPI-COLLECTION-ORDER-KEY-SIZE ENDOF
        LIBPA-RANGE-COLLECTION-TITLE OF
            LIBPI-COLLECTION-TITLE-KEY-SIZE ENDOF
        LIBPA-RANGE-MEMBERSHIP OF
            LIBPI-MEMBERSHIP-KEY-SIZE ENDOF
        LIBPA-RANGE-HISTORY OF
            LIBPI-HISTORY-DOMAIN-KEY-SIZE ENDOF
        0 SWAP
    ENDCASE ;

: LIBPA-CONTINUATION-VALID?  ( continuation -- flag )
    DUP 0= IF DROP 0 EXIT THEN
    DUP LIBPA-CONTINUATION-SIZE MSPAN-NONWRAPPING? 0= IF
        DROP 0 EXIT
    THEN
    >R
    R@ _LIBPACONT.MAGIC @ _LIBPACONT-MAGIC <> IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.FAMILY @ DUP _LIBPA-RANGE-FAMILY? 0= IF
        DROP R> DROP 0 EXIT
    THEN
    DROP
    R@ _LIBPACONT.FIRST-U @ R@ _LIBPACONT.LAST-U @ <>
    IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.FIRST-U @ IF
        R@ _LIBPACONT.FAMILY @ _LIBPA-RANGE-KEY-SIZE
        R@ _LIBPACONT.FIRST-U @ <> IF R> DROP 0 EXIT THEN
    THEN
    R@ _LIBPACONT.DIRECTION @ DUP LIBPA-CONTINUATION-SEEDED <
    SWAP LIBPA-CONTINUATION-BEFORE > OR IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.LOGICAL @ 0< IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.PREFIX-U @ DUP 0< SWAP LIBPI-KEY-MAX > OR IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPACONT.PREFIX-U @ 0= IF
        R@ _LIBPACONT.PREFIX-SEAL SHA3-256-LEN
        _LIBPA-ZERO? 0= IF R> DROP 0 EXIT THEN
    THEN
    R@ _LIBPACONT.FIRST-KEY R@ _LIBPACONT.FIRST-U @
    R@ _LIBPACONT.LAST-KEY R@ _LIBPACONT.LAST-U @
    COMPARE 0> IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.FIRST-KEY R@ _LIBPACONT.FIRST-U @ +
    LIBPI-KEY-MAX R@ _LIBPACONT.FIRST-U @ -
        _LIBPA-ZERO? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.LAST-KEY R@ _LIBPACONT.LAST-U @ +
    LIBPI-KEY-MAX R@ _LIBPACONT.LAST-U @ -
        _LIBPA-ZERO? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPACONT.RESERVED @ 0= R> DROP ;

: _LIBPIX-RANGE-TREE  ( family -- tree-index|-1 )
    CASE
        LIBPA-RANGE-DOCUMENT-CREATION OF
            _LIBPIX-CREATION-ORDER ENDOF
        LIBPA-RANGE-DOCUMENT-RECENCY OF
            _LIBPIX-RECENCY-ORDER ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-CREATION OF
            _LIBPIX-STATE-ORDER ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-RECENCY OF
            _LIBPIX-STATE-RECENCY ENDOF
        LIBPA-RANGE-DOCUMENT-TITLE OF _LIBPIX-TITLE-ORDER ENDOF
        LIBPA-RANGE-EXACT-TAG OF _LIBPIX-TAG-POSTINGS ENDOF
        LIBPA-RANGE-CANDIDATE OF _LIBPIX-BODY-POSTINGS ENDOF
        LIBPA-RANGE-COLLECTION-ORDER OF
            _LIBPIX-COLLECTION-ORDER ENDOF
        LIBPA-RANGE-COLLECTION-TITLE OF
            _LIBPIX-COLLECTION-TITLE ENDOF
        LIBPA-RANGE-MEMBERSHIP OF _LIBPIX-MEMBERSHIP ENDOF
        LIBPA-RANGE-HISTORY OF _LIBPIX-HISTORY ENDOF
        -1 SWAP
    ENDCASE ;

: _LIBPIX-RANGE-PREFIX-EMPTY?  ( index-work -- flag )
    DUP _LIBPIX.PROGRESS-LIMIT @ 0=
    SWAP _LIBPIX.MEMBER-ARG @ 0= OR ;

: _LIBPIX-RANGE-PREFIX-BUILD  ( index-work -- status )
    >R
    0 R@ _LIBPIX.PAGE-ID !
    R@ _LIBPIX.OPERATION-KIND @ CASE
        LIBPA-RANGE-DOCUMENT-CREATION OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R> DROP LIBPA-S-INVALID EXIT
            THEN
        ENDOF
        LIBPA-RANGE-DOCUMENT-RECENCY OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R> DROP LIBPA-S-INVALID EXIT
            THEN
        ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-CREATION OF
            R@ _LIBPIX.PROGRESS-LIMIT @ CASE
                1 OF
                    R@ _LIBPIX.MEMBER-ARG @ C@
                    R@ _LIBPIX.KEY0 LIBPI-STATE-LIFECYCLE-PREFIX
                ENDOF
                2 OF
                    R@ _LIBPIX.MEMBER-ARG @ DUP C@ SWAP 1+ C@
                    R@ _LIBPIX.KEY0 LIBPI-STATE-KIND-PREFIX
                ENDOF
                3 OF
                    R@ _LIBPIX.MEMBER-ARG @ DUP C@
                    OVER 1+ C@ ROT 2 + C@
                    R@ _LIBPIX.KEY0 LIBPI-STATE-MEDIA-PREFIX
                ENDOF
                R> DROP LIBPA-S-INVALID EXIT
            ENDCASE
            DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
            R@ _LIBPIX.PROGRESS-LIMIT @ R@ _LIBPIX.PAGE-ID !
        ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-RECENCY OF
            R@ _LIBPIX.PROGRESS-LIMIT @ CASE
                1 OF
                    R@ _LIBPIX.MEMBER-ARG @ C@
                    R@ _LIBPIX.KEY0 LIBPI-STATE-LIFECYCLE-PREFIX
                ENDOF
                2 OF
                    R@ _LIBPIX.MEMBER-ARG @ DUP C@ SWAP 1+ C@
                    R@ _LIBPIX.KEY0 LIBPI-STATE-KIND-PREFIX
                ENDOF
                3 OF
                    R@ _LIBPIX.MEMBER-ARG @ DUP C@
                    OVER 1+ C@ ROT 2 + C@
                    R@ _LIBPIX.KEY0 LIBPI-STATE-MEDIA-PREFIX
                ENDOF
                R> DROP LIBPA-S-INVALID EXIT
            ENDCASE
            DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
            R@ _LIBPIX.PROGRESS-LIMIT @ R@ _LIBPIX.PAGE-ID !
        ENDOF
        LIBPA-RANGE-DOCUMENT-TITLE OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R@ _LIBPIX.MEMBER-ARG @
                R@ _LIBPIX.PROGRESS-LIMIT @
                R@ _LIBPIX.KEY0 LIBPI-TITLE-PREFIX
                DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
                LIBPI-TITLE-PREFIX-SIZE R@ _LIBPIX.PAGE-ID !
            THEN
        ENDOF
        LIBPA-RANGE-EXACT-TAG OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R@ _LIBPIX.MEMBER-ARG @
                R@ _LIBPIX.PROGRESS-LIMIT @
                R@ _LIBPIX.KEY0 LIBPI-TAG-PREFIX
                DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
                LIBPI-TAG-PREFIX-SIZE R@ _LIBPIX.PAGE-ID !
            THEN
        ENDOF
        LIBPA-RANGE-CANDIDATE OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R@ _LIBPIX.MEMBER-ARG @
                R@ _LIBPIX.PROGRESS-LIMIT @
                R@ _LIBPIX.KEY0 LIBPI-BODY-PREFIX
                DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
                LIBPI-BODY-PREFIX-SIZE R@ _LIBPIX.PAGE-ID !
            THEN
        ENDOF
        LIBPA-RANGE-COLLECTION-ORDER OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R> DROP LIBPA-S-INVALID EXIT
            THEN
        ENDOF
        LIBPA-RANGE-COLLECTION-TITLE OF
            R@ _LIBPIX.PROGRESS-LIMIT @ IF
                R@ _LIBPIX.MEMBER-ARG @
                R@ _LIBPIX.PROGRESS-LIMIT @
                R@ _LIBPIX.KEY0 LIBPI-COLLECTION-TITLE-PREFIX
                DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
                LIBPI-COLLECTION-TITLE-PREFIX-SIZE
                    R@ _LIBPIX.PAGE-ID !
            THEN
        ENDOF
        LIBPA-RANGE-MEMBERSHIP OF
            R@ _LIBPIX.PROGRESS-LIMIT @ RID-SIZE <> IF
                R> DROP LIBPA-S-INVALID EXIT
            THEN
            R@ _LIBPIX.MEMBER-ARG @
            R@ _LIBPIX.KEY0 LIBPI-MEMBERSHIP-PREFIX
            DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
            LIBPI-MEMBERSHIP-PREFIX-SIZE R@ _LIBPIX.PAGE-ID !
        ENDOF
        LIBPA-RANGE-HISTORY OF
            R@ _LIBPIX.PROGRESS-LIMIT @ RID-SIZE <> IF
                R> DROP LIBPA-S-INVALID EXIT
            THEN
            R@ _LIBPIX.MEMBER-ARG @
            R@ _LIBPIX.KEY0 LIBPI-HISTORY-PREFIX
            DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
            RID-SIZE R@ _LIBPIX.PAGE-ID !
        ENDOF
        R> DROP LIBPA-S-INVALID EXIT
    ENDCASE
    R> DROP LIBPA-S-OK ;

: _LIBPIX-RANGE-KEY-PREFIX?  ( key-a key-u index-work -- flag )
    >R
    DUP R@ _LIBPIX.PAGE-ID @ < IF 2DROP R> DROP 0 EXIT THEN
    DROP R@ _LIBPIX.KEY0 R@ _LIBPIX.PAGE-ID @ _LIBPA-BYTES=
    R> DROP ;

: _LIBPIX-RANGE-ROW-ADDRESS  ( index-work -- row )
    DUP _LIBPIX.RESULT-N @ LIBPA-RANGE-ROW-SIZE *
    SWAP _LIBPIX.MEMBER-LIST-ARG @ + ;

: _LIBPIX-RANGE-BOUNDARY-NOTE  ( index-work -- )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-BEFORE = IF
        R@ _LIBPIX.RESULT-N @ 0= IF
            R@ _LIBPIX.CALLBACK-CONTEXT @
            OVER _LIBPACONT.LAST-KEY
            R@ _LIBPIX.REVISION-ARG @ MOVE
            R@ _LIBPIX.REVISION-ARG @
            OVER _LIBPACONT.LAST-U !
        THEN
        R@ _LIBPIX.CALLBACK-CONTEXT @
        OVER _LIBPACONT.FIRST-KEY
        R@ _LIBPIX.REVISION-ARG @ MOVE
        R@ _LIBPIX.REVISION-ARG @ SWAP _LIBPACONT.FIRST-U !
        R> DROP EXIT
    THEN
    R@ _LIBPIX.RESULT-N @ 0= IF
        R@ _LIBPIX.CALLBACK-CONTEXT @
        OVER _LIBPACONT.FIRST-KEY
        R@ _LIBPIX.REVISION-ARG @ MOVE
        R@ _LIBPIX.REVISION-ARG @
        OVER _LIBPACONT.FIRST-U !
    THEN
    R@ _LIBPIX.CALLBACK-CONTEXT @
    OVER _LIBPACONT.LAST-KEY
    R@ _LIBPIX.REVISION-ARG @ MOVE
    R@ _LIBPIX.REVISION-ARG @ SWAP _LIBPACONT.LAST-U !
    R> DROP ;

: _LIBPIX-RANGE-RID-OFFSET  ( family -- offset|-1 )
    DUP LIBPA-RANGE-HISTORY = IF DROP 0 EXIT THEN
    DUP _LIBPA-RANGE-KEY-SIZE DUP 0= IF 2DROP -1 EXIT THEN
    RID-SIZE - NIP ;

: _LIBPIX-RANGE-ORDER-OFFSET  ( family -- offset|-1 )
    CASE
        LIBPA-RANGE-DOCUMENT-CREATION OF 0 ENDOF
        LIBPA-RANGE-DOCUMENT-RECENCY OF 0 ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-CREATION OF 3 ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-RECENCY OF 3 ENDOF
        LIBPA-RANGE-DOCUMENT-TITLE OF -1 ENDOF
        LIBPA-RANGE-EXACT-TAG OF _LIBPI-TAG-BYTES ENDOF
        LIBPA-RANGE-CANDIDATE OF _LIBPI-BODY-BYTES ENDOF
        LIBPA-RANGE-COLLECTION-ORDER OF 0 ENDOF
        LIBPA-RANGE-COLLECTION-TITLE OF -1 ENDOF
        LIBPA-RANGE-MEMBERSHIP OF RID-SIZE ENDOF
        LIBPA-RANGE-HISTORY OF RID-SIZE ENDOF
        -1 SWAP
    ENDCASE ;

: _LIBPIX-RANGE-VALUE?  ( row index-work -- flag )
    >R
    R@ _LIBPIX.OPERATION-KIND @ CASE
        LIBPA-RANGE-CANDIDATE OF
            R@ _LIBPIX.AUX-ARG @ 1 <> IF DROP R> DROP 0 EXIT THEN
            R@ _LIBPIX.OTHER-RID-ARG @ C@ DUP 1 <
            SWAP LIBPA-CANDIDATE-TITLE LIBPA-CANDIDATE-BODY OR >
                OR IF DROP R> DROP 0 EXIT THEN
            R@ _LIBPIX.OTHER-RID-ARG @ C@
                OVER LIBPA-RANGE-ROW.VALUE !
            DROP R> DROP -1 EXIT
        ENDOF
        LIBPA-RANGE-MEMBERSHIP OF
            R@ _LIBPIX.AUX-ARG @ 0= NIP R> DROP EXIT
        ENDOF
        LIBPA-RANGE-HISTORY OF
            R@ _LIBPIX.AUX-ARG @ PERSIST-REF-SIZE <> IF
                DROP R> DROP 0 EXIT
            THEN
            R@ _LIBPIX.OTHER-RID-ARG @ PERSIST-REF-VALID?
            NIP R> DROP EXIT
        ENDOF
    ENDCASE
    R@ _LIBPIX.AUX-ARG @ RID-SIZE <> IF DROP R> DROP 0 EXIT THEN
    DUP LIBPA-RANGE-ROW.RID
    R@ _LIBPIX.OTHER-RID-ARG @ RID=
    NIP R> DROP ;

: _LIBPIX-RANGE-TITLE-ORDER  ( row index-work -- status )
    >R
    R@ _LIBPIX.KEY0 R@ _LIBPIX.PAGE
    R@ _LIBPIX.PAGE-ID @ MOVE
    R@ _LIBPIX.OPERATION-KIND @
        LIBPA-RANGE-DOCUMENT-TITLE = IF
        DUP LIBPA-RANGE-ROW.RID R@ _LIBPIX.RID-ARG !
        R@ _LIBPIX.OLD-ENTRY R@ _LIBPIX.ENTRY-ARG !
        R@ _LIBPIX-RID-LOOKUP-CORE
        DUP IF NIP R> DROP EXIT THEN DROP
        R@ _LIBPIX.PAGE R@ _LIBPIX.KEY0
        R@ _LIBPIX.PAGE-ID @ MOVE
        R@ _LIBPIX.OLD-ENTRY LIBE.CREATED-VALUE @
        SWAP LIBPA-RANGE-ROW.ORDER !
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND @
        LIBPA-RANGE-COLLECTION-TITLE = IF
        DUP LIBPA-RANGE-ROW.RID R@ _LIBPIX.RID-ARG !
        R@ _LIBPIX.OLD-COLLECTION R@ _LIBPIX.OUTPUT-ARG !
        R@ _LIBPIX-COLLECTION-READ-CORE
        DUP IF NIP R> DROP EXIT THEN DROP
        R@ _LIBPIX.PAGE R@ _LIBPIX.KEY0
        R@ _LIBPIX.PAGE-ID @ MOVE
        R@ _LIBPIX.OLD-COLLECTION LIBPAC.CREATED-SEQUENCE @
        SWAP LIBPA-RANGE-ROW.ORDER !
        R> DROP LIBPA-S-OK EXIT
    THEN
    DROP R> DROP LIBPA-S-CORRUPT ;

: _LIBPIX-RANGE-ROW
  ( key-a key-u value-a value-u persist-status index-work -- status )
    >R
    DUP IF
        _LIBPA-PERSIST>STATUS >R _LIBPA-DROP4 R> R> DROP EXIT
    THEN DROP
    3 PICK 2 PICK R@ _LIBPIX-RANGE-KEY-PREFIX? 0= IF
        _LIBPA-DROP4 R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    2 PICK
    R@ _LIBPIX.OPERATION-KIND @ _LIBPA-RANGE-KEY-SIZE <> IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DUP R@ _LIBPIX.AUX-ARG !
    1 PICK R@ _LIBPIX.OTHER-RID-ARG !
    2 PICK R@ _LIBPIX.REVISION-ARG !
    3 PICK R@ _LIBPIX.CALLBACK-CONTEXT !
    _LIBPA-DROP4
    R@ _LIBPIX-RANGE-BOUNDARY-NOTE
    R@ _LIBPIX-RANGE-ROW-ADDRESS DUP LIBPA-RANGE-ROW-SIZE 0 FILL
    R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-RID-OFFSET
    DUP 0< IF 2DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    R@ _LIBPIX.CALLBACK-CONTEXT @ +
    OVER LIBPA-RANGE-ROW.RID RID-COPY
    DUP LIBPA-RANGE-ROW.RID RID-PRESENT? 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DUP R@ _LIBPIX-RANGE-VALUE? 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-ORDER-OFFSET
    DUP 0< IF
        DROP DUP R@ _LIBPIX-RANGE-TITLE-ORDER
        DUP IF NIP R> DROP EXIT THEN DROP
    ELSE
        R@ _LIBPIX.CALLBACK-CONTEXT @ + _LIBPIX-U64-BE@
        OVER LIBPA-RANGE-ROW.ORDER !
    THEN
    DUP LIBPA-RANGE-ROW.ORDER @ 0> 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP
    1 R@ _LIBPIX.RESULT-N +!
    R> DROP LIBPA-S-OK ;

: _LIBPIX-RANGE-CONTINUATION-MATCH?  ( index-work -- flag )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @
        LIBPA-CONTINUATION-VALID? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.FAMILY @
    R@ _LIBPIX.OPERATION-KIND @ <> IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.PREFIX-U @
    R@ _LIBPIX.PROGRESS-LIMIT @ <> IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.PROGRESS-LIMIT @ 0= IF R> DROP -1 EXIT THEN
    R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @
    R@ _LIBPIX.KEY1 SHA3-256-HASH
    R@ _LIBPIX.KEY1
    R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.PREFIX-SEAL
    SHA3-256-COMPARE
    R> DROP ;

: _LIBPIX-RANGE-CONTINUATION-INIT  ( index-work -- )
    >R
    R@ _LIBPIX.NEXT-ENTRY-ARG @
    DUP LIBPA-CONTINUATION-SIZE 0 FILL
    DUP _LIBPACONT-MAGIC SWAP _LIBPACONT.MAGIC !
    DUP R@ _LIBPIX.OPERATION-KIND @ SWAP _LIBPACONT.FAMILY !
    DUP R@ _LIBPIX.TEMP-STATUS @ SWAP _LIBPACONT.DIRECTION !
    DUP R@ _LIBPIX.LOGICAL-GENERATION @ SWAP _LIBPACONT.LOGICAL !
    DUP R@ _LIBPIX.PROGRESS-LIMIT @ SWAP _LIBPACONT.PREFIX-U !
    R@ _LIBPIX.PROGRESS-LIMIT @ IF
        _LIBPACONT.PREFIX-SEAL
        R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @
        ROT SHA3-256-HASH
    ELSE
        DROP
    THEN
    R> DROP ;

: _LIBPIX-RANGE-RESUME-COPY  ( index-work -- status )
    >R
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-AFTER = IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.LAST-KEY
        R@ _LIBPIX.KEY1
        R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.LAST-U @ MOVE
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-BEFORE = IF
        R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.FIRST-KEY
        R@ _LIBPIX.KEY1
        R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.FIRST-U @ MOVE
        R> DROP LIBPA-S-OK EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPIX-RANGE-CURSOR-NEXT  ( index-work -- status )
    >R
    R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-TREE
    DUP R@ _LIBPIX-ROOT
    SWAP R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-NEXT
    R@ _LIBPIX-RANGE-ROW R> DROP ;

: _LIBPIX-RANGE-CURSOR-PREV  ( index-work -- status )
    >R
    R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-TREE
    DUP R@ _LIBPIX-ROOT
    SWAP R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-PREV
    R@ _LIBPIX-RANGE-ROW R> DROP ;

: _LIBPIX-RANGE-CURSOR-FIRST  ( index-work -- status )
    >R
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-AFTER = IF
        R@ _LIBPIX.KEY1
        R@ _LIBPIX.OPERATION-KIND @ _LIBPA-RANGE-KEY-SIZE
        R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-TREE
        DUP R@ _LIBPIX-ROOT
        SWAP R@ _LIBPIX-TREE
        R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-RESUME
        R@ _LIBPIX-RANGE-ROW R> DROP EXIT
    THEN
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-BEFORE = IF
        R@ _LIBPIX.KEY1
        R@ _LIBPIX.OPERATION-KIND @ _LIBPA-RANGE-KEY-SIZE
        R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-TREE
        DUP R@ _LIBPIX-ROOT
        SWAP R@ _LIBPIX-TREE
        R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-SEEK-BEFORE
        R@ _LIBPIX-RANGE-ROW R> DROP EXIT
    THEN
    R@ _LIBPIX.PAGE-ID @ 0= IF
        R> _LIBPIX-RANGE-CURSOR-NEXT EXIT
    THEN
    R@ _LIBPIX.KEY0 R@ _LIBPIX.PAGE-ID @
    R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-TREE
    DUP R@ _LIBPIX-ROOT
    SWAP R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR R@ _LIBPIX.BTREE-WORK PBTREE-SEEK
    R@ _LIBPIX-RANGE-ROW R> DROP ;

: _LIBPIX-RANGE-REVERSE-ROWS  ( index-work -- )
    >R 0
    BEGIN
        DUP R@ _LIBPIX.RESULT-N @ 2 / <
    WHILE
        R@ _LIBPIX.MEMBER-LIST-ARG @
        OVER LIBPA-RANGE-ROW-SIZE * +
        R@ _LIBPIX.PAGE LIBPA-RANGE-ROW-SIZE MOVE
        R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.RESULT-N @ 1- 2 PICK -
        LIBPA-RANGE-ROW-SIZE * +
        R@ _LIBPIX.MEMBER-LIST-ARG @
        2 PICK LIBPA-RANGE-ROW-SIZE * +
        LIBPA-RANGE-ROW-SIZE MOVE
        R@ _LIBPIX.PAGE
        R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.RESULT-N @ 1- 3 PICK -
        LIBPA-RANGE-ROW-SIZE * +
        LIBPA-RANGE-ROW-SIZE MOVE
        1+
    REPEAT
    DROP R> DROP ;

128 CONSTANT LIBPA-RANGE-ROW-MAX
LIBPA-RANGE-ROW-MAX LIBPA-RANGE-ROW-SIZE *
    CONSTANT _LIBPIX-RANGE-CONTINUATION-STAGE-OFF

: _LIBPIX-RANGE-ARGS?  ( index-work -- flag )
    >R
    R@ _LIBPIX.OPERATION-KIND @ _LIBPA-RANGE-FAMILY? 0= IF
        R> DROP 0 EXIT
    THEN
    R@ _LIBPIX.TEMP-STATUS @ DUP LIBPA-CONTINUATION-SEEDED <
    SWAP LIBPA-CONTINUATION-BEFORE > OR IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.PROGRESS-LIMIT @ DUP 0<
    SWAP LIBPI-KEY-MAX > OR IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.PROGRESS-LIMIT @ IF
        R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @
        R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    THEN
    R@ _LIBPIX.TOTAL-ARG @ DUP 1 <
    SWAP LIBPA-RANGE-ROW-MAX > OR IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.MEMBER-LIST-ARG @
    R@ _LIBPIX.TOTAL-ARG @ LIBPA-RANGE-ROW-SIZE *
    R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-CONTINUATION-SIZE
    R@ _LIBPIX-SPAN-SAFE? 0= IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.MEMBER-LIST-ARG @
    R@ _LIBPIX.TOTAL-ARG @ LIBPA-RANGE-ROW-SIZE *
    R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-CONTINUATION-SIZE
        MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    R@ _LIBPIX.PROGRESS-LIMIT @ IF
        R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @
        R@ _LIBPIX.MEMBER-LIST-ARG @
        R@ _LIBPIX.TOTAL-ARG @ LIBPA-RANGE-ROW-SIZE *
            MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
        R@ _LIBPIX.MEMBER-ARG @ R@ _LIBPIX.PROGRESS-LIMIT @
        R@ _LIBPIX.NEXT-ENTRY-ARG @ LIBPA-CONTINUATION-SIZE
            MSPAN-OVERLAP? IF R> DROP 0 EXIT THEN
    THEN
    R> DROP -1 ;

: _LIBPIX-RANGE-OUTPUT-STAGE  ( index-work -- )
    >R
    R@ _LIBPIX.MEMBER-LIST-ARG @ R@ _LIBPIX.OUTPUT-ARG !
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.CONTENT-ARG !
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-SEEDED <> IF
        R@ _LIBPIX.CONTENT-ARG @
        R@ _LIBPIX.CONTENT-SCRATCH
            _LIBPIX-RANGE-CONTINUATION-STAGE-OFF +
        LIBPA-CONTINUATION-SIZE MOVE
    THEN
    R@ _LIBPIX.CONTENT-SCRATCH R@ _LIBPIX.MEMBER-LIST-ARG !
    R@ _LIBPIX.CONTENT-SCRATCH
        _LIBPIX-RANGE-CONTINUATION-STAGE-OFF +
    R@ _LIBPIX.NEXT-ENTRY-ARG !
    R> DROP ;

: _LIBPIX-RANGE-SUCCESS  ( index-work -- status )
    >R
    R@ _LIBPIX.RESULT-N @ 0=
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-SEEDED <> AND IF
        R@ _LIBPIX.CONTENT-ARG @
        R@ _LIBPIX.NEXT-ENTRY-ARG @
        LIBPA-CONTINUATION-SIZE MOVE
        R@ _LIBPIX.TEMP-STATUS @
        R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.DIRECTION !
        R@ _LIBPIX.LOGICAL-GENERATION @
        R@ _LIBPIX.NEXT-ENTRY-ARG @ _LIBPACONT.LOGICAL !
    THEN
    R@ _LIBPIX.NEXT-ENTRY-ARG @
        LIBPA-CONTINUATION-VALID?
    0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.MEMBER-LIST-ARG @ R@ _LIBPIX.OUTPUT-ARG @
    R@ _LIBPIX.RESULT-N @ LIBPA-RANGE-ROW-SIZE * MOVE
    R@ _LIBPIX.NEXT-ENTRY-ARG @ R@ _LIBPIX.CONTENT-ARG @
    LIBPA-CONTINUATION-SIZE MOVE
    R> DROP LIBPA-S-OK ;

: _LIBPIX-RANGE-RUN  ( index-work -- status )
    >R
    R@ _LIBPIX-READY? 0= IF R> DROP LIBPA-S-BUSY EXIT THEN
    R@ _LIBPIX-RANGE-ARGS? 0= IF R> DROP LIBPA-S-INVALID EXIT THEN
    R@ _LIBPIX-RANGE-OUTPUT-STAGE
    R@ _LIBPIX-RANGE-PREFIX-BUILD
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-SEEDED <> IF
        R@ _LIBPIX-RANGE-CONTINUATION-MATCH? 0= IF
            R> DROP LIBPA-S-INVALID EXIT
        THEN
        R@ _LIBPIX-RANGE-RESUME-COPY
        DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPIX-RANGE-CONTINUATION-INIT
    R@ _LIBPIX.MEMBER-LIST-ARG @
    R@ _LIBPIX.TOTAL-ARG @ LIBPA-RANGE-ROW-SIZE * 0 FILL
    0 R@ _LIBPIX.RESULT-N !
    R@ _LIBPIX.OPERATION-KIND @ _LIBPIX-RANGE-TREE
    DUP R@ _LIBPIX-ROOT
    SWAP R@ _LIBPIX-TREE
    R@ _LIBPIX.CURSOR PBTREE-CURSOR-INIT
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPIX-RANGE-CURSOR-FIRST
    DUP LIBPA-S-NOT-FOUND = IF
        DROP R> _LIBPIX-RANGE-SUCCESS EXIT
    THEN
    DUP IF R> DROP EXIT THEN DROP
    BEGIN
        R@ _LIBPIX.RESULT-N @ R@ _LIBPIX.TOTAL-ARG @ <
    WHILE
        R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-BEFORE = IF
            R@ _LIBPIX-RANGE-CURSOR-PREV
        ELSE
            R@ _LIBPIX-RANGE-CURSOR-NEXT
        THEN
        DUP LIBPA-S-NOT-FOUND = IF
            DROP
            R@ _LIBPIX.TEMP-STATUS @
                LIBPA-CONTINUATION-BEFORE = IF
                R@ _LIBPIX-RANGE-REVERSE-ROWS
            THEN
            R> _LIBPIX-RANGE-SUCCESS EXIT
        THEN
        DUP IF R> DROP EXIT THEN DROP
    REPEAT
    R@ _LIBPIX.TEMP-STATUS @ LIBPA-CONTINUATION-BEFORE = IF
        R@ _LIBPIX-RANGE-REVERSE-ROWS
    THEN
    R> _LIBPIX-RANGE-SUCCESS ;

\ Stack: family prefix-a prefix-u rows capacity continuation mode adapter work.
\ Returns count status.
: _LIBPA-RANGE-PUBLIC
    2DUP _LIBPIX-ENTER DUP IF
        >R _LIBPA-DROP9 0 R> EXIT
    THEN DROP
    >R
    1 PICK R@ _LIBPIX.TEMP-STATUS !
    2 PICK R@ _LIBPIX.NEXT-ENTRY-ARG !
    3 PICK R@ _LIBPIX.TOTAL-ARG !
    4 PICK R@ _LIBPIX.MEMBER-LIST-ARG !
    5 PICK R@ _LIBPIX.PROGRESS-LIMIT !
    6 PICK R@ _LIBPIX.MEMBER-ARG !
    7 PICK R@ _LIBPIX.OPERATION-KIND !
    R@ ['] _LIBPIX-RANGE-RUN _LIBPIX-WORK-CATCH
    SWAP R@ _LIBPIX-LEAVE
    R@ _LIBPIX-COUNT-RESULT
    >R >R _LIBPA-DROP7 R> R> R> DROP ;

\ Stack: family prefix-a prefix-u rows capacity continuation adapter work.
\ Returns count status.
: LIBPA-RANGE-FIRST
    >R >R
    LIBPA-CONTINUATION-SEEDED
    R> R> _LIBPA-RANGE-PUBLIC ;

\ Stack: family prefix-a prefix-u rows capacity continuation adapter work.
\ Returns count status.
: LIBPA-RANGE-AFTER
    >R >R
    LIBPA-CONTINUATION-AFTER
    R> R> _LIBPA-RANGE-PUBLIC ;

\ Stack: family prefix-a prefix-u rows capacity continuation adapter work.
\ Returns count status.
: LIBPA-RANGE-BEFORE
    >R >R
    LIBPA-CONTINUATION-BEFORE
    R> R> _LIBPA-RANGE-PUBLIC ;

: _LIBPA-RANGE-SEED-KEY
  ( family prefix-a prefix-u order rid destination -- status )
    >R
    4 PICK CASE
        LIBPA-RANGE-DOCUMENT-CREATION OF
            2 PICK IF LIB-S-INVALID ELSE
                OVER OVER R@ LIBPI-ORDER-KEY
            THEN
        ENDOF
        LIBPA-RANGE-DOCUMENT-RECENCY OF
            2 PICK IF LIB-S-INVALID ELSE
                OVER OVER R@ LIBPI-RECENCY-KEY
            THEN
        ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-CREATION OF
            2 PICK 3 <> IF
                LIB-S-INVALID
            ELSE
                3 PICK DUP C@ OVER 1+ C@ ROT 2 + C@
                4 PICK 4 PICK R@ LIBPI-STATE-CREATION-KEY
            THEN
        ENDOF
        LIBPA-RANGE-DOCUMENT-STATE-RECENCY OF
            2 PICK 3 <> IF
                LIB-S-INVALID
            ELSE
                3 PICK DUP C@ OVER 1+ C@ ROT 2 + C@
                4 PICK 4 PICK R@ LIBPI-STATE-RECENCY-KEY
            THEN
        ENDOF
        LIBPA-RANGE-DOCUMENT-TITLE OF
            2 PICK 0= IF
                LIB-S-INVALID
            ELSE
                3 PICK 3 PICK 2 PICK R@ LIBPI-TITLE-KEY
            THEN
        ENDOF
        LIBPA-RANGE-EXACT-TAG OF
            2 PICK 0= IF
                LIB-S-INVALID
            ELSE
                3 PICK 3 PICK 3 PICK 3 PICK R@
                LIBPI-TAG-KEY
            THEN
        ENDOF
        LIBPA-RANGE-CANDIDATE OF
            2 PICK 0= IF
                LIB-S-INVALID
            ELSE
                3 PICK 3 PICK 3 PICK 3 PICK R@
                LIBPI-BODY-KEY
            THEN
        ENDOF
        LIBPA-RANGE-COLLECTION-ORDER OF
            2 PICK IF LIB-S-INVALID ELSE
                OVER OVER R@ LIBPI-COLLECTION-ORDER-KEY
            THEN
        ENDOF
        LIBPA-RANGE-COLLECTION-TITLE OF
            2 PICK 0= IF
                LIB-S-INVALID
            ELSE
                3 PICK 3 PICK 2 PICK R@
                LIBPI-COLLECTION-TITLE-KEY
            THEN
        ENDOF
        LIBPA-RANGE-MEMBERSHIP OF
            2 PICK RID-SIZE <> IF
                LIB-S-INVALID
            ELSE
                3 PICK 2 PICK 2 PICK R@ LIBPI-MEMBERSHIP-KEY
            THEN
        ENDOF
        LIBPA-RANGE-HISTORY OF
            2 PICK RID-SIZE <> IF
                LIB-S-INVALID
            ELSE
                3 PICK OVER RID= 0= IF
                    LIB-S-INVALID
                ELSE
                    3 PICK 2 PICK R@ LIBPI-HISTORY-DOMAIN-KEY
                THEN
            THEN
        ENDOF
        LIB-S-INVALID SWAP
    ENDCASE
    _LIBPA-LIB>STATUS
    R> DROP >R _LIBPA-DROP5 R> ;

\ Builds pointer-free continuation state from semantic stable boundaries.
\ State-filtered seeding requires the exact lifecycle/kind/media prefix.
\ Stack includes family/prefix, two order-plus-RID boundaries, and output.
: LIBPA-CONTINUATION-SEED
    >R
    6 PICK _LIBPA-RANGE-FAMILY? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    \ A lexical title prefix does not identify the complete title bytes in
    \ an index boundary, so these two families cannot be seeded from the
    \ semantic order-plus-RID boundary contract.
    6 PICK DUP LIBPA-RANGE-DOCUMENT-TITLE =
    SWAP LIBPA-RANGE-COLLECTION-TITLE = OR IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    4 PICK DUP 0< SWAP LIBPI-KEY-MAX > OR IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    4 PICK IF
        5 PICK 0= IF
            _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
        THEN
        5 PICK 5 PICK MSPAN-NONWRAPPING? 0= IF
            _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
        THEN
    THEN
    3 PICK 0> 0= 2 PICK 0> 0= OR IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK RID-SIZE MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK RID-PRESENT? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP 0= IF _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT THEN
    DUP RID-SIZE MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP RID-PRESENT? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    R@ 0= IF _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT THEN
    R@ LIBPA-CONTINUATION-SIZE MSPAN-NONWRAPPING? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    2 PICK RID-SIZE R@ LIBPA-CONTINUATION-SIZE
        MSPAN-OVERLAP? IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    DUP RID-SIZE R@ LIBPA-CONTINUATION-SIZE
        MSPAN-OVERLAP? IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    4 PICK IF
        5 PICK 5 PICK R@ LIBPA-CONTINUATION-SIZE
            MSPAN-OVERLAP? IF
            _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
        THEN
    THEN
    R@ LIBPA-CONTINUATION-SIZE 0 FILL
    _LIBPACONT-MAGIC R@ _LIBPACONT.MAGIC !
    6 PICK R@ _LIBPACONT.FAMILY !
    LIBPA-CONTINUATION-SEEDED R@ _LIBPACONT.DIRECTION !
    0 R@ _LIBPACONT.LOGICAL !
    4 PICK R@ _LIBPACONT.PREFIX-U !
    4 PICK IF
        5 PICK 5 PICK R@ _LIBPACONT.PREFIX-SEAL SHA3-256-HASH
    THEN
    6 PICK 6 PICK 6 PICK 6 PICK 6 PICK
    R@ _LIBPACONT.FIRST-KEY _LIBPA-RANGE-SEED-KEY
    DUP IF _LIBPA-DROP7 R> DROP EXIT THEN DROP
    6 PICK _LIBPA-RANGE-KEY-SIZE R@ _LIBPACONT.FIRST-U !
    6 PICK 6 PICK 6 PICK 4 PICK 4 PICK
    R@ _LIBPACONT.LAST-KEY _LIBPA-RANGE-SEED-KEY
    DUP IF _LIBPA-DROP7 R> DROP EXIT THEN DROP
    6 PICK _LIBPA-RANGE-KEY-SIZE R@ _LIBPACONT.LAST-U !
    R@ LIBPA-CONTINUATION-VALID? 0= IF
        _LIBPA-DROP7 R> DROP LIBPA-S-INVALID EXIT
    THEN
    _LIBPA-DROP7 R> DROP LIBPA-S-OK ;

\ =====================================================================
\ Adapter-owned semantic compaction
\ =====================================================================
\ Neutral PCOMPACT owns bank selection and the publication fence.  This
\ caller-owned context owns the Library meaning needed to rebuild the one
\ current root: retained immutable content first, then current document and
\ collection records, followed by the remaining exact index rows.

0x4C49425041434D31 CONSTANT _LIBPACOM-MAGIC  \ "LIBPACM1"

0 CONSTANT _LIBPACOM-STATE-BOUND
1 CONSTANT _LIBPACOM-STATE-RUNNING
2 CONSTANT _LIBPACOM-STATE-DONE

0 CONSTANT _LIBPACOM-PHASE-HISTORY
1 CONSTANT _LIBPACOM-PHASE-DOCUMENT
2 CONSTANT _LIBPACOM-PHASE-COLLECTION
3 CONSTANT _LIBPACOM-PHASE-INDEX
4 CONSTANT _LIBPACOM-PHASE-DONE

  0 CONSTANT _LIBPACOM-MAGIC-OFF
  8 CONSTANT _LIBPACOM-SELF-OFF
 16 CONSTANT _LIBPACOM-STATUS-OFF
 24 CONSTANT _LIBPACOM-STATE-OFF
 32 CONSTANT _LIBPACOM-PHASE-OFF
 40 CONSTANT _LIBPACOM-TREE-OFF
 48 CONSTANT _LIBPACOM-CURSOR-READY-OFF
 56 CONSTANT _LIBPACOM-ROW-ACTIVE-OFF
 64 CONSTANT _LIBPACOM-SOURCE-ADAPTER-OFF
 72 CONSTANT _LIBPACOM-SOURCE-WORK-OFF
 80 CONSTANT _LIBPACOM-BUILDER-ADAPTER-OFF
 88 CONSTANT _LIBPACOM-BUILDER-WORK-OFF
 96 CONSTANT _LIBPACOM-KEY-U-OFF
104 CONSTANT _LIBPACOM-VALUE-U-OFF
112 CONSTANT _LIBPACOM-LOGICAL-OFF
120 CONSTANT _LIBPACOM-MUTATION-OFF
128 CONSTANT _LIBPACOM-DOCUMENTS-OFF
136 CONSTANT _LIBPACOM-COLLECTIONS-OFF
144 CONSTANT _LIBPACOM-MEMBERSHIPS-OFF
152 CONSTANT _LIBPACOM-BOOTSTRAP-OFF
184 CONSTANT _LIBPACOM-ALLOWANCE-OFF
192 CONSTANT _LIBPACOM-USED-OFF
200 CONSTANT _LIBPACOM-BLOB-DONE-OFF
208 CONSTANT _LIBPACOM-ROW-READY-OFF
216 CONSTANT LIBPA-COMPACTION-CONTEXT-SIZE

: _LIBPACOM.MAGIC          ( context -- a ) _LIBPACOM-MAGIC-OFF + ;
: _LIBPACOM.SELF           ( context -- a ) _LIBPACOM-SELF-OFF + ;
: _LIBPACOM.STATUS         ( context -- a ) _LIBPACOM-STATUS-OFF + ;
: _LIBPACOM.STATE          ( context -- a ) _LIBPACOM-STATE-OFF + ;
: _LIBPACOM.PHASE          ( context -- a ) _LIBPACOM-PHASE-OFF + ;
: _LIBPACOM.TREE           ( context -- a ) _LIBPACOM-TREE-OFF + ;
: _LIBPACOM.CURSOR-READY   ( context -- a )
    _LIBPACOM-CURSOR-READY-OFF + ;
: _LIBPACOM.ROW-ACTIVE     ( context -- a )
    _LIBPACOM-ROW-ACTIVE-OFF + ;
: _LIBPACOM.SOURCE-ADAPTER ( context -- a )
    _LIBPACOM-SOURCE-ADAPTER-OFF + ;
: _LIBPACOM.SOURCE-WORK    ( context -- a )
    _LIBPACOM-SOURCE-WORK-OFF + ;
: _LIBPACOM.BUILDER-ADAPTER ( context -- a )
    _LIBPACOM-BUILDER-ADAPTER-OFF + ;
: _LIBPACOM.BUILDER-WORK   ( context -- a )
    _LIBPACOM-BUILDER-WORK-OFF + ;
: _LIBPACOM.KEY-U          ( context -- a ) _LIBPACOM-KEY-U-OFF + ;
: _LIBPACOM.VALUE-U        ( context -- a ) _LIBPACOM-VALUE-U-OFF + ;
: _LIBPACOM.LOGICAL        ( context -- a ) _LIBPACOM-LOGICAL-OFF + ;
: _LIBPACOM.MUTATION       ( context -- a ) _LIBPACOM-MUTATION-OFF + ;
: _LIBPACOM.DOCUMENTS      ( context -- a ) _LIBPACOM-DOCUMENTS-OFF + ;
: _LIBPACOM.COLLECTIONS    ( context -- a ) _LIBPACOM-COLLECTIONS-OFF + ;
: _LIBPACOM.MEMBERSHIPS    ( context -- a ) _LIBPACOM-MEMBERSHIPS-OFF + ;
: _LIBPACOM.BOOTSTRAP      ( context -- rid ) _LIBPACOM-BOOTSTRAP-OFF + ;
: _LIBPACOM.ALLOWANCE      ( context -- a ) _LIBPACOM-ALLOWANCE-OFF + ;
: _LIBPACOM.USED           ( context -- a ) _LIBPACOM-USED-OFF + ;
: _LIBPACOM.BLOB-DONE      ( context -- a ) _LIBPACOM-BLOB-DONE-OFF + ;
: _LIBPACOM.ROW-READY      ( context -- a ) _LIBPACOM-ROW-READY-OFF + ;

: _LIBPACOM-FLAG?  ( x -- flag )
    DUP 0= SWAP -1 = OR ;

: LIBPA-COMPACTION-CONTEXT-VALID?  ( context -- flag )
    DUP 0= IF DROP 0 EXIT THEN
    DUP LIBPA-COMPACTION-CONTEXT-SIZE
        MSPAN-NONWRAPPING? 0= IF DROP 0 EXIT THEN
    DUP _LIBPACOM.MAGIC @ _LIBPACOM-MAGIC <> IF DROP 0 EXIT THEN
    DUP _LIBPACOM.SELF @ OVER <> IF DROP 0 EXIT THEN
    DUP _LIBPACOM.STATUS @ _LIBPIX-STATUS? 0= IF DROP 0 EXIT THEN
    DUP _LIBPACOM.STATE @ DUP _LIBPACOM-STATE-BOUND <
        SWAP _LIBPACOM-STATE-DONE > OR IF DROP 0 EXIT THEN
    DUP _LIBPACOM.PHASE @ DUP _LIBPACOM-PHASE-HISTORY <
        SWAP _LIBPACOM-PHASE-DONE > OR IF DROP 0 EXIT THEN
    DUP _LIBPACOM.TREE @ DUP 0<
        SWAP _LIBPIX-TREE-COUNT > OR IF DROP 0 EXIT THEN
    DUP _LIBPACOM.CURSOR-READY @ _LIBPACOM-FLAG? 0= IF DROP 0 EXIT THEN
    DUP _LIBPACOM.ROW-ACTIVE @ _LIBPACOM-FLAG? 0= IF DROP 0 EXIT THEN
    DUP _LIBPACOM.SOURCE-ADAPTER @
    OVER _LIBPACOM.SOURCE-WORK @ _LIBPA-INDEX-BOUND? 0= IF
        DROP 0 EXIT
    THEN
    DUP _LIBPACOM.BUILDER-ADAPTER @
    OVER _LIBPACOM.BUILDER-WORK @ _LIBPA-INDEX-BOUND? 0= IF
        DROP 0 EXIT
    THEN
    DUP _LIBPACOM.SOURCE-ADAPTER @
    OVER _LIBPACOM.BUILDER-ADAPTER @ = IF DROP 0 EXIT THEN
    DUP _LIBPACOM.SOURCE-WORK @
    OVER _LIBPACOM.BUILDER-WORK @ = IF DROP 0 EXIT THEN
    DUP _LIBPACOM.KEY-U @ DUP 0< SWAP PBTREE-KEY-MAX > OR IF
        DROP 0 EXIT
    THEN
    DUP _LIBPACOM.VALUE-U @ DUP 0< SWAP PBTREE-VALUE-MAX > OR IF
        DROP 0 EXIT
    THEN
    DUP _LIBPACOM.ALLOWANCE @ 0< IF DROP 0 EXIT THEN
    DUP _LIBPACOM.USED @ DUP 0< IF 2DROP 0 EXIT THEN
    OVER _LIBPACOM.ALLOWANCE @ > IF DROP 0 EXIT THEN
    DUP _LIBPACOM.BLOB-DONE @ _LIBPACOM-FLAG? 0= IF DROP 0 EXIT THEN
    _LIBPACOM.ROW-READY @ _LIBPACOM-FLAG? ;

: _LIBPACOM-INIT-GEOMETRY?
  ( source-adapter source-work builder-adapter builder-work context -- flag )
    >R
    3 PICK 3 PICK _LIBPA-INDEX-BOUND? 0= IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    1 PICK 1 PICK _LIBPA-INDEX-BOUND? 0= IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    3 PICK 2 PICK = IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    2 PICK 1 PICK = IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    2 PICK LIBPA-INDEX-WORK-SIZE
    2 PICK LIBPA-INDEX-WORK-SIZE MSPAN-OVERLAP? IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    R@ LIBPA-COMPACTION-CONTEXT-SIZE
    5 PICK LIBPA-SIZE MSPAN-OVERLAP? IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    R@ LIBPA-COMPACTION-CONTEXT-SIZE
    4 PICK LIBPA-INDEX-WORK-SIZE MSPAN-OVERLAP? IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    R@ LIBPA-COMPACTION-CONTEXT-SIZE
    3 PICK LIBPA-SIZE MSPAN-OVERLAP? IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    R@ LIBPA-COMPACTION-CONTEXT-SIZE
    2 PICK LIBPA-INDEX-WORK-SIZE MSPAN-OVERLAP? IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    _LIBPA-DROP4 R> DROP -1 ;

: LIBPA-COMPACTION-CONTEXT-INIT
  ( source-adapter source-work builder-adapter builder-work context -- status )
    4 PICK 4 PICK 4 PICK 4 PICK 4 PICK
        _LIBPACOM-INIT-GEOMETRY? 0= IF
        _LIBPA-DROP5 LIBPA-S-INVALID EXIT
    THEN
    >R
    R@ LIBPA-COMPACTION-CONTEXT-SIZE 0 FILL
    _LIBPACOM-MAGIC R@ _LIBPACOM.MAGIC !
    R@ R@ _LIBPACOM.SELF !
    LIBPA-S-OK R@ _LIBPACOM.STATUS !
    _LIBPACOM-STATE-BOUND R@ _LIBPACOM.STATE !
    _LIBPACOM-PHASE-HISTORY R@ _LIBPACOM.PHASE !
    _LIBPIX-HISTORY R@ _LIBPACOM.TREE !
    3 PICK R@ _LIBPACOM.SOURCE-ADAPTER !
    2 PICK R@ _LIBPACOM.SOURCE-WORK !
    1 PICK R@ _LIBPACOM.BUILDER-ADAPTER !
    DUP R@ _LIBPACOM.BUILDER-WORK !
    _LIBPA-DROP4
    R@ LIBPA-COMPACTION-CONTEXT-VALID? 0= IF
        R@ LIBPA-COMPACTION-CONTEXT-SIZE 0 FILL
        R> DROP LIBPA-S-INVALID EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-SOURCE-ROOT?  ( source-root context -- flag )
    >R
    DUP PERSIST-ROOT-VALUE-VALID? 0= IF DROP R> DROP 0 EXIT THEN
    R@ _LIBPACOM.SOURCE-ADAPTER @ _LIBPA-D.STORE @
        PSTORE-CURRENT-ROOT@
    DUP 0= IF 2DROP R> DROP 0 EXIT THEN
    PERSIST-ROOT-VALUE-SIZE _LIBPA-BYTES=
    R> DROP ;

: _LIBPACOM-INDEX-TREE?  ( tree -- flag )
    DUP 0>= SWAP _LIBPIX-TREE-COUNT < AND ;

: _LIBPACOM-CURSOR-INIT  ( context -- status )
    >R
    R@ _LIBPACOM.TREE @ DUP _LIBPACOM-INDEX-TREE? 0= IF
        DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DUP R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX-ROOT
    SWAP R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX-TREE
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.CURSOR
    PBTREE-CURSOR-INIT _LIBPA-PERSIST>STATUS
    DUP IF R> DROP EXIT THEN DROP
    -1 R@ _LIBPACOM.CURSOR-READY !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-NEXT-ROW  ( context -- status )
    >R
    R@ _LIBPACOM.CURSOR-READY @ 0= IF
        R@ _LIBPACOM-CURSOR-INIT DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPACOM.TREE @ DUP R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX-ROOT
    SWAP R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX-TREE
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.CURSOR
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.BTREE-WORK
    PBTREE-NEXT
    DUP PERSIST-S-NOT-FOUND = IF
        DROP 2DROP 2DROP R> DROP LIBPA-S-NOT-FOUND EXIT
    THEN
    DUP IF
        _LIBPA-PERSIST>STATUS >R 2DROP 2DROP R> R> DROP EXIT
    THEN DROP
    DUP 0< OVER PBTREE-VALUE-MAX > OR IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    2 PICK DUP 0> 0= SWAP PBTREE-KEY-MAX > OR IF
        _LIBPA-DROP4 R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DUP R@ _LIBPACOM.VALUE-U !
    OVER R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY1 2 PICK MOVE
    2 PICK R@ _LIBPACOM.KEY-U !
    3 PICK R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY0
        4 PICK MOVE
    _LIBPA-DROP4
    -1 R@ _LIBPACOM.ROW-READY !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-NEXT-INDEX-TREE  ( context -- )
    >R
    1 R@ _LIBPACOM.TREE +!
    BEGIN
        R@ _LIBPACOM.TREE @ DUP _LIBPIX-RID-DIRECTORY =
        OVER _LIBPIX-COLLECTION-DIRECTORY = OR
        SWAP _LIBPIX-HISTORY = OR
    WHILE
        1 R@ _LIBPACOM.TREE +!
    REPEAT
    R@ _LIBPACOM.TREE @ _LIBPIX-TREE-COUNT >= IF
        _LIBPACOM-PHASE-DONE R@ _LIBPACOM.PHASE !
        _LIBPACOM-STATE-DONE R@ _LIBPACOM.STATE !
        _LIBPIX-TREE-COUNT R@ _LIBPACOM.TREE !
    THEN
    0 R@ _LIBPACOM.CURSOR-READY !
    R> DROP ;

: _LIBPACOM-NEXT-PHASE  ( context -- )
    >R
    R@ _LIBPACOM.PHASE @ CASE
        _LIBPACOM-PHASE-HISTORY OF
            _LIBPACOM-PHASE-DOCUMENT R@ _LIBPACOM.PHASE !
            _LIBPIX-RID-DIRECTORY R@ _LIBPACOM.TREE !
        ENDOF
        _LIBPACOM-PHASE-DOCUMENT OF
            _LIBPACOM-PHASE-COLLECTION R@ _LIBPACOM.PHASE !
            _LIBPIX-COLLECTION-DIRECTORY R@ _LIBPACOM.TREE !
        ENDOF
        _LIBPACOM-PHASE-COLLECTION OF
            _LIBPACOM-PHASE-INDEX R@ _LIBPACOM.PHASE !
            0 R@ _LIBPACOM.TREE !
        ENDOF
        _LIBPACOM-PHASE-INDEX OF
            R@ _LIBPACOM-NEXT-INDEX-TREE
        ENDOF
        DROP
        _LIBPACOM-STATE-DONE R@ _LIBPACOM.STATE !
        _LIBPACOM-PHASE-DONE R@ _LIBPACOM.PHASE !
        _LIBPIX-TREE-COUNT R@ _LIBPACOM.TREE !
    ENDCASE
    0 R@ _LIBPACOM.CURSOR-READY !
    R> DROP ;

: _LIBPACOM-CAPTURE-SOURCE  ( context -- status )
    >R
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX-READY? 0= IF
        R> DROP LIBPA-S-BUSY EXIT
    THEN
    R@ _LIBPACOM.BUILDER-ADAPTER @
    R@ _LIBPACOM.BUILDER-WORK @ LIBPA-INDEX-REBIND
    DUP LIBPA-S-ABSENT <> IF
        DUP LIBPA-S-OK = IF DROP LIBPA-S-CONFLICT THEN
        R> DROP EXIT
    THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.LOGICAL-GENERATION @
        R@ _LIBPACOM.LOGICAL !
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.MUTATION-SEQUENCE @
        R@ _LIBPACOM.MUTATION !
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.DOCUMENT-COUNT @
        R@ _LIBPACOM.DOCUMENTS !
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.COLLECTION-COUNT @
        R@ _LIBPACOM.COLLECTIONS !
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.MEMBERSHIP-COUNT @
        R@ _LIBPACOM.MEMBERSHIPS !
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.BOOTSTRAP-ID
        R@ _LIBPACOM.BOOTSTRAP RID-COPY
    _LIBPACOM-PHASE-HISTORY R@ _LIBPACOM.PHASE !
    _LIBPIX-HISTORY R@ _LIBPACOM.TREE !
    0 R@ _LIBPACOM.CURSOR-READY !
    0 R@ _LIBPACOM.ROW-ACTIVE !
    0 R@ _LIBPACOM.ROW-READY !
    _LIBPACOM-STATE-RUNNING R@ _LIBPACOM.STATE !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-BUILDER-ABORT  ( primary-status context -- final-status )
    >R
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STATE @
        _LIBPIX-STATE-ACTIVE = IF
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-ABORT-ACTIVE
    THEN
    R> DROP ;

: _LIBPACOM-BUILDER-BEGIN  ( context -- status )
    DUP _LIBPACOM.BUILDER-ADAPTER @
    OVER _LIBPACOM.BUILDER-WORK @
    LIBPA-INDEX-BEGIN NIP ;

: _LIBPACOM-BUILDER-PUBLISH  ( context -- status )
    >R
    1 R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PHYSICAL-ONLY-N !
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-PUBLISH-RUN
    R> DROP ;

: _LIBPACOM-BLOB-SINK
  ( logical-offset payload-a payload-u source-work -- persist-status )
    >R
    DUP 0< IF _LIBPA-DROP3 R> DROP PERSIST-S-INVALID EXIT THEN
    2 PICK R@ _LIBPIX.PROGRESS @ < IF
        _LIBPA-DROP3 R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    2 PICK R@ _LIBPIX.PROGRESS @ -
    DUP 2 PICK + R@ _LIBPIX.PROGRESS-LIMIT @ > IF
        DROP _LIBPA-DROP3 R> DROP PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPIX.MEMBER-ARG @ +
    2 PICK SWAP 2 PICK MOVE
    DUP R@ _LIBPIX.RESULT-N +!
    _LIBPA-DROP3 R> DROP PERSIST-S-OK ;

: _LIBPACOM-SOURCE-BLOB  ( context -- blob|0 )
    DUP _LIBPACOM.PHASE @ _LIBPACOM-PHASE-HISTORY = IF
        DUP _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT _LIBPAC.BLOB
        NIP EXIT
    THEN
    DUP _LIBPACOM.PHASE @ _LIBPACOM-PHASE-DOCUMENT = IF
        DUP _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE
            _LIBPAD.METADATA-BLOB
        NIP EXIT
    THEN
    DROP 0 ;

: _LIBPACOM-BLOB-SOURCE
  ( logical-offset destination-a requested-u context -- actual-u persist-status )
    >R
    DUP 0< IF _LIBPA-DROP3 R> DROP 0 PERSIST-S-INVALID EXIT THEN
    DUP R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PROGRESS-LIMIT !
    2 PICK R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PROGRESS !
    1 PICK R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.MEMBER-ARG !
    0 R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.RESULT-N !
    _LIBPA-DROP3
    R@ _LIBPACOM-SOURCE-BLOB DUP 0= IF
        DROP R> DROP 0 PERSIST-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PROGRESS @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PROGRESS-LIMIT @
    ['] _LIBPACOM-BLOB-SINK R@ _LIBPACOM.SOURCE-WORK @
    R@ _LIBPACOM.SOURCE-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.BLOB-WORK
    PBLOB-READ-RANGE
    DUP IF
        0 SWAP R> DROP EXIT
    THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.RESULT-N @
    DUP R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PROGRESS-LIMIT @ <> IF
        DROP R> DROP 0 PERSIST-S-CORRUPT EXIT
    THEN
    PERSIST-S-OK R> DROP ;

: _LIBPACOM-HISTORY-LOAD  ( context -- status )
    >R
    R@ _LIBPACOM.KEY-U @ LIBPI-HISTORY-KEY-SIZE <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.VALUE-U @ PERSIST-REF-SIZE <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY1
    DUP PERSIST-REF-VALID? 0= IF DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.HISTORY-REF PERSIST-REF-COPY
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.HISTORY-REF
    R@ _LIBPACOM.SOURCE-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
    PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
        PSTORE-RECORD-PAYLOAD$
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
        LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-HISTORY-BEGIN  ( context -- status )
    >R
    R@ _LIBPACOM-HISTORY-LOAD DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPACOM-BUILDER-BEGIN
    DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
        _LIBPAC.DATA-U @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB
    R@ _LIBPACOM.BUILDER-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PSTORE-WORK @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB-WORK
    PBLOB-WRITE-BEGIN _LIBPA-PERSIST>STATUS
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    -1 R@ _LIBPACOM.ROW-ACTIVE !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-HISTORY-FINISH  ( context -- status )
    >R
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE _LIBPAC.BLOB
        PBLOB-COPY
    DUP IF _LIBPA-PERSIST>STATUS
        R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT
    THEN DROP
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
        LIBPA-CONTENT-DESCRIPTOR-VALID? 0= IF
        LIBPA-S-CORRUPT R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT
    THEN
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
    LIBPA-CONTENT-DESCRIPTOR-SIZE
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.HISTORY-REF
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-APPEND
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY0
    R@ _LIBPACOM.KEY-U @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.HISTORY-REF
    PERSIST-REF-SIZE _LIBPIX-HISTORY
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-PUT
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM-BUILDER-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPACOM.ROW-ACTIVE !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-HISTORY-STEP  ( context -- status )
    >R
    R@ _LIBPACOM.ROW-ACTIVE @ 0= IF
        R@ _LIBPACOM-HISTORY-BEGIN DUP IF R> DROP EXIT THEN DROP
    THEN
    ['] _LIBPACOM-BLOB-SOURCE R@
    R@ _LIBPACOM.ALLOWANCE @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB-WORK
    PBLOB-WRITE-STEP
    DUP R@ _LIBPACOM.STATUS !
    DROP
    DUP R@ _LIBPACOM.USED !
    DROP
    DUP R@ _LIBPACOM.BLOB-DONE !
    DROP
    R@ _LIBPACOM.STATUS @
    DUP IF
        R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT
    THEN DROP
    R@ _LIBPACOM.BLOB-DONE @ IF
        R@ _LIBPACOM-HISTORY-FINISH
    ELSE
        LIBPA-S-OK
    THEN
    R> DROP ;

: _LIBPACOM-DOCUMENT-CONTENT-REF  ( context -- status )
    >R
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.CONTENT-REF
    DUP PERSIST-REF-SIZE _LIBPA-ZERO? IF
        DROP
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.HISTORY-REF
            PERSIST-REF-INIT
        R> DROP LIBPA-S-OK EXIT
    THEN
    PERSIST-REF-VALID? 0= IF R> DROP LIBPA-S-CORRUPT EXIT THEN

    \ Domain revisions can advance without replacing content.  Resolve the
    \ current content frame from the document's checked source reference
    \ rather than assuming the entry's newest domain names a history row.
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.CONTENT-REF
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.HISTORY-REF PERSIST-REF-COPY
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.HISTORY-REF
    R@ _LIBPACOM.SOURCE-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
    PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
        PSTORE-RECORD-PAYLOAD$
    DUP LIBPA-CONTENT-DESCRIPTOR-SIZE <> IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
        LIBPA-CONTENT-DESCRIPTOR-SIZE MOVE
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.ENTRY
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
        _LIBPIX-DESCRIPTOR-AGREES? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN

    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.ENTRY LIBE.ID
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.OLD-CONTENT
        _LIBPAC.DOMAIN-REVISION @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.KEY1
    LIBPI-HISTORY-KEY
    DUP IF _LIBPA-LIB>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.KEY1
    LIBPI-HISTORY-KEY-SIZE _LIBPIX-HISTORY
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.HISTORY-REF
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-GET-REF
    R> DROP ;

: _LIBPACOM-DOCUMENT-LOAD  ( context -- status )
    >R
    R@ _LIBPACOM.KEY-U @ LIBPI-RID-KEY-SIZE <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.VALUE-U @ PERSIST-REF-SIZE <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY1
    DUP PERSIST-REF-VALID? 0= IF DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.RECORD-REF PERSIST-REF-COPY
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.RECORD-REF
    R@ _LIBPACOM.SOURCE-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
    PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
        PSTORE-RECORD-PAYLOAD$
    2DUP LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE
        LIBPA-DOCUMENT-RECORD-SIZE MOVE

    R@ _LIBPACOM-DOCUMENT-CONTENT-REF
    R> DROP ;

: _LIBPACOM-DOCUMENT-BEGIN  ( context -- status )
    >R
    R@ _LIBPACOM-DOCUMENT-LOAD DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPACOM-BUILDER-BEGIN DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.ENTRY
        LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED = IF
        -1 R@ _LIBPACOM.ROW-ACTIVE !
        R> DROP LIBPA-S-OK EXIT
    THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.ENTRY
        LIBE.METADATA-U @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB
    R@ _LIBPACOM.BUILDER-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PSTORE-WORK @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB-WORK
    PBLOB-WRITE-BEGIN _LIBPA-PERSIST>STATUS
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    -1 R@ _LIBPACOM.ROW-ACTIVE !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-DOCUMENT-FINISH  ( context -- status )
    >R
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
        LIBPA-DOCUMENT-RECORD-SIZE MOVE
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.HISTORY-REF
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE _LIBPAD.CONTENT-REF
        PERSIST-REF-COPY
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE _LIBPAD.ENTRY
        LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED <> IF
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
            _LIBPAD.METADATA-BLOB
        PBLOB-COPY
        DUP IF _LIBPA-PERSIST>STATUS
            R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT
        THEN DROP
    THEN
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
        LIBPA-DOCUMENT-RECORD-SIZE
        LIBPA-DOCUMENT-RECORD-VALID? 0= IF
        LIBPA-S-CORRUPT R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT
    THEN
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.STAGE
    LIBPA-DOCUMENT-RECORD-SIZE
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.RECORD-REF
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-APPEND
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY0
    R@ _LIBPACOM.KEY-U @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.RECORD-REF
    PERSIST-REF-SIZE _LIBPIX-RID-DIRECTORY
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-PUT
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM-BUILDER-PUBLISH
    DUP IF R> DROP EXIT THEN DROP
    0 R@ _LIBPACOM.ROW-ACTIVE !
    R> DROP LIBPA-S-OK ;

: _LIBPACOM-DOCUMENT-STEP  ( context -- status )
    >R
    R@ _LIBPACOM.ROW-ACTIVE @ 0= IF
        R@ _LIBPACOM-DOCUMENT-BEGIN DUP IF R> DROP EXIT THEN DROP
    THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.STAGE _LIBPAD.ENTRY
        LIBE.LIFECYCLE @ LIB-LIFECYCLE-TOMBSTONED = IF
        R@ _LIBPACOM-DOCUMENT-FINISH R> DROP EXIT
    THEN
    ['] _LIBPACOM-BLOB-SOURCE R@
    R@ _LIBPACOM.ALLOWANCE @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.BLOB-WORK
    PBLOB-WRITE-STEP
    DUP R@ _LIBPACOM.STATUS !
    DROP
    DUP R@ _LIBPACOM.USED !
    DROP
    DUP R@ _LIBPACOM.BLOB-DONE !
    DROP
    R@ _LIBPACOM.STATUS @
    DUP IF
        R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT
    THEN DROP
    R@ _LIBPACOM.BLOB-DONE @ IF
        R@ _LIBPACOM-DOCUMENT-FINISH
    ELSE
        LIBPA-S-OK
    THEN
    R> DROP ;

: _LIBPACOM-COLLECTION-ROW  ( context -- status )
    >R
    R@ _LIBPACOM.KEY-U @ LIBPI-COLLECTION-KEY-SIZE <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.VALUE-U @ PERSIST-REF-SIZE <> IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY1
    DUP PERSIST-REF-VALID? 0= IF DROP R> DROP LIBPA-S-CORRUPT EXIT THEN
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.RECORD-REF PERSIST-REF-COPY
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.RECORD-REF
    R@ _LIBPACOM.SOURCE-ADAPTER @ _LIBPA-D.STORE @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
    PSTORE-READ-RECORD
    DUP IF _LIBPA-PERSIST>STATUS R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.PSTORE-WORK @
        PSTORE-RECORD-PAYLOAD$
    2DUP LIBPA-COLLECTION-RECORD-VALID? 0= IF
        2DROP R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.COLLECTION-STAGE
        LIBPA-COLLECTION-RECORD-SIZE MOVE

    R@ _LIBPACOM-BUILDER-BEGIN DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.COLLECTION-STAGE
    LIBPA-COLLECTION-RECORD-SIZE
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.RECORD-REF
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-APPEND
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY0
    R@ _LIBPACOM.KEY-U @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.RECORD-REF
    PERSIST-REF-SIZE _LIBPIX-COLLECTION-DIRECTORY
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-PUT
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM-BUILDER-PUBLISH
    R> DROP ;

: _LIBPACOM-INDEX-ROW  ( context -- status )
    >R
    R@ _LIBPACOM.TREE @ _LIBPACOM-INDEX-TREE? 0= IF
        R> DROP LIBPA-S-CORRUPT EXIT
    THEN
    R@ _LIBPACOM-BUILDER-BEGIN DUP IF R> DROP EXIT THEN DROP
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY0
    R@ _LIBPACOM.KEY-U @
    R@ _LIBPACOM.SOURCE-WORK @ _LIBPIX.KEY1
    R@ _LIBPACOM.VALUE-U @
    R@ _LIBPACOM.TREE @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-PUT
    DUP IF R@ _LIBPACOM-BUILDER-ABORT R> DROP EXIT THEN DROP
    R@ _LIBPACOM-BUILDER-PUBLISH
    R> DROP ;

: _LIBPACOM-DISPATCH-ROW  ( context -- status )
    DUP _LIBPACOM.PHASE @ CASE
        _LIBPACOM-PHASE-HISTORY OF _LIBPACOM-HISTORY-STEP ENDOF
        _LIBPACOM-PHASE-DOCUMENT OF _LIBPACOM-DOCUMENT-STEP ENDOF
        _LIBPACOM-PHASE-COLLECTION OF _LIBPACOM-COLLECTION-ROW ENDOF
        _LIBPACOM-PHASE-INDEX OF _LIBPACOM-INDEX-ROW ENDOF
        2DROP LIBPA-S-CORRUPT
    ENDCASE ;

: _LIBPACOM-STEP-ARGS?
  ( source-root builder-store builder-pstore-work allowance context -- flag )
    >R
    DUP 0> 0= IF _LIBPA-DROP4 R> DROP 0 EXIT THEN
    3 PICK R@ _LIBPACOM-SOURCE-ROOT? 0= IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    2 PICK R@ _LIBPACOM.BUILDER-ADAPTER @ _LIBPA-D.STORE @ <> IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    1 PICK R@ _LIBPACOM.BUILDER-WORK @
        _LIBPIX.PSTORE-WORK @ <> IF
        _LIBPA-DROP4 R> DROP 0 EXIT
    THEN
    _LIBPA-DROP4 R> DROP -1 ;

: _LIBPACOM-STEP-RUN  ( context -- done? bytes-used status )
    >R
    R@ _LIBPACOM.STATE @ _LIBPACOM-STATE-DONE = IF
        R> DROP -1 0 LIBPA-S-OK EXIT
    THEN
    R@ _LIBPACOM.STATE @ _LIBPACOM-STATE-BOUND = IF
        R@ _LIBPACOM-CAPTURE-SOURCE DUP IF
            R> DROP 0 0 ROT EXIT
        THEN DROP
    THEN
    BEGIN
        R@ _LIBPACOM.STATE @ _LIBPACOM-STATE-DONE <>
    WHILE
        R@ _LIBPACOM.ROW-ACTIVE @ 0= IF
            R@ _LIBPACOM-NEXT-ROW
            DUP LIBPA-S-NOT-FOUND = IF
                DROP R@ _LIBPACOM-NEXT-PHASE
            ELSE
                DUP IF R> DROP 0 0 ROT EXIT THEN DROP
            THEN
        THEN
        R@ _LIBPACOM.STATE @ _LIBPACOM-STATE-DONE = IF
            R> DROP -1 0 LIBPA-S-OK EXIT
        THEN
        R@ _LIBPACOM.ROW-ACTIVE @
        R@ _LIBPACOM.ROW-READY @ OR IF
            R@ _LIBPACOM.PHASE @ DUP _LIBPACOM-PHASE-HISTORY =
            SWAP _LIBPACOM-PHASE-DOCUMENT = OR IF
                R@ _LIBPACOM-DISPATCH-ROW
                DUP IF R> DROP 0 0 ROT EXIT THEN DROP
                0 R@ _LIBPACOM.ROW-READY !
                R@ _LIBPACOM.USED @
                R> DROP 0 SWAP LIBPA-S-OK EXIT
            THEN
            R@ _LIBPACOM-DISPATCH-ROW
            DUP IF R> DROP 0 0 ROT EXIT THEN DROP
            0 R@ _LIBPACOM.ROW-READY !
            R> DROP 0 0 LIBPA-S-OK EXIT
        THEN
    REPEAT
    R> DROP -1 0 LIBPA-S-OK ;

: _LIBPACOM-STEP-CATCH  ( context -- done? bytes-used status )
    ['] _LIBPACOM-STEP-RUN CATCH
    DUP IF
        >R DROP R> DROP 0 0 LIBPA-S-FAULT
    ELSE
        DROP
    THEN ;

: _LIBPACOM-STEP  ( source-root builder-store builder-work allowance context -- done? used status )
    DUP LIBPA-COMPACTION-CONTEXT-VALID? 0= IF
        _LIBPA-DROP5 0 0 PERSIST-S-INVALID EXIT
    THEN
    >R
    3 PICK 3 PICK 3 PICK 3 PICK R@
        _LIBPACOM-STEP-ARGS? 0= IF
        _LIBPA-DROP4 R> DROP 0 0 PERSIST-S-INVALID EXIT
    THEN
    DUP R@ _LIBPACOM.ALLOWANCE !
    0 R@ _LIBPACOM.USED !
    0 R@ _LIBPACOM.BLOB-DONE !
    _LIBPA-DROP4
    R@ _LIBPACOM-STEP-CATCH
    DUP R@ _LIBPACOM.STATUS !
    R> DROP ;

: _LIBPACOM-ROOT-PAGE  ( exact-generation context -- status )
    >R
    DUP 0> 0= IF DROP R> DROP LIBPA-S-INVALID EXIT THEN
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        PERSIST-PAGE-PAYLOAD-SIZE 0 FILL
    _LIBPA-ROOT-MAGIC
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE _LIBPAR-MAGIC + 8 MOVE
    R@ _LIBPACOM.LOGICAL @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-LOGICAL-GENERATION + !
    R@ _LIBPACOM.MUTATION @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-MUTATION-SEQUENCE + !
    R@ _LIBPACOM.DOCUMENTS @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-DOCUMENT-COUNT + !
    R@ _LIBPACOM.COLLECTIONS @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-COLLECTION-COUNT + !
    R@ _LIBPACOM.MEMBERSHIPS @
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-MEMBERSHIP-COUNT + !
    R@ _LIBPACOM.BOOTSTRAP
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-BOOTSTRAP-ID + RID-COPY
    0
    BEGIN DUP _LIBPIX-TREE-COUNT < WHILE
        DUP R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-ROOT
        2 PICK
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.TEMP-ROOT
        3 PICK R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX-TREE
        PBTREE-ROOT-REBASE
        DUP IF
            _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
        THEN DROP
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.TEMP-ROOT
        OVER PBTREE-ROOT-SIZE *
        R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
            _LIBPAR-ROOTS + +
        PBTREE-ROOT-COPY
        DUP IF
            _LIBPA-PERSIST>STATUS >R 2DROP R> R> DROP EXIT
        THEN DROP
        1+
    REPEAT
    DROP
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
        _LIBPAR-RECLAIM-STATE + RECLAIM-STATE-SIZE
    RECLAIM-EMPTY-STATE-FOR-GENERATION _LIBPA-PERSIST>STATUS
    R> DROP ;

: _LIBPACOM-FINALIZE-ABORT
  ( primary-status builder-store builder-pstore-work -- final-status )
    >R
    R@ PSTORE-PROPOSED-ROOT@ IF
        DUP R@ PSTORE-ABORT
        DUP IF
            >R 2DROP R>
        ELSE
            DROP
            DROP
        THEN
    ELSE
        DROP
    THEN
    R> DROP ;

: _LIBPACOM-FINALIZE-RUN
  ( exact-generation builder-store builder-pstore-work context -- status )
    >R
    R@ _LIBPACOM.STATE @ _LIBPACOM-STATE-DONE <> IF
        _LIBPA-DROP3 R> DROP LIBPA-S-CONFLICT EXIT
    THEN
    2 PICK R@ _LIBPACOM-ROOT-PAGE
    DUP IF >R _LIBPA-DROP3 R> R> DROP EXIT THEN DROP
    DUP R@ _LIBPACOM.BUILDER-WORK @
        _LIBPIX.PSTORE-WORK @ <> IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    1 PICK R@ _LIBPACOM.BUILDER-ADAPTER @
        _LIBPA-D.STORE @ <> IF
        _LIBPA-DROP3 R> DROP LIBPA-S-INVALID EXIT
    THEN
    1 PICK 1 PICK PSTORE-BEGIN
    DUP IF >R _LIBPA-DROP3 R> R> DROP EXIT THEN DROP
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.PAGE
    PERSIST-PAGE-PAYLOAD-SIZE
    3 PICK 3 PICK PSTORE-APPEND-PAGE
    DUP IF
        _LIBPA-PERSIST>STATUS DUP R@ _LIBPACOM.STATUS ! DROP
        DROP
        R@ _LIBPACOM.STATUS @ 2 PICK 2 PICK
            _LIBPACOM-FINALIZE-ABORT
        >R _LIBPA-DROP3 R> R> DROP EXIT
    THEN DROP
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.APP-ROOT-PAGE !
    R@ _LIBPACOM.BUILDER-WORK @ _LIBPIX.APP-ROOT-PAGE @
    2 PICK 2 PICK PSTORE-APPLICATION-ROOT!
    DUP IF
        _LIBPA-PERSIST>STATUS DUP R@ _LIBPACOM.STATUS ! DROP
        R@ _LIBPACOM.STATUS @ 2 PICK 2 PICK
            _LIBPACOM-FINALIZE-ABORT
        >R _LIBPA-DROP3 R> R> DROP EXIT
    THEN DROP
    1 PICK 1 PICK PSTORE-COMMIT _LIBPA-PERSIST>STATUS
    >R _LIBPA-DROP3 R> R> DROP ;

: _LIBPACOM-FINALIZE  ( exact-generation builder-store builder-work context -- status )
    DUP LIBPA-COMPACTION-CONTEXT-VALID? 0= IF
        _LIBPA-DROP4 PERSIST-S-INVALID EXIT
    THEN
    >R
    1 PICK R@ _LIBPACOM.BUILDER-ADAPTER @ _LIBPA-D.STORE @ <> IF
        _LIBPA-DROP3 R> DROP PERSIST-S-INVALID EXIT
    THEN
    DUP R@ _LIBPACOM.BUILDER-WORK @
        _LIBPIX.PSTORE-WORK @ <> IF
        _LIBPA-DROP3 R> DROP PERSIST-S-INVALID EXIT
    THEN
    R@ _LIBPACOM-FINALIZE-RUN
    DUP R@ _LIBPACOM.STATUS !
    R> DROP ;

: LIBPA-COMPACTION-STEP-XT  ( -- xt )
    ['] _LIBPACOM-STEP ;

: LIBPA-COMPACTION-FINALIZE-XT  ( -- xt )
    ['] _LIBPACOM-FINALIZE ;
